INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d76152bd-203c-404f-895a-3ef6220baf72', '晦日同志昆明池汎舟', '晦日同志昆明池汎舟', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["靈沼疑河漢，蕭條見斗牛。","煙生知岸近，水淨覺天秋。","落月低前樹，清輝滿去舟。","興因孤嶼起，心爲白蘋留。","曉吹兼漁笛，閑雲伴客愁。","龍津如可上，長嘯且乘流。"]', '["靈沼疑河漢，蕭條见斗牛。","煙生知岸近，水淨覺天秋。","落月低前樹，清輝满去舟。","兴因孤嶼起，心爲白蘋留。","晓吹兼漁笛，闲云伴客愁。","龙津如可上，长嘯且乘流。"]', '诗', 'shi', '', NULL, '晦日同志昆明池汎舟 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d19ebe2a-3d00-491b-9e8d-807ea30aa9af', '禮闈階前春草生', '禮闈階前春草生', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["河畔雖同色，南宮淑景先。","微開曳履處，常對講經前。","得地風塵隔，依林雨露偏。","已逢霜候改，初寄日華妍。","影與叢蘭雜，榮將衆卉連。","哲人如不薙，生意在芳年。"]', '["河畔雖同色，南宮淑景先。","微开曳履处，常对講經前。","得地风塵隔，依林雨露偏。","已逢霜候改，初寄日华妍。","影與叢蘭杂，榮將衆卉連。","哲人如不薙，生意在芳年。"]', '诗', 'shi', '', NULL, '禮闈階前春草生 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e76d5e57-ed32-492f-955b-9d9f095759db', '秋風生桂枝', '秋风生桂枝', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["寒桂秋風動，蕭蕭自一枝。","方將擊林變，不假舞松移。","散翠幽花落，搖青密葉離。","哀猨驚助褭，花露滴爭垂。","遺韻連波聚，流音萬木隨。","常聞小山裏，逋客最先知。"]', '["寒桂秋风动，蕭蕭自一枝。","方將擊林变，不假舞松移。","散翠幽花落，搖青密葉離。","哀猨驚助褭，花露滴爭垂。","遺韻連波聚，流音万木隨。","常闻小山裏，逋客最先知。"]', '诗', 'shi', '', NULL, '秋風生桂枝 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5c9128d-f819-4a62-929f-60e8daac6d26', '幽人折芳桂', '幽人折芳桂', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["厚地生芳桂，遙林聳榦長。","葉開風裏色，花吐月中光。","曙鳥啼餘翠，幽人愛早芳。","動時垂露滴，攀處拂衣香。","古調聲猶苦，孤高力自強。","一枝終是折，榮耀在東堂。"]', '["厚地生芳桂，遙林聳榦长。","葉开风裏色，花吐月中光。","曙鸟啼餘翠，幽人愛早芳。","动时垂露滴，攀处拂衣香。","古調声猶苦，孤高力自強。","一枝終是折，榮耀在东堂。"]', '诗', 'shi', '', NULL, '幽人折芳桂 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50614ad6-187f-4b43-bf6b-321bcb48bb2f', '霜菊', '霜菊', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["秋盡北風去，律移寒氣肅。","淅瀝降繁霜，離披委殘菊。","華滋尚照灼，幽氣含紛郁。","的的冒空園，萋萋被幽谷。","騷人有遺詠，陶令曾盈掬。","儻使懷袖中，猶堪襲餘馥。"]', '["秋尽北风去，律移寒氣肅。","淅瀝降繁霜，離披委殘菊。","华滋尚照灼，幽氣含紛郁。","的的冒空园，萋萋被幽谷。","騷人有遺詠，陶令曾盈掬。","儻使懷袖中，猶堪襲餘馥。"]', '诗', 'shi', '', NULL, '霜菊 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a665d08f-4042-43ff-9349-4862435449c1', '金谷園花發懷古', '金谷园花發懷古', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["春風生梓澤，遲景映花林。","欲問當時事，因傷此日心。","繁華人已歿，桃李意何深。","澗咽歌聲在，雲歸蓋影沈。","地形同萬古，笑價失千金。","遺跡應無限，芳菲不可尋。"]', '["春风生梓澤，遲景映花林。","欲问當时事，因傷此日心。","繁华人已歿，桃李意何深。","澗咽歌声在，云归蓋影沈。","地形同万古，笑價失千金。","遺跡應無限，芳菲不可尋。"]', '诗', 'shi', '', NULL, '金谷園花發懷古 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90e592bb-5f0c-457a-a957-05a45de95677', '驪龍', '驪龙', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["有美爲鱗族，潛蟠得所從。","標奇初韞寶，表智即稱龍。","大壑長千里，深泉固九重。","奮髯雲乍起，矯首浪還衝。","荀氏傳高譽，莊生冀絕蹤。","仍知流淚在，何幸此相逢。"]', '["有美爲鱗族，潛蟠得所從。","標奇初韞寶，表智即稱龙。","大壑长千里，深泉固九重。","奮髯云乍起，矯首浪還衝。","荀氏傳高譽，莊生冀絕蹤。","仍知流泪在，何幸此相逢。"]', '诗', 'shi', '', NULL, '驪龍 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22b71614-1f07-4576-a51e-5afc6ab2cd5d', '鶴鳴九臯', '鹤鳴九臯', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["胎化呈仙質，長鳴在九臯。","排空散清唳，映日委霜毛。","萬里思寥廓，千山望鬱陶。","香凝光不見，風積韻彌高。","鳳侶攀何及，雞羣思忽勞。","昇天如有應，飛舞出蓬蒿。"]', '["胎化呈仙質，长鳴在九臯。","排空散清唳，映日委霜毛。","万里思寥廓，千山望鬱陶。","香凝光不见，风積韻彌高。","鳳侶攀何及，雞羣思忽勞。","昇天如有應，飞舞出蓬蒿。"]', '诗', 'shi', '', NULL, '鶴鳴九臯 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1e218e3-02e1-409c-a94f-b274f233d608', '霜隼下晴臯', '霜隼下晴臯', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["九臯霜氣勁，翔隼下初晴。","風動閑雲卷，星馳白草平。","稜稜方厲疾，肅肅自縱橫。","掠地秋毫迥，投身逸翮輕。","高墉全失影，逐雀作飛聲。","薄暮寒郊外，悠悠萬里情。"]', '["九臯霜氣勁，翔隼下初晴。","风动闲云卷，星驰白草平。","稜稜方厲疾，肅肅自縱橫。","掠地秋毫迥，投身逸翮轻。","高墉全失影，逐雀作飞声。","薄暮寒郊外，悠悠万里情。"]', '诗', 'shi', '', NULL, '霜隼下晴臯 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df60674c-73ca-432a-a47a-d566f928513d', '河鯉登龍門', '河鯉登龙门', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["年久還求變，今來有所從。","得名當是鯉，無點可成龍。","備歷艱難徧，因期造化容。","泥沙寧不阻，釣餌莫相逢。","擊浪因成勢，纖鱗莫繼蹤。","若令搖尾去，雨露此時濃。"]', '["年久還求变，今来有所從。","得名當是鯉，無点可成龙。","備歷艱难徧，因期造化容。","泥沙寧不阻，釣餌莫相逢。","擊浪因成勢，纖鱗莫繼蹤。","若令搖尾去，雨露此时濃。"]', '诗', 'shi', '', NULL, '河鯉登龍門 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cee0f10c-161a-41cd-86b3-2d42886fdaf3', '改九子山爲九華山聯句', '改九子山爲九华山聯句', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["妙有分二氣，靈山開九華。","層標遏遲日，半壁明朝霞。","積雪曜陰壑，飛流歕陽崖。","青瑩玉樹色，縹緲羽人家。"]', '["妙有分二氣，靈山开九华。","層標遏遲日，半壁明朝霞。","積雪曜陰壑，飞流歕陽崖。","青瑩玉樹色，縹緲羽人家。"]', '诗', 'shi', '', NULL, '改九子山爲九華山聯句 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('415052da-08ac-43f0-bb9b-9ce383e55bf0', '夏夜李尚書筵送宇文石首赴縣聯句', '夏夜李尚书筵送宇文石首赴縣聯句', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["愛客尚書貴，之官宅相賢。","酒香傾坐側，帆影駐江邊。","翟表郎官瑞，鳧看令宰仙。","雨稀雲葉斷，夜久燭花偏。","數語敧紗帽，高文擲彩箋。","興饒行處樂，離惜醉中眠。","單父長多暇，河陽實少年。","客居逢自出，爲別幾悽然。"]', '["愛客尚书貴，之官宅相賢。","酒香傾坐側，帆影駐江邊。","翟表郎官瑞，鳧看令宰仙。","雨稀云葉斷，夜久燭花偏。","數語敧紗帽，高文擲彩箋。","兴饒行处乐，離惜醉中眠。","單父长多暇，河陽實少年。","客居逢自出，爲別幾悽然。"]', '诗', 'shi', '', NULL, '夏夜李尚書筵送宇文石首赴縣聯句 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e491ab0-edcf-41b9-8c91-fa4a9e61a96c', '登峴山觀李左相石尊聯句', '登峴山观李左相石尊聯句', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["李公登飲處，因石爲窪尊。","人事歲年改，峴山今古存。","榛蕪掩前跡，苔蘚餘舊痕。","叔子尚遺德，山公此迴軒。","維舟陪高興，感昔情彌敦。","藹藹賢哲事，依依離別言。","嶇嶔橫道周，迢遰連山根。","餘烈曖林野，衆芳揖蘭蓀。","德暉映巖足，勝賞延高原。","遠水明匹練，因晴見吳門。","陪遊追盛美，揆德欣討論。","器有成形用，功資造化元。","流霞方泔淡，別鶴遽翩飜。","舊規傾逸賞，新興麗初暾。","醉後接㒿倒，歸時騶騎喧。","遲迴向遺跡，離別益傷魂。","覽事古興屬，送人歸思繁。","懷賢久徂謝，贈遠空攀援。","八座欽懿躅，高名播乾坤。","松深引閑步，葛弱供險捫。","花氣酒中馥，雲華衣上屯。","森沈列湖樹，牢落望郊園。","白日半巖岫，清風滿丘樊。","旌麾間翠幄，簫鼓來朱轓。","閑路躡雲影，清心澄水源。","萍連浦中嶼，竹繞山下村。","景落全谿暗，煙凝半嶺昏。","去日往如復，換年涼代溫。","登臨繼風騷，義激舊府恩。"]', '["李公登饮处，因石爲窪尊。","人事歲年改，峴山今古存。","榛蕪掩前跡，苔蘚餘旧痕。","叔子尚遺德，山公此迴軒。","維舟陪高兴，感昔情彌敦。","藹藹賢哲事，依依離別言。","嶇嶔橫道周，迢遰連山根。","餘烈曖林野，衆芳揖蘭蓀。","德暉映巖足，勝賞延高原。","远水明匹練，因晴见吳门。","陪游追盛美，揆德欣討論。","器有成形用，功資造化元。","流霞方泔淡，別鹤遽翩飜。","旧規傾逸賞，新兴丽初暾。","醉後接㒿倒，归时騶騎喧。","遲迴向遺跡，離別益傷魂。","覽事古兴屬，送人归思繁。","懷賢久徂謝，贈远空攀援。","八座欽懿躅，高名播乾坤。","松深引闲步，葛弱供險捫。","花氣酒中馥，云华衣上屯。","森沈列湖樹，牢落望郊园。","白日半巖岫，清风满丘樊。","旌麾间翠幄，簫鼓来朱轓。","闲路躡云影，清心澄水源。","萍連浦中嶼，竹繞山下村。","景落全谿暗，煙凝半嶺昏。","去日往如复，換年涼代溫。","登臨繼风騷，義激旧府恩。"]', '诗', 'shi', '', NULL, '登峴山觀李左相石尊聯句 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca540fa1-8bdf-4128-b51a-355f70e94afd', '水堂送諸文士戲贈潘丞聯句', '水堂送諸文士戲贈潘丞聯句', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["居人未可散，上客須留著。","莫唱阿嚲迴，應云夜半樂。","詩教刻燭賦，酒任連盤酌。","從他白眼看，終戀青山郭。","林栖非姓許，寺住那名約。","會異永和年，才同建安作。","何煩問更漏，但遣催弦索。","共說長句能，皆言早歸惡。","那知殊出處，還得同笑謔。","雅韻雖暫歡，禪心肯拋却。","一宿同高會，幾人歸下若。","簾開北陸風，燭焯南枝鵲。","文場苦叨竊，釣渚甘漂泊。","弱質幸見容，菲才誠重諾。"]', '["居人未可散，上客須留著。","莫唱阿嚲迴，應云夜半乐。","诗教刻燭賦，酒任連盤酌。","從他白眼看，終戀青山郭。","林栖非姓許，寺住那名約。","會異永和年，才同建安作。","何煩问更漏，但遣催弦索。","共说长句能，皆言早归惡。","那知殊出处，還得同笑謔。","雅韻雖暫歡，禪心肯拋却。","一宿同高會，幾人归下若。","簾开北陸风，燭焯南枝鵲。","文場苦叨竊，釣渚甘漂泊。","弱質幸见容，菲才誠重諾。"]', '诗', 'shi', '', NULL, '水堂送諸文士戲贈潘丞聯句 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('212bfdd6-0a39-4ebc-b923-6053c4288e21', '與耿湋水亭詠風聯句', '與耿湋水亭詠风聯句', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["清風何處起，拂檻復縈洲。","回入飄華幕，輕來疊晚流。","桃竹今已展，羽翣且從收。","經竹吹彌切，過松韻更幽。","直散青蘋末，偏隨白浪頭。","山山催雨過，浦浦發行舟。","動樹蟬爭噪，開簾客罷愁。","度弦方解慍，臨水已迎秋。","涼爲開襟至，清因作頌留。","周回隨遠夢，騷屑滿離憂。","豈獨銷繁暑，偏能入迥樓。","王風今若此，誰不荷明休。"]', '["清风何处起，拂檻复縈洲。","回入飄华幕，轻来叠晚流。","桃竹今已展，羽翣且從收。","經竹吹彌切，過松韻更幽。","直散青蘋末，偏隨白浪头。","山山催雨過，浦浦發行舟。","动樹蟬爭噪，开簾客罷愁。","度弦方解慍，臨水已迎秋。","涼爲开襟至，清因作頌留。","周回隨远梦，騷屑满離憂。","豈独銷繁暑，偏能入迥楼。","王风今若此，誰不荷明休。"]', '诗', 'shi', '', NULL, '與耿湋水亭詠風聯句 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9019b3c-87a2-4698-ae6a-4de907ee9cc4', '又溪館聽蟬聯句', '又溪館听蟬聯句', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["高樹多涼吹，疎蟬足斷聲。","已催居客感，更使別人驚。","晚夏猶知急，新秋別有情。","危湍和不似，細管學難成。","當斅附金重，無貪曜火明。","青松四面落，白髮一重生。","向夕音彌厲，迎風翼更輕。","單嘶出迥樹，餘響思空城。","嘒唳松間坐，蕭寥竹裏行。","如何長飲露，高潔未能名。"]', '["高樹多涼吹，疎蟬足斷声。","已催居客感，更使別人驚。","晚夏猶知急，新秋別有情。","危湍和不似，細管学难成。","當斅附金重，無貪曜火明。","青松四面落，白髮一重生。","向夕音彌厲，迎风翼更轻。","單嘶出迥樹，餘响思空城。","嘒唳松间坐，蕭寥竹裏行。","如何长饮露，高潔未能名。"]', '诗', 'shi', '', NULL, '又溪館聽蟬聯句 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd9065e4-e444-45f2-8126-4d5c6b8ba4f1', '送耿湋拾遺聯句', '送耿湋拾遺聯句', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["堯舜逢明主，嚴徐得侍臣。","分行接三事，高興柏梁新。","楚國千山道，秦城萬里人。","鏡中看齒髮，河上有煙塵。","望闕飛青翰，朝天憶紫宸。","喜來歡宴洽，愁去詠歌頻。","顧盼情非一，睽攜處亦頻。","吳興賢太守，臨水最殷勤。"]', '["堯舜逢明主，嚴徐得侍臣。","分行接三事，高兴柏梁新。","楚国千山道，秦城万里人。","镜中看齒髮，河上有煙塵。","望闕飞青翰，朝天憶紫宸。","喜来歡宴洽，愁去詠歌頻。","顧盼情非一，睽携处亦頻。","吳兴賢太守，臨水最殷勤。"]', '诗', 'shi', '', NULL, '送耿湋拾遺聯句 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a565fcb7-9e68-4ded-b859-c1a5a0a86d30', '五言月夜啜茶聯句', '五言月夜啜茶聯句', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["泛花邀坐客，代飲引情言。","醒酒宜華席，留僧想獨園。","不須攀月桂，何假樹庭萱。","御史秋風勁，尚書北斗尊。","流華淨肌骨，疏瀹滌心原。","不似春醪醉，何辭綠菽繁。","素瓷傳靜夜，芳氣滿閑軒。"]', '["泛花邀坐客，代饮引情言。","醒酒宜华席，留僧想独园。","不須攀月桂，何假樹庭萱。","御史秋风勁，尚书北斗尊。","流华淨肌骨，疏瀹滌心原。","不似春醪醉，何辞綠菽繁。","素瓷傳静夜，芳氣满闲軒。"]', '诗', 'shi', '', NULL, '五言月夜啜茶聯句 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb18d8b0-a09a-4511-8bd2-0415c73204ee', '五言夜宴詠燈聯句', '五言夜宴詠灯聯句', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["桂酒牽詩興，蘭釭照客情。","詎慙珠乘朗，不讓月輪明。","破暗光初白，浮雲色轉清。","帶花疑在樹，比燎欲分庭。","顧己慙微照，開簾識近汀。"]', '["桂酒牽诗兴，蘭釭照客情。","詎慙珠乘朗，不讓月輪明。","破暗光初白，浮云色轉清。","带花疑在樹，比燎欲分庭。","顧己慙微照，开簾識近汀。"]', '诗', 'shi', '', NULL, '五言夜宴詠燈聯句 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38f5ca4e-d53f-4c40-872d-a07eaf8d5c47', '三言喜皇甫侍御見過南樓玩月', '三言喜皇甫侍御见過南楼玩月', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["喜嘉客，闢前軒。","天月淨，水雲昏。","雁聲苦，蟾影寒。","聞裛浥，滴檀欒。","歡宴處，江湖間。","卷翠幕，吟嘉句。","恨清光，留不住。","高駕動，清角催。","惜歸去，重裴回。","露欲晞，客將醉。","猶宛轉，照深意。"]', '["喜嘉客，闢前軒。","天月淨，水云昏。","雁声苦，蟾影寒。","闻裛浥，滴檀欒。","歡宴处，江湖间。","卷翠幕，吟嘉句。","恨清光，留不住。","高駕动，清角催。","惜归去，重裴回。","露欲晞，客將醉。","猶宛轉，照深意。"]', '诗', 'shi', '', NULL, '三言喜皇甫侍御見過南樓玩月 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('100f1b25-d4bc-4d80-9f55-040330a1fd83', '七言重聯句', '七言重聯句', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["頃持憲簡推高步，獨占詩流橫素波。","不是中情深惠好，誰能千里遠經過。","詩書宛似陪康樂，少長還同宴永和。","夜酌此時看碾玉，晨趨幾日重鳴珂。","萬井更深空寂寞，千方霧起隱嵯峨。","熒熒遠火分漁浦，歷歷寒枝露鳥窠。","漢朝舊學君公隱，魯國今從弟子科。","只自傾心慙煦濡，何曾將口恨蹉跎。","獨賞謝吟山照耀，共知殷歎樹婆娑。","華轂苦嫌雲路隔，衲衣長向雪峰何。"]', '["頃持憲簡推高步，独占诗流橫素波。","不是中情深惠好，誰能千里远經過。","诗书宛似陪康乐，少长還同宴永和。","夜酌此时看碾玉，晨趨幾日重鳴珂。","万井更深空寂寞，千方霧起隐嵯峨。","熒熒远火分漁浦，歷歷寒枝露鸟窠。","漢朝旧学君公隐，魯国今從弟子科。","只自傾心慙煦濡，何曾將口恨蹉跎。","独賞謝吟山照耀，共知殷歎樹婆娑。","华轂苦嫌云路隔，衲衣长向雪峰何。"]', '诗', 'shi', '', NULL, '七言重聯句 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3279f99d-f0ab-4c4f-9155-eb2bf4a81145', '五言送李侍御聯句', '五言送李侍御聯句', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["吾友駐行輪，遲遲惜上春。","東西出餞路，惆悵獨歸人。","歡會期他日，驅馳恨此身。","須知貢公望，從此願相因。"]', '["吾友駐行輪，遲遲惜上春。","东西出餞路，惆悵独归人。","歡會期他日，驱驰恨此身。","須知貢公望，從此願相因。"]', '诗', 'shi', '', NULL, '五言送李侍御聯句 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36e556d5-dcc6-4cd0-a80c-1c71b044a699', '五言翫初月重遊聯句', '五言翫初月重游聯句', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["春谿與岸平，初月出谿明。","璧彩寒仍潔，金波夜轉清。","孤光遠近滿，練色往來輕。","望望隨蘭櫂，依依出柳城。"]', '["春谿與岸平，初月出谿明。","璧彩寒仍潔，金波夜轉清。","孤光远近满，練色往来轻。","望望隨蘭櫂，依依出柳城。"]', '诗', 'shi', '', NULL, '五言翫初月重遊聯句 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e432373-9952-4686-8ab2-4cabc8c1b3a2', '五言重送橫飛聯句', '五言重送橫飞聯句', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["春田草未齊，春水滿長溪。","出餞風初暖，攀光日漸西。","歸期江上遠，別思月中迷。"]', '["春田草未齊，春水满长溪。","出餞风初暖，攀光日漸西。","归期江上远，別思月中迷。"]', '诗', 'shi', '', NULL, '五言重送橫飛聯句 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bdf81be-dfc6-4b8b-b88a-87664c4704e8', '五言夜集聯句', '五言夜集聯句', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["寒花護月色，墜葉占風音。","茲夕無塵慮，高雲共片心。"]', '["寒花護月色，墜葉占风音。","茲夕無塵慮，高云共片心。"]', '诗', 'shi', '', NULL, '五言夜集聯句 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c1a6976-1e2e-4570-bd5e-299cdf32dbf0', '三言擬五雜組聯句', '三言擬五杂組聯句', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["五雜組，盤上葅。","往復還，頭嬾梳。","不得已，罾裏魚。","五雜組，郊外蕪。","往復還，櫪上駒。","不得已，谷中愚。","五雜組，繡與錦。","往復還，興又寢。","不得已，病伏枕。","五雜組，酒與肉。","往復還，東籬菊。","不得已，醉便宿。","五雜組，闤闠間。","往復還，門上關。","不得已，鬢毛斑。","五雜組，繡紋線。","往復還，春來燕。","不得已，入征戰。"]', '["五杂組，盤上葅。","往复還，头嬾梳。","不得已，罾裏鱼。","五杂組，郊外蕪。","往复還，櫪上駒。","不得已，谷中愚。","五杂組，繡與錦。","往复還，兴又寢。","不得已，病伏枕。","五杂組，酒與肉。","往复還，东籬菊。","不得已，醉便宿。","五杂組，闤闠间。","往复還，门上关。","不得已，鬢毛斑。","五杂組，繡紋線。","往复還，春来燕。","不得已，入征戰。"]', '诗', 'shi', '', NULL, '三言擬五雜組聯句 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a847a272-c46f-4b77-b88b-e5deda4210cf', '三言重擬五雜組聯句', '三言重擬五杂組聯句', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["五雜組，四豪客。","往復還，阡與陌。","不得已，長沙謫。","五雜組，五辛盤。","往復還，馬上鞍。","不得已，左降官。","五雜組，甘鹹醋。","往復還，烏與兔。","不得已，韶光度。","五雜組，五色絲。","往復還，回文詩。","不得已，失喜期。"]', '["五杂組，四豪客。","往复還，阡與陌。","不得已，长沙謫。","五杂組，五辛盤。","往复還，马上鞍。","不得已，左降官。","五杂組，甘鹹醋。","往复還，烏與兔。","不得已，韶光度。","五杂組，五色絲。","往复還，回文诗。","不得已，失喜期。"]', '诗', 'shi', '', NULL, '三言重擬五雜組聯句 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92a91c9f-b861-457d-8f64-201de001ee13', '七言大言聯句', '七言大言聯句', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["高歌閬風步瀛洲，燂鵬爚鯤餐未休。","四方上下無外頭，一啜頓涸滄溟流。"]', '["高歌閬风步瀛洲，燂鵬爚鯤餐未休。","四方上下無外头，一啜頓涸滄溟流。"]', '诗', 'shi', '', NULL, '七言大言聯句 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21219b75-ade8-45fc-ab22-b8764ecd51e9', '七言小言聯句', '七言小言聯句', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["長路迢遙吞吐絲，蟭螟蚊睫察難知。"]', '["长路迢遙吞吐絲，蟭螟蚊睫察难知。"]', '诗', 'shi', '', NULL, '七言小言聯句 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c1c5d5b-fdca-41e1-b244-4c6443c6287a', '七言樂語聯句', '七言乐語聯句', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["苦河既濟真僧喜，新知滿座笑相視。","戍客歸來見妻子，學生放假偷向市。"]', '["苦河既濟真僧喜，新知满座笑相視。","戍客归来见妻子，学生放假偷向市。"]', '诗', 'shi', '', NULL, '七言樂語聯句 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a94b5f2c-ecc9-4e11-a901-731efd3b0f30', '七言嚵語聯句', '七言嚵語聯句', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["拈䭔舐指不知休，欲炙侍立涎交流。","過屠大嚼肯知羞，食店門外強淹留。"]', '["拈䭔舐指不知休，欲炙侍立涎交流。","過屠大嚼肯知羞，食店门外強淹留。"]', '诗', 'shi', '', NULL, '七言嚵語聯句 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1109c90a-36a4-4e56-a6f2-0f01062b3a20', '七言滑語聯句', '七言滑語聯句', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["雨裏下山蹋榆皮，莓苔石橋步難移。","蕪荑醬醋喫煮葵，縫靴蠟線油塗錐。","急逢龍背須且騎。"]', '["雨裏下山蹋榆皮，莓苔石橋步难移。","蕪荑醬醋喫煮葵，縫靴蠟線油塗錐。","急逢龙背須且騎。"]', '诗', 'shi', '', NULL, '七言滑語聯句 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a974cf5f-cfdf-4d27-8a0c-52f5d3f72565', '七言醉語聯句', '七言醉語聯句', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["逢糟遇麯便酩酊，覆車墜馬皆不醒。","倒著接㒿髮垂領，狂心亂語無人竝。"]', '["逢糟遇麯便酩酊，覆车墜马皆不醒。","倒著接㒿髮垂領，狂心亂語無人竝。"]', '诗', 'shi', '', NULL, '七言醉語聯句 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d351384-9f44-454f-b5b9-da9a1bf6b155', '建元寺晝公與崔秀才見過聯句與鄭奉禮部同作', '建元寺晝公與崔秀才见過聯句與鄭奉禮部同作', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["人閑宜歲晚，道者訪幽期。","獨與寒山別，行當暮雪時。","柏臺辭漢主，竹寺寄潛師。","荷策知君待，開門笑我遲。","暮階縣雨足，寒吹繞松枝。","理辯塵心妄，經分梵字疑。","久承黃紙詔，曾賦碧雲詩。","然諾驚相許，風流話所思。","筌忘心已默，磬發夜何其。","願結求羊侶，名山從所之。"]', '["人闲宜歲晚，道者訪幽期。","独與寒山別，行當暮雪时。","柏台辞漢主，竹寺寄潛師。","荷策知君待，开门笑我遲。","暮階縣雨足，寒吹繞松枝。","理辯塵心妄，經分梵字疑。","久承黄紙詔，曾賦碧云诗。","然諾驚相許，风流話所思。","筌忘心已默，磬發夜何其。","願結求羊侶，名山從所之。"]', '诗', 'shi', '', NULL, '建元寺晝公與崔秀才見過聯句與鄭奉禮部同作 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98c9c233-06c2-47de-8f9d-36b34fcc353d', '建元寺西院寄李員外縱聯句', '建元寺西院寄李員外縱聯句', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["寄隱霜臺客，相思粉署人。","誠知阡陌近，無奈別離頻。","夜色迷雙樹，鐘聲警四鄰。","散才徒仰鮑，歸夢遠知秦。","雨帶清笳發，花驚夕漏春。","招搖隨步錫，髣髴聽行輪。","要路推高足，空林寄一身。","盛名知獨擅，良會憶相親。","稍滌心中垢，都遺陌上塵。","今宵此堂集，何事少遺民。"]', '["寄隐霜台客，相思粉署人。","誠知阡陌近，無奈別離頻。","夜色迷雙樹，鐘声警四鄰。","散才徒仰鲍，归梦远知秦。","雨带清笳發，花驚夕漏春。","招搖隨步錫，髣髴听行輪。","要路推高足，空林寄一身。","盛名知独擅，良會憶相親。","稍滌心中垢，都遺陌上塵。","今宵此堂集，何事少遺民。"]', '诗', 'shi', '', NULL, '建元寺西院寄李員外縱聯句 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78fb6cf1-def1-4f59-9e4a-d878dfa3a72b', '中元日鮑端公宅遇吳天師聯句', '中元日鲍端公宅遇吳天師聯句', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["道流爲柱史，教戒下真仙。","共契中元會，初修內景篇。","遊方依地僻，卜室喜牆連。","寶笥開金籙，華池漱玉泉。","怪龍隨羽翼，青節降雲煙。","昔去遺丹竈，今來變海田。","養形奔二景，鍊骨度千年。","騎竹投陂裏，攜壺挂牖邊。","洞中嘗入靜，河上舊談玄。","伊洛笙歌遠，蓬壺日月偏。","青騾薊訓引，白犬伯陽牽。","法受相君後，心存象帝先。","道成能縮地，功滿欲升天。","何意迷孤性，含情戀數賢。"]', '["道流爲柱史，教戒下真仙。","共契中元會，初修內景篇。","游方依地僻，卜室喜牆連。","寶笥开金籙，华池漱玉泉。","怪龙隨羽翼，青節降云煙。","昔去遺丹竈，今来变海田。","養形奔二景，鍊骨度千年。","騎竹投陂裏，携壺挂牖邊。","洞中嘗入静，河上旧談玄。","伊洛笙歌远，蓬壺日月偏。","青騾薊訓引，白犬伯陽牽。","法受相君後，心存象帝先。","道成能縮地，功满欲升天。","何意迷孤性，含情戀數賢。"]', '诗', 'shi', '', NULL, '中元日鮑端公宅遇吳天師聯句 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ae3e161-6143-44f6-af95-6c1f44f0d45e', '酒語聯句各分一字', '酒語聯句各分一字', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["山簡酣歌倒接㒿，看朱成碧無所知。","耳鳴目眩駟馬馳，口稱童羖腹鴟夷。","兀然落帽灌酒巵，太常吏部相對時。","藉糟枕麴浮酒池，瓮間籬下臥不移。","叫呼不應無事悲，千日一醒知是誰。","左傾右倒人避之。"]', '["山簡酣歌倒接㒿，看朱成碧無所知。","耳鳴目眩駟马驰，口稱童羖腹鴟夷。","兀然落帽灌酒巵，太常吏部相对时。","藉糟枕麴浮酒池，瓮间籬下臥不移。","叫呼不應無事悲，千日一醒知是誰。","左傾右倒人避之。"]', '诗', 'shi', '', NULL, '酒語聯句各分一字 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ad1b7d6-54fe-435e-93e3-d2f56b628413', '一字至九字詩聯句', '一字至九字诗聯句', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["東，西。","步月，尋溪。","鳥已宿，猨又啼。","狂流礙石，迸筍穿磎。","望望人煙遠，行行蘿徑迷。","探題只應盡墨，持贈更欲封泥。","松下流時何歲月，雲中幽處屢攀躋。","乘興不知山路遠近，緣情莫問日過高低。","靜聽林下潺潺足湍瀨，厭問城中喧喧多鼓鼙。"]', '["东，西。","步月，尋溪。","鸟已宿，猨又啼。","狂流礙石，迸筍穿磎。","望望人煙远，行行蘿徑迷。","探題只應尽墨，持贈更欲封泥。","松下流时何歲月，云中幽处屢攀躋。","乘兴不知山路远近，緣情莫问日過高低。","静听林下潺潺足湍瀨，厭问城中喧喧多鼓鼙。"]', '诗', 'shi', '', NULL, '一字至九字詩聯句 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36a514e0-92f1-4f74-82b3-7245297fa4ee', '宣上人病中相尋聯句', '宣上人病中相尋聯句', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["策杖迎詩客，歸房理病身。","閑收無效藥，徧寄有情人。","草木分千品，方書問六陳。","還知一室內，我爾即天親。"]', '["策杖迎诗客，归房理病身。","闲收無效藥，徧寄有情人。","草木分千品，方书问六陳。","還知一室內，我爾即天親。"]', '诗', 'shi', '', NULL, '宣上人病中相尋聯句 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d83c748-a0ad-444f-8be9-b215cf82edd9', '八月十五夜宣上人獨遊安國寺山庭院步人遲明將至因話昨宵乘興聯句', '八月十五夜宣上人独游安国寺山庭院步人遲明將至因話昨宵乘兴聯句', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["九重城接天花界，三五秋生一夜風。","行聽漏聲雲散後，遙聞天語月明中。","含涼閣迥通仙掖，承露盤高出上宮。","誰問獨愁門外客，清談不與此宵同。"]', '["九重城接天花界，三五秋生一夜风。","行听漏声云散後，遙闻天語月明中。","含涼閣迥通仙掖，承露盤高出上宮。","誰问独愁门外客，清談不與此宵同。"]', '诗', 'shi', '', NULL, '八月十五夜宣上人獨遊安國寺山庭院步人遲明將至因話昨宵乘興聯句 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dee34f3-98c5-4e93-9f0d-8524840ef3b4', '重陽夜集蘭陵居與宣上人聯句', '重陽夜集蘭陵居與宣上人聯句', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["蟋蟀催寒服，茱萸滴露房。","酒巡明刻燭，籬菊暗尋芳。","新月和秋露，繁星混夜霜。","登高今夕事，九九是天長。"]', '["蟋蟀催寒服，茱萸滴露房。","酒巡明刻燭，籬菊暗尋芳。","新月和秋露，繁星混夜霜。","登高今夕事，九九是天长。"]', '诗', 'shi', '', NULL, '重陽夜集蘭陵居與宣上人聯句 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23aeab81-c690-4383-8b10-2d0e105aec60', '與宣供奉攜癭尊歸杏溪園聯句', '與宣供奉携癭尊归杏溪园聯句', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["千畦抱甕園，一酌癭尊酒。","唯有沃洲僧，時過杏溪叟。","追歡君適性，獨飲我空口。","儒釋事雖殊，文章意多偶。"]', '["千畦抱甕园，一酌癭尊酒。","唯有沃洲僧，时過杏溪叟。","追歡君適性，独饮我空口。","儒釋事雖殊，文章意多偶。"]', '诗', 'shi', '', NULL, '與宣供奉攜癭尊歸杏溪園聯句 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d63384dc-4f83-43cb-b8a7-c7020a3ac904', '蘭陵僻居聯句', '蘭陵僻居聯句', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["潘岳閑居賦，陶潛獨酌謠。","二賢成往事，三徑是今朝。","生幸逢唐運，昌時奉帝堯。","進思諧啓沃，退混即漁樵。","蠹簡封延閣，彫闌閟上霄。","相從清曠地，秋露挹蘭苕。"]', '["潘岳闲居賦，陶潛独酌謠。","二賢成往事，三徑是今朝。","生幸逢唐運，昌时奉帝堯。","進思諧啓沃，退混即漁樵。","蠹簡封延閣，彫闌閟上霄。","相從清曠地，秋露挹蘭苕。"]', '诗', 'shi', '', NULL, '蘭陵僻居聯句 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53bc96df-8ea0-4936-b697-2fc94a3bdef3', '天津橋南山中各題一句', '天津橋南山中各題一句', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["野坐分苔席，山行繞菊叢。","雲衣惹不破，秋色望來空。"]', '["野坐分苔席，山行繞菊叢。","云衣惹不破，秋色望来空。"]', '诗', 'shi', '', NULL, '天津橋南山中各題一句 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('830df6a7-5eb1-4c62-979c-eeaeade0a0b9', '紅樓下聯句', '紅楼下聯句', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["佛剎接重城，紅樓切太清。","紫雲連照耀，丹檻鬱崢嶸。","榱棟煙虹入，軒窗日月平。","參差五陵晚，分背八川明。","松韻風初過，蓮陂浪欲傾。","敬瞻疑涌見，圍繞學無生。"]', '["佛剎接重城，紅楼切太清。","紫云連照耀，丹檻鬱崢嶸。","榱棟煙虹入，軒窗日月平。","參差五陵晚，分背八川明。","松韻风初過，蓮陂浪欲傾。","敬瞻疑涌见，圍繞学無生。"]', '诗', 'shi', '', NULL, '紅樓下聯句 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5311e29-eab3-4f14-9363-c6d81b786aa3', '賦應門照綠苔', '賦應门照綠苔', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["宮闕何年月，應門何歲苔。","清光一以照，白露共裴回。","珠履久行絕，玉房重未開。","妾心正如此，昭陽歌吹來。"]', '["宮闕何年月，應门何歲苔。","清光一以照，白露共裴回。","珠履久行絕，玉房重未开。","妾心正如此，昭陽歌吹来。"]', '诗', 'shi', '', NULL, '賦應門照綠苔 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e74f69c0-ed7a-4ab3-adeb-650db1cc262e', '寄司空曙李端聯句', '寄司空曙李端聯句', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["長安一分首，萬里隔煙波。","海上青山暮，天涯白髮多。","尋僧因看竹，訪道或求鵝。","雲樹無猨鳥，陰崖足薜蘿。","醉中留越客，興裏眄庭柯。","黃葉身仍逐，丹霄背未摩。","別愁連旦暮，歸夢繞關河。","高柳寒蟬對，空階夜雨和。","年華空荏苒，名宦轉蹉跎。","南陌東城路，春來幾度過。"]', '["长安一分首，万里隔煙波。","海上青山暮，天涯白髮多。","尋僧因看竹，訪道或求鵝。","云樹無猨鸟，陰崖足薜蘿。","醉中留越客，兴裏眄庭柯。","黄葉身仍逐，丹霄背未摩。","別愁連旦暮，归梦繞关河。","高柳寒蟬对，空階夜雨和。","年华空荏苒，名宦轉蹉跎。","南陌东城路，春来幾度過。"]', '诗', 'shi', '', NULL, '寄司空曙李端聯句 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1746c11d-447f-4bff-bdb0-33ed521c2572', '連句多暇贈陸三山人', '連句多暇贈陸三山人', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["一生爲墨客，幾世作茶仙。","喜是攀闌者，慙非負鼎賢。","禁門聞曙漏，顧渚入晨煙。","拜井孤城裏，攜籠萬壑前。","閑喧悲異趣，語默取同年。","歷落驚相偶，衰羸猥見憐。","詩書聞講誦，文雅接蘭荃。","未敢重芳席，焉能弄綵箋。","黑池流研水，徑石澀苔錢。","何事親香案，無端狎釣船。","野中求逸禮，江上訪遺編。","莫發搜歌意，予心或不然。"]', '["一生爲墨客，幾世作茶仙。","喜是攀闌者，慙非負鼎賢。","禁门闻曙漏，顧渚入晨煙。","拜井孤城裏，携籠万壑前。","闲喧悲異趣，語默取同年。","歷落驚相偶，衰羸猥见怜。","诗书闻講誦，文雅接蘭荃。","未敢重芳席，焉能弄綵箋。","黑池流研水，徑石澀苔錢。","何事親香案，無端狎釣船。","野中求逸禮，江上訪遺編。","莫發搜歌意，予心或不然。"]', '诗', 'shi', '', NULL, '連句多暇贈陸三山人 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a8d86eb-2bee-45f2-a790-2452dca33f58', '道州春日感興', '道州春日感兴', '5a85b00f-be48-4510-9be3-b483059997f5', '唐', '["始見花滿枝，又看花滿地。","且持增氣酒，莫滴傷心淚。","深誠長鬱結，芳晨自妍媚。","嘯歌聊永日，誰知此時意。"]', '["始见花满枝，又看花满地。","且持增氣酒，莫滴傷心泪。","深誠长鬱結，芳晨自妍媚。","嘯歌聊永日，誰知此时意。"]', '诗', 'shi', '', NULL, '道州春日感興 李景儉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3bf982c-4340-4c31-b79c-e498fc2762cb', '中秋夜聽歌聯句', '中秋夜听歌聯句', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["此夕來奔月，何時去上天。","雲鬟方自照，玉腕更呈鮮。","燕婉人間意，飄颻物外緣。","詩裁明月扇，歌索想夫憐。","暗染荀香久，長隨楚夢偏。","會當來彩鳳，髣髴逐神仙。"]', '["此夕来奔月，何时去上天。","云鬟方自照，玉腕更呈鲜。","燕婉人间意，飄颻物外緣。","诗裁明月扇，歌索想夫怜。","暗染荀香久，长隨楚梦偏。","會當来彩鳳，髣髴逐神仙。"]', '诗', 'shi', '', NULL, '中秋夜聽歌聯句 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86a91e4c-1580-41d9-8bb4-68b3c9ef6e49', '春池泛舟聯句', '春池泛舟聯句', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["鳳池新雨後，池上好風光。","取酒愁春盡，留賓喜日長。","柳絲迎畫舸，水鏡寫雕梁。","潭洞迷仙府，煙霞認醉鄉。","鶯聲隨笑語，竹色入壺觴。","晚景含澄澈，時芳得豔陽。","飛鳧拂輕浪，綠柳暗迴塘。","逸韻追安石，高居勝辟彊。","杯停新令舉，詩動綵牋忙。","顧謂同來客，歡遊不可忘。"]', '["鳳池新雨後，池上好风光。","取酒愁春尽，留賓喜日长。","柳絲迎畫舸，水镜寫雕梁。","潭洞迷仙府，煙霞認醉乡。","鶯声隨笑語，竹色入壺觴。","晚景含澄澈，时芳得豔陽。","飞鳧拂轻浪，綠柳暗迴塘。","逸韻追安石，高居勝辟彊。","杯停新令舉，诗动綵牋忙。","顧謂同来客，歡游不可忘。"]', '诗', 'shi', '', NULL, '春池泛舟聯句 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca763363-874c-4da2-b0db-57665365d49e', '西池落泉聯句', '西池落泉聯句', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["東閣聽泉落，能令野興多。","散時猶帶沫，淙處即跳波。","偏洗磷磷石，還驚泛泛鵝。","色清塵不染，光白月相和。","噴雪縈松竹，攢珠濺芰荷。","對吟時合響，觸樹更搖柯。","照圃紅分藥，侵階綠浸莎。","日斜車馬散，餘韻逐鳴珂。"]', '["东閣听泉落，能令野兴多。","散时猶带沫，淙处即跳波。","偏洗磷磷石，還驚泛泛鵝。","色清塵不染，光白月相和。","噴雪縈松竹，攢珠濺芰荷。","对吟时合响，觸樹更搖柯。","照圃紅分藥，侵階綠浸莎。","日斜车马散，餘韻逐鳴珂。"]', '诗', 'shi', '', NULL, '西池落泉聯句 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acd05cdb-edc1-44ff-8c33-6f6056e295b0', '首夏猶清和聯句', '首夏猶清和聯句', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["記得謝家詩，清和即此時。","餘花數種在，密葉幾重垂。","芳謝人人惜，陰成處處宜。","水萍爭點綴，梁燕共追隨。","亂蝶憐疎蘂，殘鶯戀好枝。","草香殊未歇，雲勢漸多奇。","單服初寧體，新篁已出籬。","與春爲別近，覺日轉行遲。","繞樹風光少，侵階苔蘚滋。","惟思奉歡樂，長得在西池。"]', '["記得謝家诗，清和即此时。","餘花數種在，密葉幾重垂。","芳謝人人惜，陰成处处宜。","水萍爭点綴，梁燕共追隨。","亂蝶怜疎蘂，殘鶯戀好枝。","草香殊未歇，云勢漸多奇。","單服初寧體，新篁已出籬。","與春爲別近，覺日轉行遲。","繞樹风光少，侵階苔蘚滋。","惟思奉歡乐，长得在西池。"]', '诗', 'shi', '', NULL, '首夏猶清和聯句 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0f07ca0-3738-4724-8051-0f86d096819f', '薔薇花聯句', '薔薇花聯句', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["似錦如霞色，連春接夏開。","波紅分影入，風好帶香來。","得地依東閣，當階奉上台。","淺深皆有態，次第暗相催。","滿地愁英落，緣堤惜櫂迴。","芳濃濡雨露，明麗隔塵埃。","似著臙脂染，如經巧婦裁。","奈花無別計，只有酒殘杯。"]', '["似錦如霞色，連春接夏开。","波紅分影入，风好带香来。","得地依东閣，當階奉上台。","淺深皆有態，次第暗相催。","满地愁英落，緣堤惜櫂迴。","芳濃濡雨露，明丽隔塵埃。","似著臙脂染，如經巧婦裁。","奈花無別計，只有酒殘杯。"]', '诗', 'shi', '', NULL, '薔薇花聯句 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2363f79-9196-4ea4-b497-a4b677f6a600', '喜遇劉二十八偶書兩韻聯句', '喜遇劉二十八偶书兩韻聯句', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["病來佳興少，老去舊遊稀。","笑語縱橫作，杯觴絡繹飛。","清談如水玉，逸韻貫珠璣。","高位當金鉉，虛懷似布衣。","已容狂取樂，仍任醉忘機。","捨眷將何適，留歡便是歸。","鳳儀常欲附，蚊力自知微。","願假尊罍末，膺門自此依。"]', '["病来佳兴少，老去旧游稀。","笑語縱橫作，杯觴絡繹飞。","清談如水玉，逸韻貫珠璣。","高位當金鉉，虛懷似布衣。","已容狂取乐，仍任醉忘機。","捨眷將何適，留歡便是归。","鳳儀常欲附，蚊力自知微。","願假尊罍末，膺门自此依。"]', '诗', 'shi', '', NULL, '喜遇劉二十八偶書兩韻聯句 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74c131c2-ecdb-4ff5-86c1-dbf6a6589549', '劉二十八自汝赴左馮塗經洛中相見聯句', '劉二十八自汝赴左馮塗經洛中相见聯句', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["不歸丹掖去，銅竹漫云云。","唯喜因過我，須知未賀君。","詩聞安石詠，香見令公熏。","欲首函關路，來披緱嶺雲。","貂蟬公獨步，鴛鷺我同羣。","插羽先飛酒，交鋒便戰文。","鎮嵩知表德，定鼎爲銘勳。","顧鄙容商洛，徵歡候汝墳。","頻年多謔浪，此夕任喧紛。","故態猶應在，行期未要聞。","遊藩榮已久，捧袂惜將分。","詎厭杯行疾，唯愁日向曛。","窮陰初莽蒼，離思漸氤氳。","殘雪午橋岸，斜陽伊水濆。","上謨尊右掖，全略靜東軍。","萬頃徒稱量，滄溟詎有垠。"]', '["不归丹掖去，銅竹漫云云。","唯喜因過我，須知未賀君。","诗闻安石詠，香见令公熏。","欲首函关路，来披緱嶺云。","貂蟬公独步，鴛鷺我同羣。","插羽先飞酒，交鋒便戰文。","鎮嵩知表德，定鼎爲銘勳。","顧鄙容商洛，徵歡候汝墳。","頻年多謔浪，此夕任喧紛。","故態猶應在，行期未要闻。","游藩榮已久，捧袂惜將分。","詎厭杯行疾，唯愁日向曛。","窮陰初莽蒼，離思漸氤氳。","殘雪午橋岸，斜陽伊水濆。","上謨尊右掖，全略静东軍。","万頃徒稱量，滄溟詎有垠。"]', '诗', 'shi', '', NULL, '劉二十八自汝赴左馮塗經洛中相見聯句 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0ce3d80-fd8a-4adf-b24b-58e25c5d20ea', '度自到洛中與樂天爲文酒之會時時搆詠樂不可支則慨然共憶夢得而夢得亦分司至止歡愜可知因爲聯句', '度自到洛中與乐天爲文酒之會时时搆詠乐不可支則慨然共憶梦得而梦得亦分司至止歡愜可知因爲聯句', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["成周文酒會，吾友勝鄒枚。","唯憶劉夫子，而今又到來。","欲迎先倒屣，亦坐便傾杯。","飲許伯倫右，詩推公幹才。","久曾聆郢唱，重喜上燕臺。","晝話牆陰轉，宵歡斗柄迴。","新聲還共聽，故態復相咍。","遇物皆先賞，從花半未開。","起時烏帽側，散處玉山頹。","墨客喧東閣，文星犯上台。","詠吟君稱首，疎放我爲魁。","憶戴何勞訪，留髠不用猜。","奉觴承麴糵，落筆捧瓊瑰。","醉弁無妨側，詞鋒不可摧。","水軒看翡翠，石徑踐莓苔。","童子能騎竹，佳人解詠梅。","洛中三可矣，鄴下七悠哉。","自向風光急，不須弦管催。","樂觀魚踴躍，閑愛鶴裴回。","煙柳青凝黛，波萍綠撥醅。","春榆初改火，律管又飛灰。","紅藥多遲發，碧松宜亂栽。","馬嘶駝陌上，鷁泛鳳城隈。","色色時堪惜，些些病莫推。","涸流尋軋軋，餘刃轉恢恢。","從此知心伏，無因敢自媒。","室隨親客入，席許舊寮陪。","逸興嵇將阮，交情陳與雷。","洪爐思哲匠，大廈要羣材。","他日登龍路，應知免曝鰓。"]', '["成周文酒會，吾友勝鄒枚。","唯憶劉夫子，而今又到来。","欲迎先倒屣，亦坐便傾杯。","饮許伯倫右，诗推公幹才。","久曾聆郢唱，重喜上燕台。","晝話牆陰轉，宵歡斗柄迴。","新声還共听，故態复相咍。","遇物皆先賞，從花半未开。","起时烏帽側，散处玉山頹。","墨客喧东閣，文星犯上台。","詠吟君稱首，疎放我爲魁。","憶戴何勞訪，留髠不用猜。","奉觴承麴糵，落笔捧瓊瑰。","醉弁無妨側，词鋒不可摧。","水軒看翡翠，石徑踐莓苔。","童子能騎竹，佳人解詠梅。","洛中三可矣，鄴下七悠哉。","自向风光急，不須弦管催。","乐观鱼踴躍，闲愛鹤裴回。","煙柳青凝黛，波萍綠撥醅。","春榆初改火，律管又飞灰。","紅藥多遲發，碧松宜亂栽。","马嘶駝陌上，鷁泛鳳城隈。","色色时堪惜，些些病莫推。","涸流尋軋軋，餘刃轉恢恢。","從此知心伏，無因敢自媒。","室隨親客入，席許旧寮陪。","逸兴嵇將阮，交情陳與雷。","洪爐思哲匠，大廈要羣材。","他日登龙路，應知免曝鰓。"]', '诗', 'shi', '', NULL, '度自到洛中與樂天爲文酒之會時時搆詠樂不可支則慨然共憶夢得而夢得亦分司至止歡愜可知因爲聯句 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('369fe5ec-66fe-4e22-be52-eeefe1db519c', '宴興化池亭送白二十二東歸聯句', '宴兴化池亭送白二十二东归聯句', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["東洛言歸去，西園告別來。","白頭青眼客，池上手中杯。","離瑟殷勤奏，仙舟委曲回。","征輪今欲動，賓閣爲誰開。","坐弄琉璃水，行登綠縟堆。","花低妝照影，萍散酒吹醅。","岸蔭新抽竹，亭香欲變梅。","隨遊多笑傲，遇勝且裴回。","澄澈連天鏡，潺湲出地雷。","林塘難共賞，鞍馬莫相催。","信及魚還樂，機忘鳥不猜。","晚晴槐起露，新雨石添苔。","擬作雲泥別，尤思頃刻陪。","歌停珠貫斷，飲罷玉峰頹。","雖有逍遙志，其如磊落才。","會當重入用，此去肯悠哉。"]', '["东洛言归去，西园告別来。","白头青眼客，池上手中杯。","離瑟殷勤奏，仙舟委曲回。","征輪今欲动，賓閣爲誰开。","坐弄琉璃水，行登綠縟堆。","花低妝照影，萍散酒吹醅。","岸蔭新抽竹，亭香欲变梅。","隨游多笑傲，遇勝且裴回。","澄澈連天镜，潺湲出地雷。","林塘难共賞，鞍马莫相催。","信及鱼還乐，機忘鸟不猜。","晚晴槐起露，新雨石添苔。","擬作云泥別，尤思頃刻陪。","歌停珠貫斷，饮罷玉峰頹。","雖有逍遙志，其如磊落才。","會當重入用，此去肯悠哉。"]', '诗', 'shi', '', NULL, '宴興化池亭送白二十二東歸聯句 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eadd607d-a93b-48ef-97d7-9e343d1faa23', '西池送白二十二東歸兼寄令狐相公聯句', '西池送白二十二东归兼寄令狐相公聯句', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["促坐宴回塘，送君歸洛陽。","彼都留上宰，爲我說中腸。","威鳳池邊別，冥鴻天際翔。","披雲見居守，望日拜封章。","春盡年華少，舟通景氣長。","送行歡共惜，寄遠意難忘。","東道瞻軒蓋，西園醉羽觴。","謝公深眷眄，商皓信輝光。","舊德推三友，新篇代八行。"]', '["促坐宴回塘，送君归洛陽。","彼都留上宰，爲我说中腸。","威鳳池邊別，冥鴻天際翔。","披云见居守，望日拜封章。","春尽年华少，舟通景氣长。","送行歡共惜，寄远意难忘。","东道瞻軒蓋，西园醉羽觴。","謝公深眷眄，商皓信輝光。","旧德推三友，新篇代八行。"]', '诗', 'shi', '', NULL, '西池送白二十二東歸兼寄令狐相公聯句 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31b156c5-85d6-41be-9fe5-276ce8ea4f67', '杏園聯句', '杏园聯句', 'aefd5b04-cbf6-42cf-b054-fcbd572793a4', '唐', '["杏園千樹欲隨風，一醉同人此暫同。","老態忽忘絲管裏，衰顏宜解酒杯中。","曲江日暮殘紅在，翰苑年深舊事空。","二十四年流落者，故人相引到花叢。"]', '["杏园千樹欲隨风，一醉同人此暫同。","老態忽忘絲管裏，衰顏宜解酒杯中。","曲江日暮殘紅在，翰苑年深旧事空。","二十四年流落者，故人相引到花叢。"]', '诗', 'shi', '', NULL, '杏園聯句 李絳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f83432c-c443-41fd-b105-78ea725537d7', '花下醉中聯句', '花下醉中聯句', 'aefd5b04-cbf6-42cf-b054-fcbd572793a4', '唐', '["共醉風光地，花飛落酒杯。","殘春猶可賞，晚景莫相催。","酒幸年年有，花應歲歲開。","且當金韻擲，莫遣玉山頹。","高會彌堪惜，良時不易陪。","誰能拉花住，爭換得春回。","我輩尋常有，佳人早晚來。","寄言三相府，欲散且裴回。"]', '["共醉风光地，花飞落酒杯。","殘春猶可賞，晚景莫相催。","酒幸年年有，花應歲歲开。","且當金韻擲，莫遣玉山頹。","高會彌堪惜，良时不易陪。","誰能拉花住，爭換得春回。","我輩尋常有，佳人早晚来。","寄言三相府，欲散且裴回。"]', '诗', 'shi', '', NULL, '花下醉中聯句 李絳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d6dc54e-a5bf-4741-8ee8-d8305e89fb66', '樂天是月長齋鄙夫此時愁臥里閭非遠雲霧難披因以寄懷遂爲聯句所期解悶焉敢驚禪', '乐天是月长斋鄙夫此时愁臥里閭非远云霧难披因以寄懷遂爲聯句所期解悶焉敢驚禪', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["五月長齋月，文心苦行心。","蘭蔥不入戶，薝蔔自成林。","護戒先辭酒，嫌喧亦徹琴。","塵埃賓位靜，香火道場深。","我靜馴狂象，餐餘施衆禽。","定知於佛佞，豈復向書淫。","闌藥凋紅豔，庭槐換綠陰。","風光徒滿目，雲霧未披襟。","樹爲清涼倚，池因盥漱臨。","蘋芳遭燕拂，蓮坼待蠭尋。","舍下環流水，窗中列遠岑。","苔斑錢剝落，石怪玉嶔岑。","鵲頂迎秋禿，鶯喉入夏瘖。","綠楊垂嫩色，綖棘露長鍼。","散秩身猶幸，趨朝力不任。","官將方共拙，年與病交侵。","徇樂非時選，忘機似陸沈。","鑒容稱四皓，捫腹有三壬。","攜手慙連璧，同心許斷金。","紫芝雖繼唱，白雪少知音。","憶罷吳門守，相逢楚水潯。","舟中頻曲宴，夜後各加斟。","濁酒銷殘漏，弦聲間遠砧。","酡顏舞長袖，密坐接華簪。","持論峰巒峻，戰文矛戟森。","笑言誠莫逆，造次必相箴。","往事應如昨，餘歡迄至今。","迎君常倒屣，訪我輒攜衾。","陰魄初離畢，陽光正在參。","待公休一食，縱飲共狂吟。"]', '["五月长斋月，文心苦行心。","蘭蔥不入戶，薝蔔自成林。","護戒先辞酒，嫌喧亦徹琴。","塵埃賓位静，香火道場深。","我静馴狂象，餐餘施衆禽。","定知於佛佞，豈复向书淫。","闌藥凋紅豔，庭槐換綠陰。","风光徒满目，云霧未披襟。","樹爲清涼倚，池因盥漱臨。","蘋芳遭燕拂，蓮坼待蠭尋。","舍下环流水，窗中列远岑。","苔斑錢剝落，石怪玉嶔岑。","鵲頂迎秋禿，鶯喉入夏瘖。","綠楊垂嫩色，綖棘露长鍼。","散秩身猶幸，趨朝力不任。","官將方共拙，年與病交侵。","徇乐非时選，忘機似陸沈。","鑒容稱四皓，捫腹有三壬。","携手慙連璧，同心許斷金。","紫芝雖繼唱，白雪少知音。","憶罷吳门守，相逢楚水潯。","舟中頻曲宴，夜後各加斟。","濁酒銷殘漏，弦声间远砧。","酡顏舞长袖，密坐接华簪。","持論峰巒峻，戰文矛戟森。","笑言誠莫逆，造次必相箴。","往事應如昨，餘歡迄至今。","迎君常倒屣，訪我輒携衾。","陰魄初離畢，陽光正在參。","待公休一食，縱饮共狂吟。"]', '诗', 'shi', '', NULL, '樂天是月長齋鄙夫此時愁臥里閭非遠雲霧難披因以寄懷遂爲聯句所期解悶焉敢驚禪 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0426e00e-b755-4169-bd3a-edeb00645dd6', '秋霖即事聯句三十韻', '秋霖即事聯句三十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蕭索窮秋月，蒼茫苦雨天。","泄雲生棟上，行潦入庭前。","苔色侵三徑，波聲想五弦。","井蛙爭入戶，轍鮒亂歸泉。","高𩅸愁晨坐，空階警夜眠。","鶴鳴猶未已，蟻穴亦頻遷。","散漫疎還密，空濛斷復連。","竹霑青玉潤，荷滴白珠圓。","地溼灰蛾滅，池添水馬憐。","有苗霑霢霂，無月弄潺湲。","籬菊潛開秀，園蔬已罷鮮。","斷行隨雁翅，孤嘯聳鳶肩。","橋柱黏黃菌，牆衣點綠錢。","草荒行藥路，沙泛釣魚船。","長者車猶阻，高人榻且懸。","金烏何日見，玉爵幾時傳。","近井桐先落，當檐石欲穿。","趨風誠有戀，披霧邈無緣。","廩米陳生醭，庖薪溼起煙。","鳴雞潛報曉，急景暗彫年。","蓋灑高松上，絲繁細柳邊。","拂叢時起蝶，墮葉乍驚蟬。","巾角皆爭墊，帬裾別似湔。","人多蒙翠被，馬盡著連乾。","好客無來者，貧家但悄然。","溼泥印鶴迹，漏壁絡蝸涎。","蚊聚雷侵室，鷗翻/浪滿川。","上樓愁羃羃，繞舍厭濺濺。","律候今秋矣，歡娛久曠焉。","但令高興在，晴後奉周旋。"]', '["蕭索窮秋月，蒼茫苦雨天。","泄云生棟上，行潦入庭前。","苔色侵三徑，波声想五弦。","井蛙爭入戶，轍鮒亂归泉。","高𩅸愁晨坐，空階警夜眠。","鹤鳴猶未已，蟻穴亦頻遷。","散漫疎還密，空濛斷复連。","竹霑青玉潤，荷滴白珠圓。","地溼灰蛾滅，池添水马怜。","有苗霑霢霂，無月弄潺湲。","籬菊潛开秀，园蔬已罷鲜。","斷行隨雁翅，孤嘯聳鳶肩。","橋柱黏黄菌，牆衣点綠錢。","草荒行藥路，沙泛釣鱼船。","长者车猶阻，高人榻且懸。","金烏何日见，玉爵幾时傳。","近井桐先落，當檐石欲穿。","趨风誠有戀，披霧邈無緣。","廩米陳生醭，庖薪溼起煙。","鳴雞潛報晓，急景暗彫年。","蓋灑高松上，絲繁細柳邊。","拂叢时起蝶，墮葉乍驚蟬。","巾角皆爭墊，帬裾別似湔。","人多蒙翠被，马尽著連乾。","好客無来者，貧家但悄然。","溼泥印鹤迹，漏壁絡蝸涎。","蚊聚雷侵室，鷗翻/浪满川。","上楼愁羃羃，繞舍厭濺濺。","律候今秋矣，歡娛久曠焉。","但令高兴在，晴後奉周旋。"]', '诗', 'shi', '', NULL, '秋霖即事聯句三十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('702b8e84-8305-4d8d-ac54-5bf825966c20', '喜晴聯句', '喜晴聯句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["苦雨晴何喜，喜於未雨時。","氣收雲物變，聲樂鳥烏知。","蕙泛光風圃，蘭開皎月池。","千峰分遠近，九陌好追隨。","白日開天路，玄陰卷地維。","餘清在林薄，新照入漣漪。","碧樹涼先落，青蕪溼更滋。","曬毛經浴鶴，曳尾出泥龜。","舞去商羊速，飛來野馬遲。","柱邊無潤礎，臺上有游絲。","橋淨行塵息，堤長禁柳垂。","宮城開睥睨，觀闕麗罘罳。","洛水澄清鎮，嵩煙展翠帷。","梁成虹乍見，市散蜃初移。","藉草風猶暖，攀條露已晞。","屋穿添碧瓦，牆缺召金鎚。","迥徹來雙目，昏煩去四支。","霞文晚煥爛，星影夕參差。","爽助門庭肅，寒摧草木衰。","黃乾向陽菊，紅洗得霜梨。","假蓋閑誰惜，彈弦燥更悲。","散蹄良馬穩，炙背野人宜。","洞戶晨暉入，空庭宿霧披。","推林出書目，傾笥上衣椸。","道路行非阻，軒車望可期。","無辭訪圭竇，且願見瓊枝。","山閣蓬萊客，儲宮羽翼師。","每優陪麗句，何暇覿英姿。","翫景方搔首，懷人尚斂眉。","因吟仲文什，高興盡於斯。"]', '["苦雨晴何喜，喜於未雨时。","氣收云物变，声乐鸟烏知。","蕙泛光风圃，蘭开皎月池。","千峰分远近，九陌好追隨。","白日开天路，玄陰卷地維。","餘清在林薄，新照入漣漪。","碧樹涼先落，青蕪溼更滋。","曬毛經浴鹤，曳尾出泥龟。","舞去商羊速，飞来野马遲。","柱邊無潤礎，台上有游絲。","橋淨行塵息，堤长禁柳垂。","宮城开睥睨，观闕丽罘罳。","洛水澄清鎮，嵩煙展翠帷。","梁成虹乍见，市散蜃初移。","藉草风猶暖，攀條露已晞。","屋穿添碧瓦，牆缺召金鎚。","迥徹来雙目，昏煩去四支。","霞文晚煥爛，星影夕參差。","爽助门庭肅，寒摧草木衰。","黄乾向陽菊，紅洗得霜梨。","假蓋闲誰惜，彈弦燥更悲。","散蹄良马穩，炙背野人宜。","洞戶晨暉入，空庭宿霧披。","推林出书目，傾笥上衣椸。","道路行非阻，軒车望可期。","無辞訪圭竇，且願见瓊枝。","山閣蓬萊客，儲宮羽翼師。","每優陪丽句，何暇覿英姿。","翫景方搔首，懷人尚斂眉。","因吟仲文什，高兴尽於斯。"]', '诗', 'shi', '', NULL, '喜晴聯句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e34b3adb-5e5a-49af-a42c-3d5ca6d61401', '會昌春連宴即事', '會昌春連宴即事', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["元年寒食日，上巳暮春天。","雞黍三家會，鶯花二節連。","光風初澹蕩，美景漸暄妍。","簪組蘭亭上，車輿曲水邊。","松聲添奏樂，草色助鋪筵。","雀舫宜閑泛，螺杯任漫傳。","園蔬香帶露，廚柳暗藏煙。","麗句輕珠玉，清談勝管弦。","陌喧金距鬬，樹動綵繩懸。","姹女妝梳豔，遊童衣服鮮。","圃香知種蕙，池暖憶開蓮。","怪石雲疑觸，夭桃火欲然。","正歡唯恐散，雖醉未思眠。","嘯傲人間世，追隨地上僊。","燕來雙涎涎，雁去累翩翩。","行樂真吾事，尋芳獨我先。","滯周慙太史，入洛繼先賢。","昔恨多分手，今歡謬比肩。","病猶陪讌飲，老更奉周旋。","望重青雲客，情深白首年。","徧嘗珍饌後，許入畫堂前。","舞袖翻紅炬，歌鬟插寶蟬。","斷金多感激，倚玉貴遷延。","說史吞顏注，論詩笑鄭箋。","松筠寒不變，膠漆冷彌堅。","興伴王尋戴，榮同隗在燕。","擲盧誇使氣，刻燭鬬成篇。","實藝皆三捷，虛名愧六聯。","興闌猶舉白，話靜每思玄。","更說歸時好，亭亭月正圓。"]', '["元年寒食日，上巳暮春天。","雞黍三家會，鶯花二節連。","光风初澹蕩，美景漸暄妍。","簪組蘭亭上，车輿曲水邊。","松声添奏乐，草色助鋪筵。","雀舫宜闲泛，螺杯任漫傳。","园蔬香带露，廚柳暗藏煙。","丽句轻珠玉，清談勝管弦。","陌喧金距鬬，樹动綵繩懸。","姹女妝梳豔，游童衣服鲜。","圃香知種蕙，池暖憶开蓮。","怪石云疑觸，夭桃火欲然。","正歡唯恐散，雖醉未思眠。","嘯傲人间世，追隨地上僊。","燕来雙涎涎，雁去累翩翩。","行乐真吾事，尋芳独我先。","滯周慙太史，入洛繼先賢。","昔恨多分手，今歡謬比肩。","病猶陪讌饮，老更奉周旋。","望重青云客，情深白首年。","徧嘗珍饌後，許入畫堂前。","舞袖翻紅炬，歌鬟插寶蟬。","斷金多感激，倚玉貴遷延。","说史吞顏注，論诗笑鄭箋。","松筠寒不变，膠漆冷彌堅。","兴伴王尋戴，榮同隗在燕。","擲盧誇使氣，刻燭鬬成篇。","實藝皆三捷，虛名愧六聯。","兴闌猶舉白，話静每思玄。","更说归时好，亭亭月正圓。"]', '诗', 'shi', '', NULL, '會昌春連宴即事 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f699ef22-319a-481b-8575-103300613ab9', '僕射來示有三春向晚四者難幷之說誠哉是言輒引起題重爲聯句疲兵再戰勍敵難降下筆之時囅然自哂走呈僕射兼簡尚書', '僕射来示有三春向晚四者难幷之说誠哉是言輒引起題重爲聯句疲兵再戰勍敵难降下笔之时囅然自哂走呈僕射兼簡尚书', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三春今向晚，四者昔難幷。","借問低眉坐，何如攜手行。","舊遊多過隙，新宴且尋盟。","鸚鵡林須樂，麒麟閣未成。","分陰當愛惜，遲景好逢迎。","林野熏風起，樓臺穀雨晴。","牆低山半出，池廣水初平。","橋轉長虹曲，舟回小鷁輕。","殘花猶布繡，密竹自聞笙。","欲過芳菲節，難忘宴慰情。","月輪行似箭，時物始如傾。","見雁隨兄去，聽鶯求友聲。","蕙長書帶展，菰嫩剪刀生。","坐密衣裳暖，堂虛絲管清。","峰巒侵碧落，草木近朱明。","與點非沂水，陪膺是洛城。","撥醅爭綠醑，臥酪待朱櫻。","幾處能留客，何人喚解酲。","舊儀尊右揆，新命寵春卿。","有喜鵲頻語，無機鷗不驚。","青林思小隱，白雪仰芳名。","訪舊殊千里，登高賴九城。","酇侯司管鑰，疏傅傲簪纓。","綸綍曾同掌，煙霄即上征。","冊庭嘗接武，書殿忝連衡。","蘭室春彌馥，松心晚更貞。","琴招翠羽下，鉤掣紫鱗呈。","只願回烏景，誰能避兕觥。","方知醉兀兀，應是走營營。","鳳閣鸞臺路，從他年少爭。"]', '["三春今向晚，四者昔难幷。","借问低眉坐，何如携手行。","旧游多過隙，新宴且尋盟。","鸚鵡林須乐，麒麟閣未成。","分陰當愛惜，遲景好逢迎。","林野熏风起，楼台穀雨晴。","牆低山半出，池廣水初平。","橋轉长虹曲，舟回小鷁轻。","殘花猶布繡，密竹自闻笙。","欲過芳菲節，难忘宴慰情。","月輪行似箭，时物始如傾。","见雁隨兄去，听鶯求友声。","蕙长书带展，菰嫩剪刀生。","坐密衣裳暖，堂虛絲管清。","峰巒侵碧落，草木近朱明。","與点非沂水，陪膺是洛城。","撥醅爭綠醑，臥酪待朱櫻。","幾处能留客，何人喚解酲。","旧儀尊右揆，新命寵春卿。","有喜鵲頻語，無機鷗不驚。","青林思小隐，白雪仰芳名。","訪旧殊千里，登高賴九城。","酇侯司管鑰，疏傅傲簪纓。","綸綍曾同掌，煙霄即上征。","冊庭嘗接武，书殿忝連衡。","蘭室春彌馥，松心晚更貞。","琴招翠羽下，鉤掣紫鱗呈。","只願回烏景，誰能避兕觥。","方知醉兀兀，應是走營營。","鳳閣鸾台路，從他年少爭。"]', '诗', 'shi', '', NULL, '僕射來示有三春向晚四者難幷之說誠哉是言輒引起題重爲聯句疲兵再戰勍敵難降下筆之時囅然自哂走呈僕射兼簡尚書 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06d93660-224b-4a79-baef-3f219bb7011f', '城南聯句', '城南聯句', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["竹影金瑣碎，泉音玉淙琤。","琉璃翦木葉，翡翠開園英。","流滑隨仄步，搜尋得深行。","遙岑出寸碧，遠目增雙明。","乾穟紛拄地，化蟲枯挶莖。","木腐或垂耳，草珠競駢睛。","浮虛有新斸，摧扤饒孤撐。","囚飛黏網動，盜啅接彈驚。","脫實自開坼，牽柔誰繞縈。","禮鼠拱而立，駭牛躅且鳴。","蔬甲喜臨社，田毛樂寬征。","露螢不自暖，凍蝶尚思輕。","宿羽有先曉，食鱗時半橫。","菱飜紫角利，荷折碧圓傾。","楚膩鱣鮪亂，獠羞蠃蟹幷。","桑蠖見虛指，穴貍聞鬬獰。","逗翳翅相築，擺幽尾交搒。","蔓涎角出縮，樹啄頭敲鏗。","修箭褭金餌，羣鮮沸池羹。","岸殼坼玄兆，野麰漸豐萌。","窰煙羃疏島，沙篆印迴平。","㾕肌遭眊刺，啾耳聞雞生。","奇慮恣迴轉，遐睎縱逢迎。","顛林戢遠睫，縹氣夷空情。","歸跡歸不得，捨心捨還爭。","靈麻撮狗蝨，村穉啼禽猩。","紅皺曬檐瓦，黃團繫門衡。","得雋蠅虎健，相殘雀豹趟。","束枯樵指禿，刈熟擔肩赬。","澀旋皮卷臠，苦開腹彭亨。","機舂潺湲力，吹簸飄颻精。","賽饌木盤簇，靸妖藤索絣。","荒學五六卷，古藏四三塋。","里儒拳足拜，土怪閃眸偵。","蹄道補復破，絲窠掃還成。","暮堂蝙蝠沸，破竈伊威盈。","追此訊前主，荅云皆冢卿。","敗壁剝寒月，折篁嘯遺笙。","袿熏霏霏在，綦跡微微呈。","劒石猶竦檻，獸材尚拏楹。","寶唾拾未盡，玉啼墮猶鎗。","窗綃疑閟豔，妝燭已銷檠。","綠髮抽珉甃，青膚聳瑤楨。","白蛾飛舞地，幽蠹落書棚。","惟昔集嘉詠，吐芳類鳴嚶。","窺奇摘海異，恣韻激天鯨。","腸胃繞萬象，精神驅五兵。","蜀雄李杜拔，嶽力雷車轟。","大句斡玄造，高言軋霄崢。","芒端轉寒燠，神助溢杯觥。","巨細各乘運，湍潿亦騰聲。","凌花咀粉蘂，削縷穿珠櫻。","綺語洗晴雪，嬌辭哢雛鶯。","酣歡雜弁珥，繁價流金瓊。","菡萏寫江調，萎蕤綴藍瑛。","庖霜膾玄鯽，淅玉炊香稉。","朝饌已百態，春醪又千名。","哀匏蹙駛景，冽唱凝餘晶。","解魄不自主，痺肌坐空瞠。","扳援賤蹊絕，炫曜仙選更。","藂巧競采笑，駢鮮互探嬰。","桑變忽蕪蔓，樟裁浪登丁。","霞鬬詎能極，風期誰復賡。","臯區扶帝壤，瓌蘊郁天京。","祥色被文彥，良才插杉檉。","隱伏饒氣象，興潛示堆坑。","擘華露神物，擁終儲地禎。","訏謨壯締始，輔弼登階清。","坌秀恣填塞，呀靈滀渟澄。","益大聯漢魏，肇初邁周嬴。","積照涵德鏡，傳經儷金籯。","食家行鼎鼐，寵族飫弓旌。","奕制盡從賜，殊私得逾程。","飛橋上架漢，繚岸俯規瀛。","瀟碧遠輸委，湖嵌費攜擎。","萄苜從大漠，楓櫧至南荆。","嘉植鮮危朽，膏理易滋榮。","懸長巧紐翠，象曲善攢珩。","魚口星浮沒，馬毛錦斑騂。","五方亂風土，百種分鉏耕。","葩蘖相妬出，菲茸共舒晴。","類招臻倜詭，翼萃伏衿纓。","危望跨飛動，冥升躡登閎。","春游轢靃靡，彩伴颯嫈嫇。","遺燦飄的皪，淑顏洞精誠。","嬌應如在寤，頹意若含酲。","鵷毳翔衣帶，鵝肪截佩璜。","文升相照灼，武勝屠欃槍。","割錦不酬價，構雲有高營。","通波牣鱗介，疏畹富蕭蘅。","買養馴孔翠，遠苞樹蕉栟。","鴻頭排刺芡，鵠𪇄攢瓌橙。","騖廣雜良牧，蒙休賴先盟。","罷旄奉環衛，守封踐忠貞。","戰服脫明介，朝冠飄彩紘。","爵勳逮僮隸，簪笏自懷繃。","乳下秀嶷嶷，椒蕃泣喤喤。","貌鑑清溢匣，眸光寒發硎。","館儒養經史，綴戚觴孫甥。","考鐘饋殽核，戛鼓侑牢牲。","飛膳自北下，函珍極東烹。","如瓜煮大卵，比線茹芳菁。","海嶽錯口腹，趙燕錫媌娙。","一笑釋仇恨，百金交弟兄。","貨至貊戎市，呼傳鸚鵒令。","順居無鬼瞰，抑橫免官評。","殺候肆凌翦，籠原匝罝紭。","羽空顛雉鷃，血路迸狐麖。","折足去踸踔，蹙鬐怒䰃鬤。","躍犬疾翥鳥，呀鷹甚飢䖟。","算蹄記功賞，裂腦擒摚掁。","猛斃牛馬樂，妖殘梟鵅惸。","窟窮尚嗔視，箭出方驚抨。","連箱載已實，礙轍棄仍贏。","喘覰鋒刃點，困衝株枿盲。","掃淨豁曠曠，騁遙略苹苹。","饞杈飽活臠，惡嚼𠽢腥鯖。","歲律及郊至，古音命韶韺。","旗斾流日月，帳廬扶棟甍。","磊落奠鴻璧，參差席香藑。","玄祇祉兆姓，黑秬饛豐盛。","慶流蠲瘥癘，威暢捐䡴輣。","靈燔望高冏，龍駕聞敲𩙁。","是惟禮之盛，永用表其宏。","德孕厚生植，恩熙完刖剠。","宅土盡華族，連田間強甿。","蔭庾森嶺檜，啄場翽祥䳟。","畦肥翦韭●，陶固收盆甖。","利養積餘健，孝思事嚴祊。","掘雲破嵽嵲，采月漉坳泓。","寺砌上明鏡，僧盂敲曉鉦。","泥象對騁怪，鐵鐘孤舂鍠。","癭頸鬧鳩鴿，蜿垣亂蛷蠑。","葚黑老蠶蠋，麥黃韻鸝鶊。","韶曙遲勝賞，賢明戒先庚。","馳門填偪仄，競墅輾砯砰。","碎纈紅滿杏，稠凝碧浮餳。","蹙繩覲娥婺，鬬草擷璣珵。","粉汗澤廣額，金星墮連瓔。","鼻偷困淑郁，眼剽強盯𥋝。","是節飽顏色，茲疆稱都城。","書饒罄魚繭，紀盛播琴箏。","奚必事遠覿，無端逐羇傖。","將身親魍魅，浮跡侶鷗鶄。","腥味空奠屈，天年徒羨彭。","驚魂見蛇蚓，觸齅值蝦蟚。","幸得履中氣，忝從拂天棖。","歸私暫休暇，驅明出庠黌。","鮮意竦輕暢，連輝照瓊瑩。","陶暄逐風乙，躍視舞晴蜻。","足勝自多詣，心貪敵無勍。","始知樂名教，何用苦拘儜。","畢景任詩趣，焉能守硜硜。"]', '["竹影金瑣碎，泉音玉淙琤。","琉璃翦木葉，翡翠开园英。","流滑隨仄步，搜尋得深行。","遙岑出寸碧，远目增雙明。","乾穟紛拄地，化蟲枯挶莖。","木腐或垂耳，草珠競駢睛。","浮虛有新斸，摧扤饒孤撐。","囚飞黏網动，盜啅接彈驚。","脫實自开坼，牽柔誰繞縈。","禮鼠拱而立，駭牛躅且鳴。","蔬甲喜臨社，田毛乐寬征。","露螢不自暖，凍蝶尚思轻。","宿羽有先晓，食鱗时半橫。","菱飜紫角利，荷折碧圓傾。","楚膩鱣鮪亂，獠羞蠃蟹幷。","桑蠖见虛指，穴貍闻鬬獰。","逗翳翅相築，擺幽尾交搒。","蔓涎角出縮，樹啄头敲鏗。","修箭褭金餌，羣鲜沸池羹。","岸殼坼玄兆，野麰漸豐萌。","窰煙羃疏島，沙篆印迴平。","㾕肌遭眊刺，啾耳闻雞生。","奇慮恣迴轉，遐睎縱逢迎。","顛林戢远睫，縹氣夷空情。","归跡归不得，捨心捨還爭。","靈麻撮狗蝨，村穉啼禽猩。","紅皺曬檐瓦，黄團繫门衡。","得雋蠅虎健，相殘雀豹趟。","束枯樵指禿，刈熟擔肩赬。","澀旋皮卷臠，苦开腹彭亨。","機舂潺湲力，吹簸飄颻精。","賽饌木盤簇，靸妖藤索絣。","荒学五六卷，古藏四三塋。","里儒拳足拜，土怪閃眸偵。","蹄道補复破，絲窠掃還成。","暮堂蝙蝠沸，破竈伊威盈。","追此訊前主，荅云皆冢卿。","敗壁剝寒月，折篁嘯遺笙。","袿熏霏霏在，綦跡微微呈。","劒石猶竦檻，獸材尚拏楹。","寶唾拾未尽，玉啼墮猶鎗。","窗綃疑閟豔，妝燭已銷檠。","綠髮抽珉甃，青膚聳瑤楨。","白蛾飞舞地，幽蠹落书棚。","惟昔集嘉詠，吐芳類鳴嚶。","窺奇摘海異，恣韻激天鯨。","腸胃繞万象，精神驱五兵。","蜀雄李杜拔，嶽力雷车轟。","大句斡玄造，高言軋霄崢。","芒端轉寒燠，神助溢杯觥。","巨細各乘運，湍潿亦腾声。","凌花咀粉蘂，削縷穿珠櫻。","綺語洗晴雪，嬌辞哢雛鶯。","酣歡杂弁珥，繁價流金瓊。","菡萏寫江調，萎蕤綴藍瑛。","庖霜膾玄鯽，淅玉炊香稉。","朝饌已百態，春醪又千名。","哀匏蹙駛景，冽唱凝餘晶。","解魄不自主，痺肌坐空瞠。","扳援賤蹊絕，炫曜仙選更。","藂巧競采笑，駢鲜互探嬰。","桑变忽蕪蔓，樟裁浪登丁。","霞鬬詎能極，风期誰复賡。","臯區扶帝壤，瓌蘊郁天京。","祥色被文彥，良才插杉檉。","隐伏饒氣象，兴潛示堆坑。","擘华露神物，擁終儲地禎。","訏謨壯締始，輔弼登階清。","坌秀恣填塞，呀靈滀渟澄。","益大聯漢魏，肇初邁周嬴。","積照涵德镜，傳經儷金籯。","食家行鼎鼐，寵族飫弓旌。","奕制尽從賜，殊私得逾程。","飞橋上架漢，繚岸俯規瀛。","瀟碧远輸委，湖嵌費携擎。","萄苜從大漠，楓櫧至南荆。","嘉植鲜危朽，膏理易滋榮。","懸长巧紐翠，象曲善攢珩。","鱼口星浮沒，马毛錦斑騂。","五方亂风土，百種分鉏耕。","葩蘖相妬出，菲茸共舒晴。","類招臻倜詭，翼萃伏衿纓。","危望跨飞动，冥升躡登閎。","春游轢靃靡，彩伴颯嫈嫇。","遺燦飄的皪，淑顏洞精誠。","嬌應如在寤，頹意若含酲。","鵷毳翔衣带，鵝肪截佩璜。","文升相照灼，武勝屠欃槍。","割錦不酬價，構云有高營。","通波牣鱗介，疏畹富蕭蘅。","買養馴孔翠，远苞樹蕉栟。","鴻头排刺芡，鵠𪇄攢瓌橙。","騖廣杂良牧，蒙休賴先盟。","罷旄奉环衛，守封踐忠貞。","戰服脫明介，朝冠飄彩紘。","爵勳逮僮隸，簪笏自懷繃。","乳下秀嶷嶷，椒蕃泣喤喤。","貌鑑清溢匣，眸光寒發硎。","館儒養經史，綴戚觴孫甥。","考鐘饋殽核，戛鼓侑牢牲。","飞膳自北下，函珍極东烹。","如瓜煮大卵，比線茹芳菁。","海嶽錯口腹，趙燕錫媌娙。","一笑釋仇恨，百金交弟兄。","貨至貊戎市，呼傳鸚鵒令。","順居無鬼瞰，抑橫免官評。","殺候肆凌翦，籠原匝罝紭。","羽空顛雉鷃，血路迸狐麖。","折足去踸踔，蹙鬐怒䰃鬤。","躍犬疾翥鸟，呀鷹甚飢䖟。","算蹄記功賞，裂腦擒摚掁。","猛斃牛马乐，妖殘梟鵅惸。","窟窮尚嗔視，箭出方驚抨。","連箱載已實，礙轍棄仍贏。","喘覰鋒刃点，困衝株枿盲。","掃淨豁曠曠，騁遙略苹苹。","饞杈飽活臠，惡嚼𠽢腥鯖。","歲律及郊至，古音命韶韺。","旗斾流日月，帳廬扶棟甍。","磊落奠鴻璧，參差席香藑。","玄祇祉兆姓，黑秬饛豐盛。","慶流蠲瘥癘，威暢捐䡴輣。","靈燔望高冏，龙駕闻敲𩙁。","是惟禮之盛，永用表其宏。","德孕厚生植，恩熙完刖剠。","宅土尽华族，連田间強甿。","蔭庾森嶺檜，啄場翽祥䳟。","畦肥翦韭●，陶固收盆甖。","利養積餘健，孝思事嚴祊。","掘云破嵽嵲，采月漉坳泓。","寺砌上明镜，僧盂敲晓鉦。","泥象对騁怪，鐵鐘孤舂鍠。","癭頸鬧鳩鴿，蜿垣亂蛷蠑。","葚黑老蠶蠋，麦黄韻鸝鶊。","韶曙遲勝賞，賢明戒先庚。","驰门填偪仄，競墅輾砯砰。","碎纈紅满杏，稠凝碧浮餳。","蹙繩覲娥婺，鬬草擷璣珵。","粉汗澤廣額，金星墮連瓔。","鼻偷困淑郁，眼剽強盯𥋝。","是節飽顏色，茲疆稱都城。","书饒罄鱼繭，紀盛播琴箏。","奚必事远覿，無端逐羇傖。","將身親魍魅，浮跡侶鷗鶄。","腥味空奠屈，天年徒羨彭。","驚魂见蛇蚓，觸齅值蝦蟚。","幸得履中氣，忝從拂天棖。","归私暫休暇，驱明出庠黌。","鲜意竦轻暢，連輝照瓊瑩。","陶暄逐风乙，躍視舞晴蜻。","足勝自多詣，心貪敵無勍。","始知乐名教，何用苦拘儜。","畢景任诗趣，焉能守硜硜。"]', '诗', 'shi', '', NULL, '城南聯句 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9828863-e92e-4aad-bc05-209438dd31f5', '會合聯句', '會合聯句', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["離別言無期，會合意彌重。","病添兒女戀，老喪丈夫勇。","劒心知未死，詩思猶孤聳。","愁去劇箭飛，歡來若泉涌。","析言多新貫，攄抱無昔壅。","念難須勤追，悔易勿輕踵。","吟巴山犖嶨，說楚波堆壟。","馬辭虎豹怒，舟出蛟鼉恐。","狂鯨時孤軒，幽狖雜百種。","瘴衣常腥膩，蠻器多疎宂。","剝苔弔斑林，角飯餌沈冢。","忽爾銜遠命，歸歟舞新寵。","鬼窟脫幽妖，天居覿清栱。","京遊步方振，謫夢意猶恟。","詩書誇舊知，酒食接新奉。","嘉言寫清越，瘉病失肬腫。","夏陰偶高庇，宵魄接虛擁。","雪弦寂寂聽，茗盌纖纖捧。","馳輝燭浮螢，幽響泄潛蛬。","詩老獨何心，江疾有餘尰。","我家本瀍穀，有地介臯鞏。","休跡憶沈冥，峨冠慙闒𤾖。","升朝高轡逸，振物羣聽悚。","徒言濯幽泌，誰與薙荒茸。","朝紳鬱青綠，馬飾曜珪珙。","國讐未銷鑠，我志蕩邛隴。","君才誠倜儻，時論方洶溶。","格言多彪蔚，懸解無梏拲。","張生得淵源，寒色拔山冢。","堅如撞羣金，眇若抽獨蛹。","伊余何所擬，跛鼈詎能踊。","塊然墮岳石，飄爾罥巢氄。","龍斾垂天衛，雲韶凝禁甬。","君胡眠安然，朝鼓聲洶洶。"]', '["離別言無期，會合意彌重。","病添兒女戀，老喪丈夫勇。","劒心知未死，诗思猶孤聳。","愁去劇箭飞，歡来若泉涌。","析言多新貫，攄抱無昔壅。","念难須勤追，悔易勿轻踵。","吟巴山犖嶨，说楚波堆壟。","马辞虎豹怒，舟出蛟鼉恐。","狂鯨时孤軒，幽狖杂百種。","瘴衣常腥膩，蠻器多疎宂。","剝苔弔斑林，角飯餌沈冢。","忽爾銜远命，归歟舞新寵。","鬼窟脫幽妖，天居覿清栱。","京游步方振，謫梦意猶恟。","诗书誇旧知，酒食接新奉。","嘉言寫清越，瘉病失肬腫。","夏陰偶高庇，宵魄接虛擁。","雪弦寂寂听，茗盌纖纖捧。","驰輝燭浮螢，幽响泄潛蛬。","诗老独何心，江疾有餘尰。","我家本瀍穀，有地介臯鞏。","休跡憶沈冥，峨冠慙闒𤾖。","升朝高轡逸，振物羣听悚。","徒言濯幽泌，誰與薙荒茸。","朝紳鬱青綠，马飾曜珪珙。","国讐未銷鑠，我志蕩邛隴。","君才誠倜儻，时論方洶溶。","格言多彪蔚，懸解無梏拲。","張生得淵源，寒色拔山冢。","堅如撞羣金，眇若抽独蛹。","伊余何所擬，跛鼈詎能踊。","塊然墮岳石，飄爾罥巢氄。","龙斾垂天衛，云韶凝禁甬。","君胡眠安然，朝鼓声洶洶。"]', '诗', 'shi', '', NULL, '會合聯句 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3932a98c-45b7-4754-9cb7-6e00eeb2971a', '鬬雞聯句', '鬬雞聯句', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["大雞昂然來，小雞竦而待。","崢嶸顛盛氣，洗刷凝鮮彩。","高行若矜豪，側睨如伺殆。","精光目相射，劒戟心獨在。","既取冠爲胄，復以距爲鐓。","天時得清寒，地利挾爽塏。","磔毛各噤㾕，怒癭爭碨磊。","俄膺忽爾低，植立瞥而改。","腷膊戰聲喧，繽飜落羽皠。","中休事未決，小挫勢益倍。","妬腸務生敵，賊性專相醢。","裂血失鳴聲，啄殷甚飢餒。","對起何急驚，隨旋誠巧紿。","毒手飽李陽，神槌困朱亥。","惻心我以仁，碎首爾何罪。","獨勝事有然，旁驚汗流浼。","知雄欣動顏，怯負愁看賄。","爭觀雲填道，助叫波飜海。","事爪深難解，嗔睛時未怠。","一噴一醒然，再接再礪乃。","頭垂碎丹砂，翼搨拖錦綵。","連軒尚賈餘，清厲比歸凱。","選俊感收毛，受恩慙始隗。","英心甘鬬死，義肉恥庖宰。","君看鬬雞篇，短韻有可采。"]', '["大雞昂然来，小雞竦而待。","崢嶸顛盛氣，洗刷凝鲜彩。","高行若矜豪，側睨如伺殆。","精光目相射，劒戟心独在。","既取冠爲胄，复以距爲鐓。","天时得清寒，地利挾爽塏。","磔毛各噤㾕，怒癭爭碨磊。","俄膺忽爾低，植立瞥而改。","腷膊戰声喧，繽飜落羽皠。","中休事未決，小挫勢益倍。","妬腸務生敵，賊性專相醢。","裂血失鳴声，啄殷甚飢餒。","对起何急驚，隨旋誠巧紿。","毒手飽李陽，神槌困朱亥。","惻心我以仁，碎首爾何罪。","独勝事有然，旁驚汗流浼。","知雄欣动顏，怯負愁看賄。","爭观云填道，助叫波飜海。","事爪深难解，嗔睛时未怠。","一噴一醒然，再接再礪乃。","头垂碎丹砂，翼搨拖錦綵。","連軒尚賈餘，清厲比归凱。","選俊感收毛，受恩慙始隗。","英心甘鬬死，義肉恥庖宰。","君看鬬雞篇，短韻有可采。"]', '诗', 'shi', '', NULL, '鬬雞聯句 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdb4a42a-f2dc-46bc-b47a-19434f475c22', '納涼聯句', '納涼聯句', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["遞嘯取遙風，微微近秋朔。","金柔氣尚低，火老候愈濁。","熙熙炎光流，竦竦高雲擢。","閃紅驚蚴虯，凝赤聳山嶽。","目林恐焚燒，耳井憶瀺灂。","仰懼失交泰，非時結冰雹。","化鄧渴且多，奔河誠已慤。","暍道者誰子，叩商者何樂。","洗矣得滂沱，感然鳴鸑鷟。","嘉願苟未從，前心空緬邈。","清砌千迴坐，冷環再三握。","煩懷却星星，高意還卓卓。","龍沈劇煮鱗，牛喘甚焚角。","蟬煩鳴轉喝，烏噪飢不啄。","晝蠅食案繁，宵蚋肌血渥。","單絺厭已褫，長䈉倦還捉。","幸茲得佳朋，於此蔭華桷。","青熒文簟施，淡澉甘瓜濯。","大壁曠凝淨，古畫奇駁犖。","淒如羾寒門，皓若攢玉璞。","埽寬延鮮飆，汲冷漬香穱。","篚實摘林珍，盤殽饋禽㲉。","空堂喜淹留，貧饌羞齷齪。","殷勤相勸勉，左右加礱斲。","賈勇發霜硎，爭前曜冰槊。","微然草根響，先被詩情覺。","感衰悲舊改，工異逞新貌。","誰言擯朋老，猶自將心學。","危檐不敢憑，朽機懼傾撲。","青雲路難近，黃鶴足仍鋜。","未能飲淵泉，立滯叫芳葯。","與子昔睽離，嗟余苦屯剝。","直道敗邪徑，拙謀傷巧諑。","炎湖度氛氳，熱石行犖硞。","痟肌夏尤甚，瘧渴秋更數。","君顏不可覿，君手無由搦。","今來沐新恩，庶見返鴻朴。","儒庠恣游息，聖籍飽商搉。","危行無低徊，正言免咿喔。","車馬獲同驅，酒醪欣共欶。","惟憂棄菅蒯，敢望侍帷幄。","此志且何如，希君爲追琢。"]', '["遞嘯取遙风，微微近秋朔。","金柔氣尚低，火老候愈濁。","熙熙炎光流，竦竦高云擢。","閃紅驚蚴虯，凝赤聳山嶽。","目林恐焚燒，耳井憶瀺灂。","仰懼失交泰，非时結冰雹。","化鄧渴且多，奔河誠已慤。","暍道者誰子，叩商者何乐。","洗矣得滂沱，感然鳴鸑鷟。","嘉願苟未從，前心空緬邈。","清砌千迴坐，冷环再三握。","煩懷却星星，高意還卓卓。","龙沈劇煮鱗，牛喘甚焚角。","蟬煩鳴轉喝，烏噪飢不啄。","晝蠅食案繁，宵蚋肌血渥。","單絺厭已褫，长䈉倦還捉。","幸茲得佳朋，於此蔭华桷。","青熒文簟施，淡澉甘瓜濯。","大壁曠凝淨，古畫奇駁犖。","淒如羾寒门，皓若攢玉璞。","埽寬延鲜飆，汲冷漬香穱。","篚實摘林珍，盤殽饋禽㲉。","空堂喜淹留，貧饌羞齷齪。","殷勤相勸勉，左右加礱斲。","賈勇發霜硎，爭前曜冰槊。","微然草根响，先被诗情覺。","感衰悲旧改，工異逞新貌。","誰言擯朋老，猶自將心学。","危檐不敢憑，朽機懼傾撲。","青云路难近，黄鹤足仍鋜。","未能饮淵泉，立滯叫芳葯。","與子昔睽離，嗟余苦屯剝。","直道敗邪徑，拙謀傷巧諑。","炎湖度氛氳，熱石行犖硞。","痟肌夏尤甚，瘧渴秋更數。","君顏不可覿，君手無由搦。","今来沐新恩，庶见返鴻朴。","儒庠恣游息，聖籍飽商搉。","危行無低徊，正言免咿喔。","车马獲同驱，酒醪欣共欶。","惟憂棄菅蒯，敢望侍帷幄。","此志且何如，希君爲追琢。"]', '诗', 'shi', '', NULL, '納涼聯句 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56fc63f1-446e-4b6a-96a2-cf0c34fac211', '秋雨聯句', '秋雨聯句', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["萬木聲號呼，百川氣交會。","庭飜樹離合，牖變景明藹。","潨瀉殊未終，飛浮亦云泰。","牽懷到空山，屬聽邇驚瀨。","檐垂白練直，渠漲清湘大。","甘津澤祥禾，伏潤肥荒艾。","主人吟有歡，客子歌無奈。","侵陽日沈玄，剝節風搜兌。","坱圠遊峽喧，颼飀臥江汰。","微飄來枕前，高灑自天外。","蛬穴何迫迮，蟬枝埽鳴噦。","楥菊茂新芳，徑蘭銷晚馤。","地鏡時昏曉，池星競漂沛。","讙呶尋一聲，灌注咽羣籟。","儒宮煙火溼，市舍煎熬忲。","臥冷空避門，衣寒屢循帶。","水怒已倒流，陰繁恐凝害。","憂魚思舟檝，感禹勤畎澮。","懷襄信可畏，疏決須有賴。","筮命或馮蓍，卜晴將問蔡。","庭商忽驚舞，墉禜亦親酹。","氛醨稍疎映，雺亂還擁薈。","陰旌時摎流，帝鼓鎮訇磕。","棗圃落青璣，瓜畦爛文貝。","貧薪不燭竈，富粟空填廥。","秦俗動言利，魯儒欲何匄。","深路倒羸驂，弱途擁行軑。","毛羽皆遭凍，離褷不能翽。","飜浪洗虛空，傾濤敗藏蓋。","吾人猶在陳，僮僕誠自鄶。","因思征蜀士，未免溼戎斾。","安得發商飆，廓然吹宿靄。","白日懸大野，幽泥化輕壒。","戰場暫一乾，賊肉行可膾。","搜心思有效，抽策期稱最。","豈惟慮收穫，亦以救顛沛。","禽情初嘯儔，礎色微收霈。","庶幾諧我願，遂止無已太。"]', '["万木声號呼，百川氣交會。","庭飜樹離合，牖变景明藹。","潨瀉殊未終，飞浮亦云泰。","牽懷到空山，屬听邇驚瀨。","檐垂白練直，渠漲清湘大。","甘津澤祥禾，伏潤肥荒艾。","主人吟有歡，客子歌無奈。","侵陽日沈玄，剝節风搜兌。","坱圠游峽喧，颼飀臥江汰。","微飄来枕前，高灑自天外。","蛬穴何迫迮，蟬枝埽鳴噦。","楥菊茂新芳，徑蘭銷晚馤。","地镜时昏晓，池星競漂沛。","讙呶尋一声，灌注咽羣籟。","儒宮煙火溼，市舍煎熬忲。","臥冷空避门，衣寒屢循带。","水怒已倒流，陰繁恐凝害。","憂鱼思舟檝，感禹勤畎澮。","懷襄信可畏，疏決須有賴。","筮命或馮蓍，卜晴將问蔡。","庭商忽驚舞，墉禜亦親酹。","氛醨稍疎映，雺亂還擁薈。","陰旌时摎流，帝鼓鎮訇磕。","棗圃落青璣，瓜畦爛文貝。","貧薪不燭竈，富粟空填廥。","秦俗动言利，魯儒欲何匄。","深路倒羸驂，弱途擁行軑。","毛羽皆遭凍，離褷不能翽。","飜浪洗虛空，傾濤敗藏蓋。","吾人猶在陳，僮僕誠自鄶。","因思征蜀士，未免溼戎斾。","安得發商飆，廓然吹宿靄。","白日懸大野，幽泥化轻壒。","戰場暫一乾，賊肉行可膾。","搜心思有效，抽策期稱最。","豈惟慮收穫，亦以救顛沛。","禽情初嘯儔，礎色微收霈。","庶幾諧我願，遂止無已太。"]', '诗', 'shi', '', NULL, '秋雨聯句 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cf29ef3-76c8-420c-906a-3aab88dce825', '征蜀聯句', '征蜀聯句', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["日王忿違慠，有命事誅拔。","蜀險豁關防，秦師縱橫猾。","風旗匝地揚，雷鼓轟天殺。","竹兵彼皴脆，鐵刃我槍䶪。","刑神咤犛旄，陰燄颭犀札。","飜霓紛偃蹇，塞野澒坱圠。","生獰競掣跌，癡突爭填軋。","渴鬬信豗呶，噉奸何噢嗗。","更呼相簸蕩，交斫雙缺齾。","火發激鋩腥，血漂騰足滑。","飛猱無整陣，翩鶻有邪戛。","江倒沸鯨鯤，山搖潰貙䝟。","中離分二三，外變迷七八。","逆頸盡徽索，仇頭恣髠鬝。","怒鬚猶鬇鬡，斷臂仍𤬁𤫶。","石潛設奇伏，穴覰騁精察。","中矢類妖㺑，跳鋒狀驚豽。","蹋飜聚林嶺，斗起成埃圿。","斾亡多空杠，軸折鮮聯轄。","剟膚浹瘡痍，敗面碎剠㓤。","渾奔肆狂勷，捷竄脫趫黠。","巖鉤踔狙猨，水漉雜鱣螖。","投奅鬧䃔䃧，填隍𠋘㑻𠋚。","強睛死不閉，獷眼困逾䀣。","爇堞熇歊熺，抉門呀拗䦪。","天刀封未坼，酋膽懾前揠。","跧梁排郁縮，闖竇揳窋窡。","迫脅聞雜驅，咿呦叫冤{⻊兀}。","窮區指清夷，兇部坐雕鎩。","邛文裁斐斖，巴豔收婠妠。","椎肥牛呼牟，載實駝鳴𡇼。","聖靈閔頑嚚，燾養均草䕓。","下書遏雄虓，解罪弔攣瞎。","戰血時銷洗，劒霜夜清刮。","漢棧罷囂闐，獠江息澎汃。","戍寒絕朝乘，刁暗歇宵詧。","始去杏飛蠭，及歸柳嘶𧉒。","廟獻繁馘級，樂聲洞椌楬。","臺圖煥丹玄，郊告儼匏稭。","念齒慰黴黧，視傷悼瘢痆。","休輸任訛寢，報力厚麩秳。","公歡鐘晨撞，室宴絲曉扴。","杯盂酬酒醪，箱篋饋巾帓。","小臣昧戎經，維用贊勳劼。"]', '["日王忿違慠，有命事誅拔。","蜀險豁关防，秦師縱橫猾。","风旗匝地揚，雷鼓轟天殺。","竹兵彼皴脆，鐵刃我槍䶪。","刑神咤犛旄，陰燄颭犀札。","飜霓紛偃蹇，塞野澒坱圠。","生獰競掣跌，癡突爭填軋。","渴鬬信豗呶，噉奸何噢嗗。","更呼相簸蕩，交斫雙缺齾。","火發激鋩腥，血漂腾足滑。","飞猱無整陣，翩鶻有邪戛。","江倒沸鯨鯤，山搖潰貙䝟。","中離分二三，外变迷七八。","逆頸尽徽索，仇头恣髠鬝。","怒鬚猶鬇鬡，斷臂仍𤬁𤫶。","石潛設奇伏，穴覰騁精察。","中矢類妖㺑，跳鋒狀驚豽。","蹋飜聚林嶺，斗起成埃圿。","斾亡多空杠，軸折鲜聯轄。","剟膚浹瘡痍，敗面碎剠㓤。","渾奔肆狂勷，捷竄脫趫黠。","巖鉤踔狙猨，水漉杂鱣螖。","投奅鬧䃔䃧，填隍𠋘㑻𠋚。","強睛死不閉，獷眼困逾䀣。","爇堞熇歊熺，抉门呀拗䦪。","天刀封未坼，酋膽懾前揠。","跧梁排郁縮，闖竇揳窋窡。","迫脅闻杂驱，咿呦叫冤{⻊兀}。","窮區指清夷，兇部坐雕鎩。","邛文裁斐斖，巴豔收婠妠。","椎肥牛呼牟，載實駝鳴𡇼。","聖靈閔頑嚚，燾養均草䕓。","下书遏雄虓，解罪弔攣瞎。","戰血时銷洗，劒霜夜清刮。","漢棧罷囂闐，獠江息澎汃。","戍寒絕朝乘，刁暗歇宵詧。","始去杏飞蠭，及归柳嘶𧉒。","廟獻繁馘級，乐声洞椌楬。","台圖煥丹玄，郊告儼匏稭。","念齒慰黴黧，視傷悼瘢痆。","休輸任訛寢，報力厚麩秳。","公歡鐘晨撞，室宴絲晓扴。","杯盂酬酒醪，箱篋饋巾帓。","小臣昧戎經，維用贊勳劼。"]', '诗', 'shi', '', NULL, '征蜀聯句 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99aa50fb-e645-453d-9762-a6622be195ae', '同宿聯句', '同宿聯句', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["自從別君來，遠出遭巧譖。","斑斑落春淚，浩浩浮秋浸。","毛奇覩象犀，羽怪見鵩鴆。","朝行多危棧，夜臥饒驚枕。","生榮今分踰，死棄昔情任。","鵷行參綺陌，雞唱聞清禁。","山晴指高標，槐密騖長蔭。","直辭一以薦，巧舌千皆𦧈。","匡鼎惟說詩，桓譚不讀讖。","逸韻何嘈嗷，高名俟沽賃。","紛葩歡屢填，曠朗憂早滲。","爲君開酒腸，顛倒舞相飲。","曦光霽曙物，景曜鑠宵祲。","儒門雖大啓，奸首不敢闖。","義泉雖至近，盜索不敢沁。","清琴試一揮，白鶴叫相喑。","欲知心同樂，雙繭抽作絍。"]', '["自從別君来，远出遭巧譖。","斑斑落春泪，浩浩浮秋浸。","毛奇覩象犀，羽怪见鵩鴆。","朝行多危棧，夜臥饒驚枕。","生榮今分踰，死棄昔情任。","鵷行參綺陌，雞唱闻清禁。","山晴指高標，槐密騖长蔭。","直辞一以薦，巧舌千皆𦧈。","匡鼎惟说诗，桓譚不读讖。","逸韻何嘈嗷，高名俟沽賃。","紛葩歡屢填，曠朗憂早滲。","爲君开酒腸，顛倒舞相饮。","曦光霽曙物，景曜鑠宵祲。","儒门雖大啓，奸首不敢闖。","義泉雖至近，盜索不敢沁。","清琴試一揮，白鹤叫相喑。","欲知心同乐，雙繭抽作絍。"]', '诗', 'shi', '', NULL, '同宿聯句 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('991b8b2a-11e3-4ea8-8ed9-3e02c807a232', '莎柵聯句', '莎柵聯句', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["冰溪時咽絕，風櫪方軒舉。","此處不斷腸，定知無斷處。"]', '["冰溪时咽絕，风櫪方軒舉。","此处不斷腸，定知無斷处。"]', '诗', 'shi', '', NULL, '莎柵聯句 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34a198e6-7d61-4aac-b5d5-d92312e28649', '雨中寄孟刑部幾道聯句', '雨中寄孟刑部幾道聯句', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["秋潦淹轍迹，高居限參拜。","耿耿蓄良思，遙遙仰嘉話。","一晨長隔歲，百步遠殊界。","商聽饒清聳，悶懷空抑噫。","美君知道腴，逸步謝天械。","吟馨鑠紛雜，抱照瑩疑怪。","撞宏聲不掉，輸邈瀾逾殺。","檐瀉碎江喧，街流淺溪邁。","念初相遭逢，幸免因媒介。","祛煩類決癰，愜興劇爬疥。","研文較幽玄，呼博騁雄快。","今君軺方馳，伊我羽已鎩。","溫存感深惠，琢切奉明誡。","迨茲更凝情，暫阻若嬰瘵。","欲知相從盡，靈珀拾纖芥。","欲知相益多，神藥銷宿憊。","德符仙山岸，永立難欹壞。","氣涵秋天河，有朗無驚湃。","祥鳳遺蒿鷃，雲韶掩夷靺。","爭名求鵠徒，騰口甚蟬喝。","未來聲已赫，始鼓敵前敗。","鬬場再鳴先，遐路一飛屆。","東野繼奇躅，修綸懸衆犗。","穿空細丘垤，照日陋菅蒯。","小生何足道，積慎如觸蠆。","愔愔抱所諾，翼翼自申戒。","聖書空勘讀，盜食敢求嘬。","惟當騎款段，豈望覿珪玠。","弱操愧筠杉，微芳比蕭●。","何以驗高明，柔中有剛夬。"]', '["秋潦淹轍迹，高居限參拜。","耿耿蓄良思，遙遙仰嘉話。","一晨长隔歲，百步远殊界。","商听饒清聳，悶懷空抑噫。","美君知道腴，逸步謝天械。","吟馨鑠紛杂，抱照瑩疑怪。","撞宏声不掉，輸邈瀾逾殺。","檐瀉碎江喧，街流淺溪邁。","念初相遭逢，幸免因媒介。","祛煩類決癰，愜兴劇爬疥。","研文較幽玄，呼博騁雄快。","今君軺方驰，伊我羽已鎩。","溫存感深惠，琢切奉明誡。","迨茲更凝情，暫阻若嬰瘵。","欲知相從尽，靈珀拾纖芥。","欲知相益多，神藥銷宿憊。","德符仙山岸，永立难欹壞。","氣涵秋天河，有朗無驚湃。","祥鳳遺蒿鷃，云韶掩夷靺。","爭名求鵠徒，腾口甚蟬喝。","未来声已赫，始鼓敵前敗。","鬬場再鳴先，遐路一飞屆。","东野繼奇躅，修綸懸衆犗。","穿空細丘垤，照日陋菅蒯。","小生何足道，積慎如觸蠆。","愔愔抱所諾，翼翼自申戒。","聖书空勘读，盜食敢求嘬。","惟當騎款段，豈望覿珪玠。","弱操愧筠杉，微芳比蕭●。","何以驗高明，柔中有剛夬。"]', '诗', 'shi', '', NULL, '雨中寄孟刑部幾道聯句 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('629687ee-7e6f-4b7a-8c3d-2034d5e752da', '遠遊聯句', '远游聯句', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["別腸車輪轉，一日一萬周。","離思春冰泮，瀾漫不可收。","馳光忽以迫，飛轡誰能留。","取之詎灼灼，此去信悠悠。","楚客宿江上，夜魂棲浪頭。","曉日生遠岸，水芳綴孤舟。","村飲泊好木，野蔬拾新柔。","獨含悽悽別，中結鬱鬱愁。","人憶舊行樂，鳥吟新得儔。","靈瑟時窅窅，霠猨夜啾啾。","憤濤氣尚盛，恨竹淚空幽。","長懷絕無已，多感良自尤。","即路涉獻歲，歸期眇涼秋。","兩歡日牢落，孤悲坐綢繆。","觀怪忽蕩漾，叩奇獨冥搜。","海鯨吞明月，浪島沒大漚。","我有一寸鈎，欲釣千丈流。","良知忽然遠，壯志鬱無抽。","魍魅暫出沒，蛟螭互蟠蟉。","昌言拜舜禹，舉颿凌斗牛。","懷糈餽賢屈，乘桴追聖丘。","飄然天外步，豈肯區中囚。","楚些待誰弔，賈辭緘恨投。","翳明弗可曉，祕魂安所求。","氣毒放逐域，蓼雜芳菲疇。","當春忽淒涼，不枯亦颼飀。","貉謠衆猥款，巴語相咿嚘。","默誓去外俗，嘉願還中州。","江生行既樂，躬輦自相勠。","飲醇趣明代，味腥謝荒陬。","馳深鼓利檝，趨險驚蜚輶。","繫石沈靳尚，開弓射鴅吺。","路暗執屏翳，波驚戮陽侯。","廣泛信縹緲，高行恣浮游。","外患蕭蕭去，中悒稍稍瘳。","振衣造雲闕，跪坐陳清猷。","德風變讒巧，仁氣銷戈矛。","名聲照西海，淑問無時休。","歸哉孟夫子，歸去無夷猶。"]', '["別腸车輪轉，一日一万周。","離思春冰泮，瀾漫不可收。","驰光忽以迫，飞轡誰能留。","取之詎灼灼，此去信悠悠。","楚客宿江上，夜魂棲浪头。","晓日生远岸，水芳綴孤舟。","村饮泊好木，野蔬拾新柔。","独含悽悽別，中結鬱鬱愁。","人憶旧行乐，鸟吟新得儔。","靈瑟时窅窅，霠猨夜啾啾。","憤濤氣尚盛，恨竹泪空幽。","长懷絕無已，多感良自尤。","即路涉獻歲，归期眇涼秋。","兩歡日牢落，孤悲坐綢繆。","观怪忽蕩漾，叩奇独冥搜。","海鯨吞明月，浪島沒大漚。","我有一寸鈎，欲釣千丈流。","良知忽然远，壯志鬱無抽。","魍魅暫出沒，蛟螭互蟠蟉。","昌言拜舜禹，舉颿凌斗牛。","懷糈餽賢屈，乘桴追聖丘。","飄然天外步，豈肯區中囚。","楚些待誰弔，賈辞緘恨投。","翳明弗可晓，祕魂安所求。","氣毒放逐域，蓼杂芳菲疇。","當春忽淒涼，不枯亦颼飀。","貉謠衆猥款，巴語相咿嚘。","默誓去外俗，嘉願還中州。","江生行既乐，躬輦自相勠。","饮醇趣明代，味腥謝荒陬。","驰深鼓利檝，趨險驚蜚輶。","繫石沈靳尚，开弓射鴅吺。","路暗執屏翳，波驚戮陽侯。","廣泛信縹緲，高行恣浮游。","外患蕭蕭去，中悒稍稍瘳。","振衣造云闕，跪坐陳清猷。","德风变讒巧，仁氣銷戈矛。","名声照西海，淑问無时休。","归哉孟夫子，归去無夷猶。"]', '诗', 'shi', '', NULL, '遠遊聯句 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0056864-b83d-42a0-8d6b-c0b3a654f67d', '晚秋郾城夜會聯句', '晚秋郾城夜會聯句', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["從軍古云樂，談笑青油幕。","燈明夜觀棊，月暗秋城柝。","羈客方寂歷，驚烏時落泊。","語闌壯氣衰，酒醒寒砧作。","遇主貴陳力，夷凶匪兼弱。","百牢犒輿師，千戶購首惡。","平生恥論兵，末暮不輕諾。","徒然感恩義，誰復論勳爵。","多士被霑汚，小夷施毒蠚。","何當鑄劒戟，相與歸臺閣。","室婦歡鳴鸛，家人祝喜鵲。","終朝考蓍龜，何日親蒸礿。","間使斷津梁，潛軍索林薄。","紅塵羽書靖，大水沙囊涸。","銘山子所工，插羽余何怍。","未足煩刀俎，祗應輸管鑰。","雨矢逐天狼，電矛驅海若。","靈誅固無縱，力戰誰敢却。","峨峨雲梯翔，赫赫火箭著。","連空隳雉堞，照夜焚城郭。","軍門宣一令，廟算建三略。","雷鼓揭千槍，浮橋交萬筰。","蹂野馬雲騰，映原旗火鑠。","疲氓墜將拯，殘虜狂可縛。","摧鋒若貙兕，超乘如猱玃。","逢掖服飜慙，縵胡纓可愕。","星隕聞雊雉，師興隨唳鶴。","虎豹貪犬羊，鷹鸇憎鳥雀。","燒陂除積聚，灌壘失依託。","憑軾諭昏迷，執殳征暴虐。","倉空戰卒飢，月黑探兵錯。","兇徒更蹈藉，逆族相啗嚼。","軸轤亙淮泗，斾旌連夏鄂。","大野縱氐羌，長河浴騮駱。","東西競角逐，遠近施矰繳。","人怨童聚謠，天殃鬼行虐。","漢刑支郡黜，周制閑田削。","侯社退無功，鬼薪懲不恪。","余雖司斧鑕，情本尚丘壑。","且待獻俘囚，終當返耕穫。","藁街陳鈇鉞，桃塞興錢鎛。","地理畫封疆，天文埽寥廓。","天子憫瘡痍，將軍禁鹵掠。","策勳封龍頟，歸獸獲麟脚。","詰誅敬王怒，給復哀人瘼。","澤髮解兜鍪，酡顏傾鑿落。","安存惟恐晚，洗雪不論昨。","暮鳥已安巢，春蠶看滿箔。","聲明動朝闕，光寵耀京洛。","旁午降絲綸，中堅擁鼓鐸。","密坐列珠翠，高門塗粉雘。","跋朝賀書飛，塞路歸鞍躍。","魏闕橫雲漢，秦關束巖㟧。","拜迎羅櫜鞬，問遺結囊橐。","江淮永清晏，宇宙重開拓。","是日號升平，此年名作噩。","洪赦方下究，武飆亦旁魄。","南據定蠻陬，北攫空朔漠。","儒生愜教化，武士猛刺斫。","吾相兩優游，他人雙落莫。","印從負鼎佩，門爲登壇鑿。","再入更顯嚴，九遷彌謇諤。","賓筵盡狐趙，導騎多衛霍。","國史擅芬芳，宮娃分綽約。","丹掖列鵷鷺，洪爐衣狐貉。","摛文揮月毫，講劒淬霜鍔。","命衣備藻火，賜樂兼附搏。","兩廂鋪𣰽毺，五鼎調勺藥。","帶垂蒼玉佩，轡蹙黃金絡。","誘接喻登龍，趨馳狀傾藿。","青娥翳長袖，紅頰吹鳴籥。","儻不忍辛勤，何由恣歡謔。","惟當早富貴，豈得暫寂寞。","但擲雇笑金，仍祈却老藥。","歿廟配尊斝，生堂合毊鑮。","安行庇松篁，高臥枕莞蒻。","洗沐恣蘭芷，割烹厭腗臄。","喜顏非忸怩，達志無隕穫。","詼諧酒席展，慷慨戎裝著。","斬馬祭旄纛，包羔禮芒屩。","山多離隱豹，野有求伸蠖。","推選閱羣材，薦延搜一鶚。","左右供諂譽，親交獻諛噱。","名聲載揄揚，權勢實熏灼。","道舊生感激，當歌發酬酢。","羣孫輕綺紈，下客豐醴酪。","窮天貢琛異，匝海賜酺醵。","作樂鼓還槌，從禽弓始彍。","取歡移日飲，求勝通宵博。","五白氣爭呼，六奇心運度。","恩澤誠布濩，嚚頑已簫勺。","告成上云亭，考古垂矩矱。","前堂清夜吹，東第良晨酌。","池蓮拆秋房，院竹飜夏籜。","五狩朝恆岱，三畋宿楊柞。","農書乍討論，馬法長懸格。","雪下收新息，陽生過京索。","爾牛時寢訛，我僕或歌咢。","帝載彌天地，臣辭劣螢爝。","爲詩安能詳，庶用存糟粕。"]', '["從軍古云乐，談笑青油幕。","灯明夜观棊，月暗秋城柝。","羈客方寂歷，驚烏时落泊。","語闌壯氣衰，酒醒寒砧作。","遇主貴陳力，夷凶匪兼弱。","百牢犒輿師，千戶購首惡。","平生恥論兵，末暮不轻諾。","徒然感恩義，誰复論勳爵。","多士被霑汚，小夷施毒蠚。","何當鑄劒戟，相與归台閣。","室婦歡鳴鸛，家人祝喜鵲。","終朝考蓍龟，何日親蒸礿。","间使斷津梁，潛軍索林薄。","紅塵羽书靖，大水沙囊涸。","銘山子所工，插羽余何怍。","未足煩刀俎，祗應輸管鑰。","雨矢逐天狼，電矛驱海若。","靈誅固無縱，力戰誰敢却。","峨峨云梯翔，赫赫火箭著。","連空隳雉堞，照夜焚城郭。","軍门宣一令，廟算建三略。","雷鼓揭千槍，浮橋交万筰。","蹂野马云腾，映原旗火鑠。","疲氓墜將拯，殘虜狂可縛。","摧鋒若貙兕，超乘如猱玃。","逢掖服飜慙，縵胡纓可愕。","星隕闻雊雉，師兴隨唳鹤。","虎豹貪犬羊，鷹鸇憎鸟雀。","燒陂除積聚，灌壘失依託。","憑軾諭昏迷，執殳征暴虐。","倉空戰卒飢，月黑探兵錯。","兇徒更蹈藉，逆族相啗嚼。","軸轤亙淮泗，斾旌連夏鄂。","大野縱氐羌，长河浴騮駱。","东西競角逐，远近施矰繳。","人怨童聚謠，天殃鬼行虐。","漢刑支郡黜，周制闲田削。","侯社退無功，鬼薪懲不恪。","余雖司斧鑕，情本尚丘壑。","且待獻俘囚，終當返耕穫。","藁街陳鈇鉞，桃塞兴錢鎛。","地理畫封疆，天文埽寥廓。","天子憫瘡痍，將軍禁鹵掠。","策勳封龙頟，归獸獲麟脚。","詰誅敬王怒，給复哀人瘼。","澤髮解兜鍪，酡顏傾鑿落。","安存惟恐晚，洗雪不論昨。","暮鸟已安巢，春蠶看满箔。","声明动朝闕，光寵耀京洛。","旁午降絲綸，中堅擁鼓鐸。","密坐列珠翠，高门塗粉雘。","跋朝賀书飞，塞路归鞍躍。","魏闕橫云漢，秦关束巖㟧。","拜迎羅櫜鞬，问遺結囊橐。","江淮永清晏，宇宙重开拓。","是日號升平，此年名作噩。","洪赦方下究，武飆亦旁魄。","南據定蠻陬，北攫空朔漠。","儒生愜教化，武士猛刺斫。","吾相兩優游，他人雙落莫。","印從負鼎佩，门爲登壇鑿。","再入更显嚴，九遷彌謇諤。","賓筵尽狐趙，導騎多衛霍。","国史擅芬芳，宮娃分綽約。","丹掖列鵷鷺，洪爐衣狐貉。","摛文揮月毫，講劒淬霜鍔。","命衣備藻火，賜乐兼附搏。","兩廂鋪𣰽毺，五鼎調勺藥。","带垂蒼玉佩，轡蹙黄金絡。","誘接喻登龙，趨驰狀傾藿。","青娥翳长袖，紅頰吹鳴籥。","儻不忍辛勤，何由恣歡謔。","惟當早富貴，豈得暫寂寞。","但擲雇笑金，仍祈却老藥。","歿廟配尊斝，生堂合毊鑮。","安行庇松篁，高臥枕莞蒻。","洗沐恣蘭芷，割烹厭腗臄。","喜顏非忸怩，達志無隕穫。","詼諧酒席展，慷慨戎裝著。","斬马祭旄纛，包羔禮芒屩。","山多離隐豹，野有求伸蠖。","推選閱羣材，薦延搜一鶚。","左右供諂譽，親交獻諛噱。","名声載揄揚，權勢實熏灼。","道旧生感激，當歌發酬酢。","羣孫轻綺紈，下客豐醴酪。","窮天貢琛異，匝海賜酺醵。","作乐鼓還槌，從禽弓始彍。","取歡移日饮，求勝通宵博。","五白氣爭呼，六奇心運度。","恩澤誠布濩，嚚頑已簫勺。","告成上云亭，考古垂矩矱。","前堂清夜吹，东第良晨酌。","池蓮拆秋房，院竹飜夏籜。","五狩朝恆岱，三畋宿楊柞。","農书乍討論，马法长懸格。","雪下收新息，陽生過京索。","爾牛时寢訛，我僕或歌咢。","帝載彌天地，臣辞劣螢爝。","爲诗安能詳，庶用存糟粕。"]', '诗', 'shi', '', NULL, '晚秋郾城夜會聯句 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d8d8c41-eb86-4279-84a8-f8c0ac204cdb', '石鼎聯句', '石鼎聯句', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["巧匠斲山骨，刳中事煎烹。","直柄未當權，塞口且吞聲。","龍頭縮菌蠢，豕腹漲彭亨。","外苞乾蘚文，中有暗浪驚。","在冷足自安，遭焚意彌貞。","謬當鼎鼐間，妄使水火爭。","大似烈士膽，圓如戰馬纓。","上比香爐尖，下與鏡面平。","秋瓜未落蔕，凍芋強抽萌。","一塊元氣閉，細泉幽竇傾。","不值輸寫處，焉知懷抱清。","方當洪爐然，益見小器盈。","睆睆無刃迹，團團類天成。","遙疑龜負圖，出曝曉正晴。","旁有雙耳穿，上有孤髻撐。","或訝短尾銚，又似無足鐺。","可惜寒食毬，擲此傍路坑。","何當出灰灺，無計離缾罌。","陋質荷斟酌，狹中媿提擎。","豈能煮仙藥，但未汙羊羹。","形模婦女笑，度量兒童輕。","徒示堅重性，不過升合盛。","傍似廢轂仰，側見折軸橫。","時於蚯蚓竅，微作蒼蠅鳴。","以茲飜溢愆，實負任使誠。","常居顧盼地，敢有漏泄情。","寧依暖熱弊，不與寒涼幷。","區區徒自效，瑣瑣不足呈。","回旋但兀兀，開闔惟[鏗鏗]。","全勝瑚璉貴，空有口傳名。","豈比俎豆古，不爲手所撜。","磨礱去圭角，浸潤著光精。","願君莫嘲誚，此物方施行。"]', '["巧匠斲山骨，刳中事煎烹。","直柄未當權，塞口且吞声。","龙头縮菌蠢，豕腹漲彭亨。","外苞乾蘚文，中有暗浪驚。","在冷足自安，遭焚意彌貞。","謬當鼎鼐间，妄使水火爭。","大似烈士膽，圓如戰马纓。","上比香爐尖，下與镜面平。","秋瓜未落蔕，凍芋強抽萌。","一塊元氣閉，細泉幽竇傾。","不值輸寫处，焉知懷抱清。","方當洪爐然，益见小器盈。","睆睆無刃迹，團團類天成。","遙疑龟負圖，出曝晓正晴。","旁有雙耳穿，上有孤髻撐。","或訝短尾銚，又似無足鐺。","可惜寒食毬，擲此傍路坑。","何當出灰灺，無計離缾罌。","陋質荷斟酌，狹中媿提擎。","豈能煮仙藥，但未汙羊羹。","形模婦女笑，度量兒童轻。","徒示堅重性，不過升合盛。","傍似廢轂仰，側见折軸橫。","时於蚯蚓竅，微作蒼蠅鳴。","以茲飜溢愆，實負任使誠。","常居顧盼地，敢有漏泄情。","寧依暖熱弊，不與寒涼幷。","區區徒自效，瑣瑣不足呈。","回旋但兀兀，开闔惟[鏗鏗]。","全勝瑚璉貴，空有口傳名。","豈比俎豆古，不爲手所撜。","磨礱去圭角，浸潤著光精。","願君莫嘲誚，此物方施行。"]', '诗', 'shi', '', NULL, '石鼎聯句 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6693bd3c-6a2b-4090-bcac-6d6a5a3538ee', '有所思聯句', '有所思聯句', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["相思繞我心，日夕千萬重。","年光坐婉娩，春淚銷顏容。","臺鏡晦舊暉，庭草滋深茸。","望夫山上石，別劒水中龍。"]', '["相思繞我心，日夕千万重。","年光坐婉娩，春泪銷顏容。","台镜晦旧暉，庭草滋深茸。","望夫山上石，別劒水中龙。"]', '诗', 'shi', '', NULL, '有所思聯句 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a548bf0-2a16-46d1-9b9c-8db15d0bfc54', '遣興聯句', '遣兴聯句', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["我心隨月光，寫君庭中央。","月光有時晦，我心安所忘。","常恐金石契，斷爲相思腸。","平生無百歲，岐路有四方。","四方各異俗，適異非所將。","駑蹄顧挫秣，逸翮遺稻粱。","時危抱獨沈，道泰懷同翔。","獨居久寂默，相顧聊慨慷。","慨慷丈夫志，可以曜鋒鋩。","蘧甯知卷舒，孔顏識行藏。","殷鑒諒不遠，佩蘭永芬芳。","苟無夫子聽，誰使知音揚。"]', '["我心隨月光，寫君庭中央。","月光有时晦，我心安所忘。","常恐金石契，斷爲相思腸。","平生無百歲，岐路有四方。","四方各異俗，適異非所將。","駑蹄顧挫秣，逸翮遺稻粱。","时危抱独沈，道泰懷同翔。","独居久寂默，相顧聊慨慷。","慨慷丈夫志，可以曜鋒鋩。","蘧甯知卷舒，孔顏識行藏。","殷鑒諒不远，佩蘭永芬芳。","苟無夫子听，誰使知音揚。"]', '诗', 'shi', '', NULL, '遣興聯句 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a6e9180-49c1-4713-be3d-a3fd53d50e5e', '贈劒客李園聯句', '贈劒客李园聯句', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["天地有靈術，得之者惟君。","築爐地區外，積火燒氛氳。","照海鑠幽怪，滿空歊異氛。","山磨電奕奕，水淬龍蝹蝹。","太一裝以寶，列仙篆其文。","可用懾百神，豈惟壯三軍。","有時幽匣吟，忽似深潭聞。","風胡久已死，此劒將誰分。","行當獻天子，然後致殊勳。","豈知豐城下，空有斗間雲。"]', '["天地有靈術，得之者惟君。","築爐地區外，積火燒氛氳。","照海鑠幽怪，满空歊異氛。","山磨電奕奕，水淬龙蝹蝹。","太一裝以寶，列仙篆其文。","可用懾百神，豈惟壯三軍。","有时幽匣吟，忽似深潭闻。","风胡久已死，此劒將誰分。","行當獻天子，然後致殊勳。","豈知豐城下，空有斗间云。"]', '诗', 'shi', '', NULL, '贈劒客李園聯句 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4476668-8330-4664-a1ef-757a54961c56', '過海聯句', '過海聯句', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["沙鳥浮還沒，山雲斷復連。","櫂穿波底月，船壓水中天。"]', '["沙鸟浮還沒，山云斷复連。","櫂穿波底月，船壓水中天。"]', '诗', 'shi', '', NULL, '過海聯句 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e78d31b7-0bc5-48a6-91ca-36cdca85bb93', '妓席與杜牧之同詠', '妓席與杜牧之同詠', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["骰子逡巡裹手拈，無因得見玉纖纖。","但知報道金釵落，髣髴還應露指尖。"]', '["骰子逡巡裹手拈，無因得见玉纖纖。","但知報道金釵落，髣髴還應露指尖。"]', '诗', 'shi', '', NULL, '妓席與杜牧之同詠 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe6526d1-3f9e-400a-8220-65c922e28b3e', '同趙二十二訪張明府郊居聯句', '同趙二十二訪張明府郊居聯句', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["陶潛官罷酒缾空，門掩楊花一夜風。","古調詩吟山色裏，無弦琴在月明中。","遠檐高樹宜幽鳥，出岫孤雲逐晚虹。","別後東籬數枝菊，不知閑醉與誰同。"]', '["陶潛官罷酒缾空，门掩楊花一夜风。","古調诗吟山色裏，無弦琴在月明中。","远檐高樹宜幽鸟，出岫孤云逐晚虹。","別後东籬數枝菊，不知闲醉與誰同。"]', '诗', 'shi', '', NULL, '同趙二十二訪張明府郊居聯句 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b89cb78-6444-44c8-b05f-0c05369060c4', '遊長安諸寺聯句 靖恭坊大興善寺 老松青桐聯二十字絕句', '游长安諸寺聯句 靖恭坊大兴善寺 老松青桐聯二十字絕句', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["有松堪繫馬，遇鉢更投鍼。","記得湯師句，高禪助朗吟。","乘晴入精舍，語默想東林。","盡是忘機侶，誰驚息影禽。","一雨微塵盡，支郎許數過。","方同齅薝蔔，不用算多羅。"]', '["有松堪繫马，遇鉢更投鍼。","記得湯師句，高禪助朗吟。","乘晴入精舍，語默想东林。","尽是忘機侶，誰驚息影禽。","一雨微塵尽，支郎許數過。","方同齅薝蔔，不用算多羅。"]', '诗', 'shi', '', NULL, '遊長安諸寺聯句 靖恭坊大興善寺 老松青桐聯二十字絕句 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7e6edd9-f281-4e0b-ade7-6137f877c644', '遊長安諸寺聯句 靖恭坊大興善寺 蛤像聯二十字絕句', '游长安諸寺聯句 靖恭坊大兴善寺 蛤像聯二十字絕句', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["相好全如梵，端倪祗爲隋。","寧同蚌頑惡，但與鷸相持。","雖因雀變化，不逐月虧盈。","縱有天中匠，神工詎可成。"]', '["相好全如梵，端倪祗爲隋。","寧同蚌頑惡，但與鷸相持。","雖因雀变化，不逐月虧盈。","縱有天中匠，神工詎可成。"]', '诗', 'shi', '', NULL, '遊長安諸寺聯句 靖恭坊大興善寺 蛤像聯二十字絕句 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff52cb43-155a-47be-9d87-d830d5b151d4', '遊長安諸寺聯句 靖恭坊大興善寺 聖柱聯句', '游长安諸寺聯句 靖恭坊大兴善寺 聖柱聯句', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["天心惟助善，聖跡此開陽。","載恐雷輪重，絙疑電索長。","上衝挾螮蝀，不動束鋃鐺。","飢鳥未曾啄，乖龍寧敢藏。"]', '["天心惟助善，聖跡此开陽。","載恐雷輪重，絙疑電索长。","上衝挾螮蝀，不动束鋃鐺。","飢鸟未曾啄，乖龙寧敢藏。"]', '诗', 'shi', '', NULL, '遊長安諸寺聯句 靖恭坊大興善寺 聖柱聯句 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d485a48-caca-4a64-91ad-894d91f93c80', '遊長安諸寺聯句 長樂坊安國寺 紅樓聯句', '游长安諸寺聯句 长乐坊安国寺 紅楼聯句', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["重疊碎晴空，餘霞更照紅。","蟬蹤近鳷鵲，鳥道接相風。","苔靜金輪路，雲輕白日宮。","壁詩傳謝客，門牓占休公。"]', '["重叠碎晴空，餘霞更照紅。","蟬蹤近鳷鵲，鸟道接相风。","苔静金輪路，云轻白日宮。","壁诗傳謝客，门牓占休公。"]', '诗', 'shi', '', NULL, '遊長安諸寺聯句 長樂坊安國寺 紅樓聯句 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d391f36-31e3-44d7-8512-c40009a9a9ef', '遊長安諸寺聯句 長樂坊安國寺 穗柏聯句', '游长安諸寺聯句 长乐坊安国寺 穗柏聯句', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["一院暑難侵，莓苔共影深。","標枝爭息鳥，餘吹正開襟。","宿雨香添色，殘陽石在陰。","乘閑動詩意，助靜入禪心。"]', '["一院暑难侵，莓苔共影深。","標枝爭息鸟，餘吹正开襟。","宿雨香添色，殘陽石在陰。","乘闲动诗意，助静入禪心。"]', '诗', 'shi', '', NULL, '遊長安諸寺聯句 長樂坊安國寺 穗柏聯句 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a033932-752e-4e17-9cae-6f583594421e', '遊長安諸寺聯句 長樂坊安國寺 題璘公院', '游长安諸寺聯句 长乐坊安国寺 題璘公院', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["靜，虛。","熱際，安居。","龕燈斂，印香除。","東林賓客，西澗圖書。","檐外垂青豆，經中發白蕖。","縱辯宗因衮衮，忘言理事如如。","泉臺定將入流否，鄰笛足疑清梵餘。"]', '["静，虛。","熱際，安居。","龕灯斂，印香除。","东林賓客，西澗圖书。","檐外垂青豆，經中發白蕖。","縱辯宗因衮衮，忘言理事如如。","泉台定將入流否，鄰笛足疑清梵餘。"]', '诗', 'shi', '', NULL, '遊長安諸寺聯句 長樂坊安國寺 題璘公院 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e54fae26-a908-43de-98df-93b05b447913', '遊長安諸寺聯句 常樂坊趙景公寺 吳畫聯句', '游长安諸寺聯句 常乐坊趙景公寺 吳畫聯句', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["慘澹十堵內，吳生縱狂跡。","風雲將逼人，神鬼如脫壁。","其中龍最怪，張甲方汗栗。","黑雲夜窸窣，焉知不霹靂。","此際忽仙子，獵獵衣舃奕。","妙瞬乍疑生，參差奪人魄。","往往乘猛虎，衝梁聳奇石。","蒼峭束高泉，角膝驚欹側。","冥獄不可視，毛戴腋流液。","苟能水成河，剎那沈火宅。"]', '["慘澹十堵內，吳生縱狂跡。","风云將逼人，神鬼如脫壁。","其中龙最怪，張甲方汗栗。","黑云夜窸窣，焉知不霹靂。","此際忽仙子，獵獵衣舃奕。","妙瞬乍疑生，參差奪人魄。","往往乘猛虎，衝梁聳奇石。","蒼峭束高泉，角膝驚欹側。","冥獄不可視，毛戴腋流液。","苟能水成河，剎那沈火宅。"]', '诗', 'shi', '', NULL, '遊長安諸寺聯句 常樂坊趙景公寺 吳畫聯句 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fd20295-962c-46f6-902a-984f83b730e3', '遊長安諸寺聯句 常樂坊趙景公寺 題約公院', '游长安諸寺聯句 常乐坊趙景公寺 題約公院', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["印火熒熒，燈續燄青。","七俱胝咒，四阿含經。","各錄佳語，聊事素屏。","丈室安居，延賓不扃。"]', '["印火熒熒，灯續燄青。","七俱胝咒，四阿含經。","各錄佳語，聊事素屏。","丈室安居，延賓不扃。"]', '诗', 'shi', '', NULL, '遊長安諸寺聯句 常樂坊趙景公寺 題約公院 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bdb1a24-689f-41b3-881f-168934c13230', '遊長安諸寺聯句 大同坊雲華寺 偶聯句', '游长安諸寺聯句 大同坊云华寺 偶聯句', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["共入夕陽寺，因窺甘露門。","清香惹苔蘚，忍草雜蘭蓀。","捷偈飛鉗荅，新詩倚杖論。","壞幡標古剎，聖畫煥崇垣。","豈慕穿籠鳥，難防在牖猿。","一音唯一性，三語更三幡。"]', '["共入夕陽寺，因窺甘露门。","清香惹苔蘚，忍草杂蘭蓀。","捷偈飞鉗荅，新诗倚杖論。","壞幡標古剎，聖畫煥崇垣。","豈慕穿籠鸟，难防在牖猿。","一音唯一性，三語更三幡。"]', '诗', 'shi', '', NULL, '遊長安諸寺聯句 大同坊雲華寺 偶聯句 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5fc52f1-826f-44b8-8840-b0816da20c13', '遊長安諸寺聯句 道政坊寶應寺 僧房聯句', '游长安諸寺聯句 道政坊寶應寺 僧房聯句', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["古畫思匡嶺，上方疑傅巖。","蝶閑移忍草，蟬曉揭高杉。","香字消芝印，金經發茝函。","井通松底脈，書坼洞中緘。"]', '["古畫思匡嶺，上方疑傅巖。","蝶闲移忍草，蟬晓揭高杉。","香字消芝印，金經發茝函。","井通松底脈，书坼洞中緘。"]', '诗', 'shi', '', NULL, '遊長安諸寺聯句 道政坊寶應寺 僧房聯句 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5908ea6e-b35f-467c-9a2e-222033f8c47f', '遊長安諸寺聯句 道政坊寶應寺 小小寫真聯句', '游长安諸寺聯句 道政坊寶應寺 小小寫真聯句', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["如生小小真，猶自未棲塵。","褕袂將離座，斜柯欲近人。","昔時知出衆，情寵占橫陳。","不遣遊張巷，豈教窺宋鄰。","庾樓吹笛裂，弘閣賞歌新。","蟬怯纖腰步，蛾驚半額嚬。","圖形誰有術，買笑詎辭貧。","複隴迷村徑，重泉隔漢津。","同心知作羽，比目定爲鱗。","殘月巫山夕，餘霞洛浦晨。"]', '["如生小小真，猶自未棲塵。","褕袂將離座，斜柯欲近人。","昔时知出衆，情寵占橫陳。","不遣游張巷，豈教窺宋鄰。","庾楼吹笛裂，弘閣賞歌新。","蟬怯纖腰步，蛾驚半額嚬。","圖形誰有術，買笑詎辞貧。","複隴迷村徑，重泉隔漢津。","同心知作羽，比目定爲鱗。","殘月巫山夕，餘霞洛浦晨。"]', '诗', 'shi', '', NULL, '遊長安諸寺聯句 道政坊寶應寺 小小寫真聯句 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1703e40e-b76e-405f-ae20-491c41427b05', '遊長安諸寺聯句 平康坊菩薩寺 書事聯句', '游长安諸寺聯句 平康坊菩薩寺 书事聯句', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["悉爲無事者，任被俗流憎。","客異干時客，僧非出院僧。","遠聞疎牖磬，曉辨密龕燈。","步觸珠旛響，吟窺鉢水澄。","句饒方外趣，遊愜社中朋。","靜裏已馴鴿，齋中亦好鷹。","金塗筆是褧，彩溜紙非繒。","錫杖已剋鍛，田衣從懷塍。","占牀暫一脅，卷箔賴長肱。","佛日初開照，魔天破幾層。","咒中陳祕計，論處正先登。","勇帶綻鍼石，危防丘井藤。"]', '["悉爲無事者，任被俗流憎。","客異干时客，僧非出院僧。","远闻疎牖磬，晓辨密龕灯。","步觸珠旛响，吟窺鉢水澄。","句饒方外趣，游愜社中朋。","静裏已馴鴿，斋中亦好鷹。","金塗笔是褧，彩溜紙非繒。","錫杖已剋鍛，田衣從懷塍。","占牀暫一脅，卷箔賴长肱。","佛日初开照，魔天破幾層。","咒中陳祕計，論处正先登。","勇带綻鍼石，危防丘井藤。"]', '诗', 'shi', '', NULL, '遊長安諸寺聯句 平康坊菩薩寺 書事聯句 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d88a3098-c01c-4930-babe-d6c134afaad5', '遊長安諸寺聯句 光宅坊光宅寺 中禪師影堂聯句', '游长安諸寺聯句 光宅坊光宅寺 中禪師影堂聯句', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["名下固無虛，敖曹貌嚴毅。","洞達見空王，圓融入佛地。","一言當要害，忽忽醒諸醉。","不動須彌山，多方辯無匱。","坦率對萬乘，偈荅無所避。","爾如毘沙門，外形如脫履。","但以理爲量，不語怪力事。","木石摧貢高，慈悲引貪恚。","當時乏支許，何人契深致。","隨宜詎說三，直下開不二。"]', '["名下固無虛，敖曹貌嚴毅。","洞達见空王，圓融入佛地。","一言當要害，忽忽醒諸醉。","不动須彌山，多方辯無匱。","坦率对万乘，偈荅無所避。","爾如毘沙门，外形如脫履。","但以理爲量，不語怪力事。","木石摧貢高，慈悲引貪恚。","當时乏支許，何人契深致。","隨宜詎说三，直下开不二。"]', '诗', 'shi', '', NULL, '遊長安諸寺聯句 光宅坊光宅寺 中禪師影堂聯句 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0b59988-260c-4e65-a5b5-d7c7d18b9268', '遊長安諸寺聯句 翊善坊保壽寺 光天幀讚聯句', '游长安諸寺聯句 翊善坊保壽寺 光天幀讚聯句', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["觀音化身，厥形孔怪。","胣腦淫厲，衆魔膜拜。","指夢鴻紛，牓列區界。","其事明張，何不可解。","閻阿德川，大士先天。","衆象參羅，福源田田。","百億花發，百千燈然。","膠如[絡繹]，浩汗連緜。","燄摩界戚，洛迦苦霽。","正念皈依，衆青如𥶙。","戾滓可汰，癡膜可蛻。","稽首如空，睟容若睇。","闡提墨師，覩而面之。","寸念不生，未遇乎而。"]', '["观音化身，厥形孔怪。","胣腦淫厲，衆魔膜拜。","指梦鴻紛，牓列區界。","其事明張，何不可解。","閻阿德川，大士先天。","衆象參羅，福源田田。","百億花發，百千灯然。","膠如[絡繹]，浩汗連緜。","燄摩界戚，洛迦苦霽。","正念皈依，衆青如𥶙。","戾滓可汰，癡膜可蛻。","稽首如空，睟容若睇。","闡提墨師，覩而面之。","寸念不生，未遇乎而。"]', '诗', 'shi', '', NULL, '遊長安諸寺聯句 翊善坊保壽寺 光天幀讚聯句 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55b3c9cc-9b0b-4ed7-92ee-29b01c690c9f', '遊長安諸寺聯句 宣陽坊靜域寺 三階院聯句', '游长安諸寺聯句 宣陽坊静域寺 三階院聯句', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["密密助堂堂，隋人歌檿桑。","雙弧摧孔雀，一矢隕貪狼。","百步望雲立，九規看月張。","獲蛟徒破浪，中乙漫如牆。","還似貫金鼓，更疑穿石梁。","因添挽河力，爲滅射天狂。","絕藝却南牧，英聲來鬼方。","麗龜何足敵，殪豕未爲長。","龍臂勝猨臂，星芒超箭芒。","虛誇絕高鳥，垂拱議明堂。"]', '["密密助堂堂，隋人歌檿桑。","雙弧摧孔雀，一矢隕貪狼。","百步望云立，九規看月張。","獲蛟徒破浪，中乙漫如牆。","還似貫金鼓，更疑穿石梁。","因添挽河力，爲滅射天狂。","絕藝却南牧，英声来鬼方。","丽龟何足敵，殪豕未爲长。","龙臂勝猨臂，星芒超箭芒。","虛誇絕高鸟，垂拱議明堂。"]', '诗', 'shi', '', NULL, '遊長安諸寺聯句 宣陽坊靜域寺 三階院聯句 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bde6a3a-097b-4517-bd28-bc985819bf74', '遊長安諸寺聯句 崇義坊招福院 贈諸上人聯句', '游长安諸寺聯句 崇義坊招福院 贈諸上人聯句', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["飜了西天偈，燒餘梵宇香。","撚眉愁俗客，支頰背殘陽。","洲號惟思沃，山名祗記匡。","辨中摧世智，定裏破魔強。","許叡禪心徹，湯休詩思長。","朗吟疎磬斷，久語貫珠妨。","乘興書芭葉，閑來入豆房。","漫題存古壁，怪畫匝長廊。"]', '["飜了西天偈，燒餘梵宇香。","撚眉愁俗客，支頰背殘陽。","洲號惟思沃，山名祗記匡。","辨中摧世智，定裏破魔強。","許叡禪心徹，湯休诗思长。","朗吟疎磬斷，久語貫珠妨。","乘兴书芭葉，闲来入豆房。","漫題存古壁，怪畫匝长廊。"]', '诗', 'shi', '', NULL, '遊長安諸寺聯句 崇義坊招福院 贈諸上人聯句 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20d1e419-7b2a-4ef0-bef7-67de4d6a3e55', '遊長安諸寺聯句 招國坊崇濟寺 奇松聯二十字絕句', '游长安諸寺聯句 招国坊崇濟寺 奇松聯二十字絕句', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["杉松何相疎，榆柳方迥屑。","無人擅談柄，一枝不敢折。","中庭苔蘚深，吹餘鳴佛禽。","至於摧折枝，凡草猶避陰。","僻徑根從露，閑房枝任侵。","一株風正好，來助碧雲吟。","時時埽窗聲，重露滴寒砌。","風颭一枝遒，閑窺別生勢。","偃蓋入樓妨，盤根侵井窄。","高僧獨惆悵，爲與澄嵐隔。"]', '["杉松何相疎，榆柳方迥屑。","無人擅談柄，一枝不敢折。","中庭苔蘚深，吹餘鳴佛禽。","至於摧折枝，凡草猶避陰。","僻徑根從露，闲房枝任侵。","一株风正好，来助碧云吟。","时时埽窗声，重露滴寒砌。","风颭一枝遒，闲窺別生勢。","偃蓋入楼妨，盤根侵井窄。","高僧独惆悵，爲與澄嵐隔。"]', '诗', 'shi', '', NULL, '遊長安諸寺聯句 招國坊崇濟寺 奇松聯二十字絕句 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('710c35fe-bd6c-4c1d-9175-2db7eb5541d6', '遊長安諸寺聯句 永安坊永壽寺 閑中好', '游长安諸寺聯句 永安坊永壽寺 闲中好', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["閑中好，盡日松爲侶。","此趣人不知，輕風度僧語。","閑中好，塵務不縈心。","坐對當窗木，看移三面陰。","閑中好，幽磬度聲遲。","卷上論題肇，畫中僧姓支。"]', '["闲中好，尽日松爲侶。","此趣人不知，轻风度僧語。","闲中好，塵務不縈心。","坐对當窗木，看移三面陰。","闲中好，幽磬度声遲。","卷上論題肇，畫中僧姓支。"]', '诗', 'shi', '', NULL, '遊長安諸寺聯句 永安坊永壽寺 閑中好 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5288376-7ae6-4eff-a3d3-f57639918688', '遊長安諸寺聯句 崇仁坊資聖寺 諸畫聯句', '游长安諸寺聯句 崇仁坊資聖寺 諸畫聯句', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["吳生畫勇矛戟攢，出變奇勢千萬端。","蒼蒼鬼怪層壁寬，覩之忽忽毛髮寒。","稜伽之力所疲殫，李真周昉優劣難。","活禽生卉推邊鸞，花房嫩彩猶未乾。","韓幹變態如激湍，惜哉壁畫世未殫。","後人新畫何汗漫。"]', '["吳生畫勇矛戟攢，出变奇勢千万端。","蒼蒼鬼怪層壁寬，覩之忽忽毛髮寒。","稜伽之力所疲殫，李真周昉優劣难。","活禽生卉推邊鸾，花房嫩彩猶未乾。","韓幹变態如激湍，惜哉壁畫世未殫。","後人新畫何汗漫。"]', '诗', 'shi', '', NULL, '遊長安諸寺聯句 崇仁坊資聖寺 諸畫聯句 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2299b727-1e00-43b6-92b9-54010cba43ef', '北禪院避暑聯句', '北禪院避暑聯句', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["歊蒸何處避，來入戴顒宅。","逍遙脫單絞，放曠拋輕策。","爬搔林下風，偃仰澗中石。","殘蟬煙外響，野鶴沙中跡。","到此失煩襟，蕭然揖禪伯。","藤懸疊霜蛻，桂倚支雲錫。","清陰豎毛髮，爽氣舒筋脈。","逐幽隨竹書，選勝鋪苮席。","魚跳上紫芡，蝶化緣青壁。","心是玉蓮徒，耳爲金磬敵。","吾宗昔高尚，志在羲皇易。","豈獨斷韋編，幾將刓鐵擿。","天書既屢降，野抱難自適。","一入承明廬，盱衡論今昔。","流光不容寸，斯道甘枉尺。","既起謝儒玄，亦飜商羽翼。","封章帷幄徧，夢寐江湖白。","擺落函谷塵，高欹華陽幘。","詔去雲無信，歸來鶴相識。","半病奪牛公，全慵捕魚客。","少微光一點，落此芒磔索。","釋子問池塘，門人廢幽賾。","堪悲東序寶，忽變西方籍。","不見步兵詩，空懷康樂屐。","高名不可效，勝境徒堪惜。","墨沼轉疎蕪，玄齋踰闃寂。","遲遲不可去，涼颸滿杉柏。","日下洲島清，煙生苾蒭碧。","俱懷出塵想，共有吟詩癖。","終與淨名遊，還來雪山覓。"]', '["歊蒸何处避，来入戴顒宅。","逍遙脫單絞，放曠拋轻策。","爬搔林下风，偃仰澗中石。","殘蟬煙外响，野鹤沙中跡。","到此失煩襟，蕭然揖禪伯。","藤懸叠霜蛻，桂倚支云錫。","清陰豎毛髮，爽氣舒筋脈。","逐幽隨竹书，選勝鋪苮席。","鱼跳上紫芡，蝶化緣青壁。","心是玉蓮徒，耳爲金磬敵。","吾宗昔高尚，志在羲皇易。","豈独斷韋編，幾將刓鐵擿。","天书既屢降，野抱难自適。","一入承明廬，盱衡論今昔。","流光不容寸，斯道甘枉尺。","既起謝儒玄，亦飜商羽翼。","封章帷幄徧，梦寐江湖白。","擺落函谷塵，高欹华陽幘。","詔去云無信，归来鹤相識。","半病奪牛公，全慵捕鱼客。","少微光一点，落此芒磔索。","釋子问池塘，门人廢幽賾。","堪悲东序寶，忽变西方籍。","不见步兵诗，空懷康乐屐。","高名不可效，勝境徒堪惜。","墨沼轉疎蕪，玄斋踰闃寂。","遲遲不可去，涼颸满杉柏。","日下洲島清，煙生苾蒭碧。","俱懷出塵想，共有吟诗癖。","終與淨名游，還来雪山覓。"]', '诗', 'shi', '', NULL, '北禪院避暑聯句 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12b1c09c-67db-47cb-becf-3bab54672f16', '寂上人院聯句', '寂上人院聯句', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["癭牀空默坐，清景不知斜。","暗數菩提子，閑看薜茘花。","有情惟墨客，無語是禪家。","背日聊依桂，嘗泉欲試茶。","石形蹲玉虎，池影閃金蛇。","經笥安巖匼，缾囊挂樹椏。","書傳滄海外，龕寄白雲涯。","竹色寒凌箔，燈光靜隔紗。","趁幽飜小品，逐勝講南華。","莎彩融黃露，蓮衣染素霞。","水堪傷聚沫，風合落天葩。","若許傳心印，何辭古堞賒。"]', '["癭牀空默坐，清景不知斜。","暗數菩提子，闲看薜茘花。","有情惟墨客，無語是禪家。","背日聊依桂，嘗泉欲試茶。","石形蹲玉虎，池影閃金蛇。","經笥安巖匼，缾囊挂樹椏。","书傳滄海外，龕寄白云涯。","竹色寒凌箔，灯光静隔紗。","趁幽飜小品，逐勝講南华。","莎彩融黄露，蓮衣染素霞。","水堪傷聚沫，风合落天葩。","若許傳心印，何辞古堞賒。"]', '诗', 'shi', '', NULL, '寂上人院聯句 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2958440-f0ed-4aaa-9e85-197165673259', '獨在開元寺避暑頗懷魯望因飛筆聯句', '独在开元寺避暑頗懷魯望因飞笔聯句', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["煩署雖難避，僧家自有期。","泉甘於馬乳，苔滑似龍漦。","任誕襟全散，臨幽榻旋移。","松行將雅拜，篁陣欲交麾。","望塔青𩩉識，登樓白鴿知。","石經森欲動，珠像儼將怡。","筠簟臨杉穗，紗巾透雨絲。","靜譚蟬噪少，涼步鶴隨遲。","煙重迴蕉扇，輕風拂桂帷。","對碑吳地說，開卷梵天詞。","積水魚梁壞，殘花病枕欹。","懷君瀟灑處，孤夢繞罘罳。"]', '["煩署雖难避，僧家自有期。","泉甘於马乳，苔滑似龙漦。","任誕襟全散，臨幽榻旋移。","松行將雅拜，篁陣欲交麾。","望塔青𩩉識，登楼白鴿知。","石經森欲动，珠像儼將怡。","筠簟臨杉穗，紗巾透雨絲。","静譚蟬噪少，涼步鹤隨遲。","煙重迴蕉扇，轻风拂桂帷。","对碑吳地说，开卷梵天词。","積水鱼梁壞，殘花病枕欹。","懷君瀟灑处，孤梦繞罘罳。"]', '诗', 'shi', '', NULL, '獨在開元寺避暑頗懷魯望因飛筆聯句 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('048624af-09cd-4637-820a-917a9eb1bc4a', '寒夜文宴聯句', '寒夜文宴聯句', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["文星今夜聚，應在斗牛間。","載石人方至，乘槎客未還。","送觴繁露曲，徵句白雲顏。","節奏惟聽竹，從容只話山。","理窮傾祕藏，論猛折玄關。","酃酒分中綠，巴箋擘處殷。","清言聞後醒，強韻壓來艱。","犀柄當風揖，瓊枝向月攀。","松吟方㗫㗫，泉夢憶潺潺。","一會文章草，昭明不可刪。"]', '["文星今夜聚，應在斗牛间。","載石人方至，乘槎客未還。","送觴繁露曲，徵句白云顏。","節奏惟听竹，從容只話山。","理窮傾祕藏，論猛折玄关。","酃酒分中綠，巴箋擘处殷。","清言闻後醒，強韻壓来艱。","犀柄當风揖，瓊枝向月攀。","松吟方㗫㗫，泉梦憶潺潺。","一會文章草，昭明不可刪。"]', '诗', 'shi', '', NULL, '寒夜文宴聯句 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e72a645-d864-437f-be33-6d15dd640ec6', '藥名聯句', '藥名聯句', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["爲待防風餅，須添薏苡杯。","香然柏子後，尊泛菊花來。","石耳泉能洗，垣衣雨爲裁。","從容犀局靜，斷續玉琴哀。","白芷寒猶采，青箱醉尚開。","馬銜衰草臥，烏啄蠹根迴。","雨過蘭芳好，霜多桂末摧。","朱兒應作粉，雲母詎成灰。","藝可屠龍膽，家曾近燕胎。","牆高牽薜茘，障輭撼玫瑰。","鸓鼠啼書戶，蝸牛上研臺。","誰能將藁本，封與玉泉才。"]', '["爲待防风餅，須添薏苡杯。","香然柏子後，尊泛菊花来。","石耳泉能洗，垣衣雨爲裁。","從容犀局静，斷續玉琴哀。","白芷寒猶采，青箱醉尚开。","马銜衰草臥，烏啄蠹根迴。","雨過蘭芳好，霜多桂末摧。","朱兒應作粉，云母詎成灰。","藝可屠龙膽，家曾近燕胎。","牆高牽薜茘，障輭撼玫瑰。","鸓鼠啼书戶，蝸牛上研台。","誰能將藁本，封與玉泉才。"]', '诗', 'shi', '', NULL, '藥名聯句 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5cd830d-49e0-4f40-9a39-5c8eebbc2af3', '寒夜聯句', '寒夜聯句', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["靜境揖神凝，寒華射林缺。","清知思緒斷，爽覺心源徹。","高唱戛金奏，朗詠鏗玉節。","我思方泬寥，君詞復淒切。","況聞風篁上，擺落殘凍雪。","寂爾萬籟清，皎然諸靄滅。","西窗客無夢，南浦波應結。","河光正如劒，月魄方似玦。","短燼不禁挑，冷毫看欲折。","何夕重相期，濁醪還爲設。"]', '["静境揖神凝，寒华射林缺。","清知思緒斷，爽覺心源徹。","高唱戛金奏，朗詠鏗玉節。","我思方泬寥，君词复淒切。","況闻风篁上，擺落殘凍雪。","寂爾万籟清，皎然諸靄滅。","西窗客無梦，南浦波應結。","河光正如劒，月魄方似玦。","短燼不禁挑，冷毫看欲折。","何夕重相期，濁醪還爲設。"]', '诗', 'shi', '', NULL, '寒夜聯句 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99c5d9d3-a209-4bea-8308-dc8ddb05bfd3', '開元寺樓看雨聯句', '开元寺楼看雨聯句', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["海上風雨來，掀轟雜飛電。","登樓一凭檻，滿眼蛟龍戰。","須臾造化慘，倏忽堪輿變。","萬戶響戈鋋，千家披組練。","羣飛拋輪石，雜下攻城箭。","點急似摧胸，行斜如中面。","細灑魂空冷，橫飄目能眩。","垂檐珂珮喧，㩧瓦珠璣濺。","無言九陔遠，瞬息馳應徧。","密處正垂絚，微時又懸綫。","寫作玉界破，吹爲羽林旋。","飜傷列缺勞，却怕豐隆倦。","遙瞻山露色，漸覺雲成片。","遠樹欲鳴蟬，深檐尚藏燕。","殘雷隱轔盡，反照依微見。","天光潔似磨，湖彩熟於練。","疎帆逗前渚，晚磬分涼殿。","接思強揮毫，窺詞幾焚研。","佶栗烏皮几，輕明白羽扇。","畢景好疎吟，餘涼可清宴。","君攜下高磴，僧引還深院。","駮蘚淨鋪筵，低松濕垂鬋。","齋明乍虛豁，林霽逾蔥蒨。","早晚重登臨，欲去多離戀。"]', '["海上风雨来，掀轟杂飞電。","登楼一凭檻，满眼蛟龙戰。","須臾造化慘，倏忽堪輿变。","万戶响戈鋋，千家披組練。","羣飞拋輪石，杂下攻城箭。","点急似摧胸，行斜如中面。","細灑魂空冷，橫飄目能眩。","垂檐珂珮喧，㩧瓦珠璣濺。","無言九陔远，瞬息驰應徧。","密处正垂絚，微时又懸綫。","寫作玉界破，吹爲羽林旋。","飜傷列缺勞，却怕豐隆倦。","遙瞻山露色，漸覺云成片。","远樹欲鳴蟬，深檐尚藏燕。","殘雷隐轔尽，反照依微见。","天光潔似磨，湖彩熟於練。","疎帆逗前渚，晚磬分涼殿。","接思強揮毫，窺词幾焚研。","佶栗烏皮几，轻明白羽扇。","畢景好疎吟，餘涼可清宴。","君携下高磴，僧引還深院。","駮蘚淨鋪筵，低松濕垂鬋。","斋明乍虛豁，林霽逾蔥蒨。","早晚重登臨，欲去多離戀。"]', '诗', 'shi', '', NULL, '開元寺樓看雨聯句 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b15f6a0-dbba-497f-85ae-e7707462b28c', '報恩寺南池聯句', '報恩寺南池聯句', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["古岸涵碧落，虛軒明素波。","坐來魚陣變，吟久菊□多。","秋草分杉露，危橋下竹坡。","遠峰青髻竝，□□□髯和。","趙論寒仍講，支硎僻亦過。","齋心曾養鶴，揮翰好邀鵝。","倚石收奇藥，臨溪藉淺莎。","桂花晴似拭，荷鏡曉如磨。","翠出牛頭聳，苔深馬跡跛。","繖欹從野醉，巾側任田歌。","跁跒松形矮，般跚檜樾矬。","香飛僧印火，泉急使鑣珂。","菱鈿真堪帖，蓴絲亦好拖。","幾時無一事，相伴著煙蘿。"]', '["古岸涵碧落，虛軒明素波。","坐来鱼陣变，吟久菊□多。","秋草分杉露，危橋下竹坡。","远峰青髻竝，□□□髯和。","趙論寒仍講，支硎僻亦過。","斋心曾養鹤，揮翰好邀鵝。","倚石收奇藥，臨溪藉淺莎。","桂花晴似拭，荷镜晓如磨。","翠出牛头聳，苔深马跡跛。","繖欹從野醉，巾側任田歌。","跁跒松形矮，般跚檜樾矬。","香飞僧印火，泉急使鑣珂。","菱鈿真堪帖，蓴絲亦好拖。","幾时無一事，相伴著煙蘿。"]', '诗', 'shi', '', NULL, '報恩寺南池聯句 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceb2ea65-f2ec-485f-9d4b-98de5ed0cd88', '天台禪院聯句', '天台禪院聯句', 'fbdf4406-fe4f-44d2-aa0e-175a4ee7d33b', '唐', '["偶到天台院，因逢物外僧。","忘機同一祖，出語離三乘。","樹老中庭寂，窗虛外境澄。","片時松影下，聯續百千燈。"]', '["偶到天台院，因逢物外僧。","忘機同一祖，出語離三乘。","樹老中庭寂，窗虛外境澄。","片时松影下，聯續百千灯。"]', '诗', 'shi', '', NULL, '天台禪院聯句 安守範 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d24662a-0f13-4c53-88e8-b469e73accfc', '講德聯句', '講德聯句', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["先王設位，以正邦國。","建立大官，封植有德。","二南敷化，四岳述職。","其言不朽，其儀不忒。","暨於嬴劉，乃創程式。","罷侯置守，剖竹分域。","赫矣皇唐，康哉立極。","精選藩翰，庸資正直。","爰命我公，東土作則。","克己恭儉，疲人休息。","濟濟閭閈，油油黍稷。","既富既教，足兵足食。","恤其凋瘵，剪其荆棘。","威懷逋叛，撲滅蝥賊。","疾惡如讐，聞善不惑。","哀矜鰥寡，旌禮儒墨。","乃修隄防，乃濬溝洫。","以利通商，以溉嘉穀。","徵賦以節，計功以時。","人胥懷惠，吏不能欺。","我政載孚，我邦載綏。","猛獸不暴，嘉魚維滋。","肅恭明神，齊沐不虧。","歲或驕陽，雨無愆期。","帝嘉有庸，寵命來斯。","紫紱載綏，金章陸離。","資忠履孝，閱禮敦詩。","明德惟馨，自天祐之。"]', '["先王設位，以正邦国。","建立大官，封植有德。","二南敷化，四岳述職。","其言不朽，其儀不忒。","暨於嬴劉，乃創程式。","罷侯置守，剖竹分域。","赫矣皇唐，康哉立極。","精選藩翰，庸資正直。","爰命我公，东土作則。","克己恭儉，疲人休息。","濟濟閭閈，油油黍稷。","既富既教，足兵足食。","恤其凋瘵，剪其荆棘。","威懷逋叛，撲滅蝥賊。","疾惡如讐，闻善不惑。","哀矜鰥寡，旌禮儒墨。","乃修隄防，乃濬溝洫。","以利通商，以溉嘉穀。","徵賦以節，計功以时。","人胥懷惠，吏不能欺。","我政載孚，我邦載綏。","猛獸不暴，嘉鱼維滋。","肅恭明神，齊沐不虧。","歲或驕陽，雨無愆期。","帝嘉有庸，寵命来斯。","紫紱載綏，金章陸離。","資忠履孝，閱禮敦诗。","明德惟馨，自天祐之。"]', '诗', 'shi', '', NULL, '講德聯句 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73e0f126-bbe7-478b-8b6f-a9df1d75f331', '講古文聯句', '講古文聯句', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["帝出於震，文明始敷。","山岳降氣，龜龍負圖。","爰有書契，乃立典謨。","先知孔聖，飛步天衢。","漢承秦弊，尊儒尚學。","百氏六經，九流七略。","屈宋接武，班馬繼作。","或頌燕然，或贊麟閣。","降及三祖，始變二雅。","仲宣閑和，公幹蕭灑。","士衡安仁，不史不野。","左張精奧，嵇阮高寡。","暨于江表，其文鬱興。","綺麗爭發，繁蕪則懲。","詞曄春華，思清冬冰。","景純跌宕，遊仙獨步。","青雲其情，白璧其句。","靈運山水，實多奇趣。","遠派孤峰，龍騰鳳翥。","陶令田園，匠意真直。","春柳寒松，不凋不飾。","江淹雜體，方見才力。","擬之信工，似而不逼。","鮑昭從軍，主意危苦。","氣勝其詞，雅愧於古。","隱侯似病，創制規矩。","時見琳琅，惜哉榛楛。","謝朓秀發，詞理翩翩。","孤標爽邁，深造精研。","惠休翰林，別白離堅。","有會必愜，無慚曩賢。","吳均頗勁，失於典裁。","竟乏波瀾，徒工邊塞。","彼柳吳興，高視時輩。","汀洲一篇，風流寡對。","何遜清切，所得必新。","緣情既密，象物又真。","江總徵正，未越常倫。","時合風興，或無淄磷。","二杜繁俗，三劉瑣碎。","陳徐之流，陰張之輩。","伊數公者，閫域之外。","吁此以還，有固斯鄶。"]', '["帝出於震，文明始敷。","山岳降氣，龟龙負圖。","爰有书契，乃立典謨。","先知孔聖，飞步天衢。","漢承秦弊，尊儒尚学。","百氏六經，九流七略。","屈宋接武，班马繼作。","或頌燕然，或贊麟閣。","降及三祖，始变二雅。","仲宣闲和，公幹蕭灑。","士衡安仁，不史不野。","左張精奧，嵇阮高寡。","暨于江表，其文鬱兴。","綺丽爭發，繁蕪則懲。","词曄春华，思清冬冰。","景純跌宕，游仙独步。","青云其情，白璧其句。","靈運山水，實多奇趣。","远派孤峰，龙腾鳳翥。","陶令田园，匠意真直。","春柳寒松，不凋不飾。","江淹杂體，方见才力。","擬之信工，似而不逼。","鲍昭從軍，主意危苦。","氣勝其词，雅愧於古。","隐侯似病，創制規矩。","时见琳琅，惜哉榛楛。","謝朓秀發，词理翩翩。","孤標爽邁，深造精研。","惠休翰林，別白離堅。","有會必愜，無慚曩賢。","吳均頗勁，失於典裁。","竟乏波瀾，徒工邊塞。","彼柳吳兴，高視时輩。","汀洲一篇，风流寡对。","何遜清切，所得必新。","緣情既密，象物又真。","江總徵正，未越常倫。","时合风兴，或無淄磷。","二杜繁俗，三劉瑣碎。","陳徐之流，陰張之輩。","伊數公者，閫域之外。","吁此以還，有固斯鄶。"]', '诗', 'shi', '', NULL, '講古文聯句 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29948fcb-610b-4702-96d0-183b8bf69375', '項王古祠聯句', '項王古祠聯句', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["遺廟風塵積，荒途歲月侵。","英靈今寂寞，容衛尚森沈。","霸楚志何在，平秦功亦深。","諸侯歸復背，青史古將今。","星聚分已定，天亡力豈任。","采蘩如可薦，舉酒瀝空林。"]', '["遺廟风塵積，荒途歲月侵。","英靈今寂寞，容衛尚森沈。","霸楚志何在，平秦功亦深。","諸侯归复背，青史古將今。","星聚分已定，天亡力豈任。","采蘩如可薦，舉酒瀝空林。"]', '诗', 'shi', '', NULL, '項王古祠聯句 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaa6498e-9cec-4447-afb2-c66bec5eb14a', '還丹可成詩聯句', '還丹可成诗聯句', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["羽化自仙骨，延年資養生。","金經啓靈秘，玉液流至精。","八石思共煉，九丹知可成。","吾心苟無妄，神理期合幷。","封竈用六一，置門考休京。","浮光含日彩，圓質煥雲英。","持此保壽命，服之頤性情。","跂予望仙侶，高詠昇天行。","鶴駕方可致，霓裳定將迎。","不因五色藥，安著七真名。","揮妙在微密，全功知感誠。","與君棄城市，攜手遊蓬瀛。"]', '["羽化自仙骨，延年資養生。","金經啓靈秘，玉液流至精。","八石思共煉，九丹知可成。","吾心苟無妄，神理期合幷。","封竈用六一，置门考休京。","浮光含日彩，圓質煥云英。","持此保壽命，服之頤性情。","跂予望仙侶，高詠昇天行。","鹤駕方可致，霓裳定將迎。","不因五色藥，安著七真名。","揮妙在微密，全功知感誠。","與君棄城市，携手游蓬瀛。"]', '诗', 'shi', '', NULL, '還丹可成詩聯句 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ca14765-40a4-4d02-8a76-ebdbe9d4be0e', '建安寺西院喜王郎中遘恩命初至聯句', '建安寺西院喜王郎中遘恩命初至聯句', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["跡就空門退，官從畫省遷。","住持良有願，朝謁宂無緣。","身淨金繩內，心馳玉扆前。","榮添一兩日，恩降九霄年。","慕法能輕冕，追非欲佩弦。","棲閑那可久，鴛鷺待行聯。"]', '["跡就空门退，官從畫省遷。","住持良有願，朝謁宂無緣。","身淨金繩內，心驰玉扆前。","榮添一兩日，恩降九霄年。","慕法能轻冕，追非欲佩弦。","棲闲那可久，鴛鷺待行聯。"]', '诗', 'shi', '', NULL, '建安寺西院喜王郎中遘恩命初至聯句 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f407363-934c-4a6c-9976-49b1d57b33cb', '建安寺夜會對雨懷皇甫侍御曾聯句', '建安寺夜會对雨懷皇甫侍御曾聯句', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["相思非是遠，風雨遣情多。","願欲披雲見，難堪候曉過。","夜長同歲月，地近極山河。","戒相初傳授，文章舊切磋。","時稱洛下詠，人許郢中歌。","惆悵徒延首，其如一水何。"]', '["相思非是远，风雨遣情多。","願欲披云见，难堪候晓過。","夜长同歲月，地近極山河。","戒相初傳授，文章旧切磋。","时稱洛下詠，人許郢中歌。","惆悵徒延首，其如一水何。"]', '诗', 'shi', '', NULL, '建安寺夜會對雨懷皇甫侍御曾聯句 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c360fd75-008f-4049-a291-ba3fbaa680e2', '泛長城東溪暝宿崇光寺寄處士陸羽聯句', '泛长城东溪暝宿崇光寺寄处士陸羽聯句', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["箬水青似箬，玉山碧於玉。","逼霄沓萬狀，截地分千曲。","萍解深可窺，林豁遙在矚。","已高物外賞，稍滌區中欲。","野鶴翔又飛，世人羈且跼。","沈吟跡所悞，放浪心自足。","緬懷虛舟客，願寄生芻束。","說詩整頹波，立義激浮俗。","荆吳備登歷，風土隨編錄。","恨與清景別，擬教長路促。","溪鳥語鸝嘍，寺花翻躑躅。","印圍水壇淨，香護蓮衣觸。","捧經啓紗燈，收袵禮金粟。","安得扣關子，玄言對吾屬。"]', '["箬水青似箬，玉山碧於玉。","逼霄沓万狀，截地分千曲。","萍解深可窺，林豁遙在矚。","已高物外賞，稍滌區中欲。","野鹤翔又飞，世人羈且跼。","沈吟跡所悞，放浪心自足。","緬懷虛舟客，願寄生芻束。","说诗整頹波，立義激浮俗。","荆吳備登歷，风土隨編錄。","恨與清景別，擬教长路促。","溪鸟語鸝嘍，寺花翻躑躅。","印圍水壇淨，香護蓮衣觸。","捧經啓紗灯，收袵禮金粟。","安得扣关子，玄言对吾屬。"]', '诗', 'shi', '', NULL, '泛長城東溪暝宿崇光寺寄處士陸羽聯句 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7692dc34-e8a1-4f8a-9d6e-d81a9078648b', '與崔子向泛舟自招橘經箬里宿天居寺憶李侍御㟧渚山春遊後期不及聯一十六韻以寄之', '與崔子向泛舟自招橘經箬里宿天居寺憶李侍御㟧渚山春游後期不及聯一十六韻以寄之', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["晴日春態深，寄遊恣所適。","寧妨花木亂，轉學心耳寂。","取性憐鶴高，謀閑任山僻。","倚舷息空曲，捨屨行淺磧。","渚箬入里逢，野梅到村摘。","碑殘飛雉嶺，井翳潛龍宅。","壞寺鄰壽陵，古壇留劫石。","穿階筍節露，拂瓦松梢碧。","天界細雲還，墙陰雜英積。","懸燈寄前焰，遙月昇圓魄。","何意清夜期，坐爲高峰隔。","茗園可交袂，藤澗好停錫。","微雨聽濕巾，迸流從點席。","戲猨隔枝透，驚鹿逢人躑。","覩物賞已奇，感時思彌極。","芳菲如馳箭，望望共君惜。"]', '["晴日春態深，寄游恣所適。","寧妨花木亂，轉学心耳寂。","取性怜鹤高，謀闲任山僻。","倚舷息空曲，捨屨行淺磧。","渚箬入里逢，野梅到村摘。","碑殘飞雉嶺，井翳潛龙宅。","壞寺鄰壽陵，古壇留劫石。","穿階筍節露，拂瓦松梢碧。","天界細云還，墙陰杂英積。","懸灯寄前焰，遙月昇圓魄。","何意清夜期，坐爲高峰隔。","茗园可交袂，藤澗好停錫。","微雨听濕巾，迸流從点席。","戲猨隔枝透，驚鹿逢人躑。","覩物賞已奇，感时思彌極。","芳菲如驰箭，望望共君惜。"]', '诗', 'shi', '', NULL, '與崔子向泛舟自招橘經箬里宿天居寺憶李侍御㟧渚山春遊後期不及聯一十六韻以寄之 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6868844-ddae-466b-8960-c0449d267c82', '渚山春暮會顧丞茗舍聯句效小庾體', '渚山春暮會顧丞茗舍聯句效小庾體', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["誰是惜暮人，相攜送春日。","因君過茗舍，留客開蘭室。","濕苔滑行屐，柔草低藉瑟。","鵲喜語成雙，花狂落非一。","煙濃山焙動，泉破水舂疾。","莫抝挂瓢枝，會移閬書帙。","頗容樵與隱，豈聞禪兼律。","欄竹不求疎，網藤從更密。","池添逸少墨，園雜莊生漆。","景晏枕猶欹，酒醒頭懶櫛。","雲教淡機慮，地可遺名實。","應待御荈青，幽期踏芳出。"]', '["誰是惜暮人，相携送春日。","因君過茗舍，留客开蘭室。","濕苔滑行屐，柔草低藉瑟。","鵲喜語成雙，花狂落非一。","煙濃山焙动，泉破水舂疾。","莫抝挂瓢枝，會移閬书帙。","頗容樵與隐，豈闻禪兼律。","欄竹不求疎，網藤從更密。","池添逸少墨，园杂莊生漆。","景晏枕猶欹，酒醒头懶櫛。","云教淡機慮，地可遺名實。","應待御荈青，幽期踏芳出。"]', '诗', 'shi', '', NULL, '渚山春暮會顧丞茗舍聯句效小庾體 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c3b38ad-a51b-4643-87f9-0007794803f8', '與李司直令從荻塘聯句', '與李司直令從荻塘聯句', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["畫舸悠悠荻塘路，真僧與我相隨去。","寒花似菊不知名，霜葉如楓是何樹。","倦客經秋夜共歸，情多語盡明相顧。","遙城候騎來仍少，傍嶺哀猨發無數。","心閑清淨得禪寂，興逸縱橫問章句。","蟲聲切切草間悲，螢影紛紛月前度。","撩亂雲峰好賦詩，嬋娟水月堪爲喻。","與君出處本不同，從此還依舊山住。"]', '["畫舸悠悠荻塘路，真僧與我相隨去。","寒花似菊不知名，霜葉如楓是何樹。","倦客經秋夜共归，情多語尽明相顧。","遙城候騎来仍少，傍嶺哀猨發無數。","心闲清淨得禪寂，兴逸縱橫问章句。","蟲声切切草间悲，螢影紛紛月前度。","撩亂云峰好賦诗，嬋娟水月堪爲喻。","與君出处本不同，從此還依旧山住。"]', '诗', 'shi', '', NULL, '與李司直令從荻塘聯句 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70c2f932-1002-4d29-8d2a-a50a7b333090', '遠意聯句', '远意聯句', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["家在炎州往朔方，豈知于闐望瀟湘。","曾經隴底復遼陽，更憶東去採扶桑。","楂客三千路未央，燭龍之地日無光。","將遊莽蒼窮大荒，車轍馬足逐周王。"]', '["家在炎州往朔方，豈知于闐望瀟湘。","曾經隴底复遼陽，更憶东去採扶桑。","楂客三千路未央，燭龙之地日無光。","將游莽蒼窮大荒，车轍马足逐周王。"]', '诗', 'shi', '', NULL, '遠意聯句 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e468df90-3866-41f4-a47a-be0df85ae38f', '暗思聯句', '暗思聯句', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["斜風飄雨三十夜，隣女餘光不相借。","跡滅塵生古人畫，洞房重扉無隟罅。"]', '["斜风飄雨三十夜，隣女餘光不相借。","跡滅塵生古人畫，洞房重扉無隟罅。"]', '诗', 'shi', '', NULL, '暗思聯句 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('602ea61b-bb96-4812-a74c-7cd2e37ce998', '樂意聯句一首', '乐意聯句一首', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["良朋益友自遠來，萬里鄉書對酒開。","子孫蔓衍負奇才，承顏弄鳥詠南陔。","鼓腹擊壤歌康哉！。"]', '["良朋益友自远来，万里乡书对酒开。","子孫蔓衍負奇才，承顏弄鸟詠南陔。","鼓腹擊壤歌康哉！。"]', '诗', 'shi', '', NULL, '樂意聯句一首 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('376cf4d7-6267-4c32-a985-81a3ab4e8c22', '恨意聯句', '恨意聯句', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["同心同縣不相見，獨采蘼蕪詠團扇。","莫聽東隣擣霜練，遠憶征人淚如霰。","長信空階荒草遍，明妃初別昭陽殿。"]', '["同心同縣不相见，独采蘼蕪詠團扇。","莫听东隣擣霜練，远憶征人泪如霰。","长信空階荒草遍，明妃初別昭陽殿。"]', '诗', 'shi', '', NULL, '恨意聯句 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee049069-51b7-4a78-90f6-ee9e92fead64', '秋日盧郎中使君幼平泛舟聯句一首', '秋日盧郎中使君幼平泛舟聯句一首', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["共載清秋客船，同瞻皂蓋朝天。","悔使比來相得，如今欲別潸然。","漸驚徒馭分散，愁望雲山接連。","魏闕馳心日日，吳城揮手年年。","送遠已傷飛雁，裁詩更切嘶蟬。","空懷鄠杜心醉，永望門欄脰捐。","別思無窮無限，還如秋水秋煙。"]', '["共載清秋客船，同瞻皂蓋朝天。","悔使比来相得，如今欲別潸然。","漸驚徒馭分散，愁望云山接連。","魏闕驰心日日，吳城揮手年年。","送远已傷飞雁，裁诗更切嘶蟬。","空懷鄠杜心醉，永望门欄脰捐。","別思無窮無限，還如秋水秋煙。"]', '诗', 'shi', '', NULL, '秋日盧郎中使君幼平泛舟聯句一首 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea3d7bfe-2252-42ed-8efb-fb5a5ad07db5', '重聯句一首', '重聯句一首', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["相將惜別且遲遲，未到新豐欲醉時。","去郡獨攜程氏酒，入朝可忘習家池。","仍憐故吏依依戀，自有清光處處隨。","晚景南徐何處宿，秋風北固不堪辭。","吳中詩酒饒佳興，秦地關山引夢思。","對酒已傷嘶馬去，銜恩只待掃門期。"]', '["相將惜別且遲遲，未到新豐欲醉时。","去郡独携程氏酒，入朝可忘習家池。","仍怜故吏依依戀，自有清光处处隨。","晚景南徐何处宿，秋风北固不堪辞。","吳中诗酒饒佳兴，秦地关山引梦思。","对酒已傷嘶马去，銜恩只待掃门期。"]', '诗', 'shi', '', NULL, '重聯句一首 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1767154-bf52-46d9-b006-a675f3f16389', '與潘述集湯衡宅懷李司直縱聯句', '與潘述集湯衡宅懷李司直縱聯句', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["幽獨何以慰，友人顧茅茨。","已忘歲月念，載說清閑時。","旭日舒朱槿，柔風引綠葹。","迢迢青溪路，耿耿芳樹枝。","執袵空躑躅，來城自逶迤。","相思寄採掇，景晏獨驅馳。"]', '["幽独何以慰，友人顧茅茨。","已忘歲月念，載说清闲时。","旭日舒朱槿，柔风引綠葹。","迢迢青溪路，耿耿芳樹枝。","執袵空躑躅，来城自逶迤。","相思寄採掇，景晏独驱驰。"]', '诗', 'shi', '', NULL, '與潘述集湯衡宅懷李司直縱聯句 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecce1da3-7017-44f4-aa40-33d45e2bdad5', '安吉崔明甫山院聯句一首', '安吉崔明甫山院聯句一首', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["人不擾，政已和。","世慮寡，山情多。","禪客至，墨卿過。","興既洽，情如何。"]', '["人不擾，政已和。","世慮寡，山情多。","禪客至，墨卿過。","兴既洽，情如何。"]', '诗', 'shi', '', NULL, '安吉崔明甫山院聯句一首 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af646dbf-0f1e-4333-aea2-fd40e7ac6e3a', '重聯句一首', '重聯句一首', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["肅肅清院，翛翛碧鮮。","已見心遠，何關地偏。","自公退食，升堂草玄。","紛紛已隔，雲心澹然。"]', '["肅肅清院，翛翛碧鲜。","已见心远，何关地偏。","自公退食，升堂草玄。","紛紛已隔，云心澹然。"]', '诗', 'shi', '', NULL, '重聯句一首 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea3b915e-8ed6-44f2-ab79-68f74f3c94d4', '重聯句一首', '重聯句一首', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["瀑溜聞窗外，晴風逼座間。","挂冠徒有意，芳桂杳難攀。"]', '["瀑溜闻窗外，晴风逼座间。","挂冠徒有意，芳桂杳难攀。"]', '诗', 'shi', '', NULL, '重聯句一首 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8065e9aa-32cd-4342-b1f0-81973c4af66f', '重聯句一首', '重聯句一首', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["清高素非宦侶，疎散從來道流。","今日還輕墨綬，知君意在滄洲。","浮雲任從飄蕩，寄隱也信沈浮。","不似漳南地僻，道安爲我淹留。"]', '["清高素非宦侶，疎散從来道流。","今日還轻墨綬，知君意在滄洲。","浮云任從飄蕩，寄隐也信沈浮。","不似漳南地僻，道安爲我淹留。"]', '诗', 'shi', '', NULL, '重聯句一首 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3a865b0-5636-43b4-b4c6-fe45689317d3', '重聯句一首', '重聯句一首', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["劉令興多常步履，柴桑事少但援琴。","閑招法侶從山寺，每掇幽芳傍竹林。","卷簾只愛荆峰色，入坐偏宜郢客吟。","誰許近來輕印綬，因君昨日悟禪心。"]', '["劉令兴多常步履，柴桑事少但援琴。","闲招法侶從山寺，每掇幽芳傍竹林。","卷簾只愛荆峰色，入坐偏宜郢客吟。","誰許近来轻印綬，因君昨日悟禪心。"]', '诗', 'shi', '', NULL, '重聯句一首 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f415cc5-04ce-4d46-b74f-e956ea07b324', '道觀中和潘丞觀青溪圖聯句', '道观中和潘丞观青溪圖聯句', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["畫得青溪樣，宜於紫府觀。","日明煙靄薄，風落水容寬。","畫野高低接，商工井邑攢。","疏川因稼穡，出使問艱難。"]', '["畫得青溪樣，宜於紫府观。","日明煙靄薄，风落水容寬。","畫野高低接，商工井邑攢。","疏川因稼穡，出使问艱难。"]', '诗', 'shi', '', NULL, '道觀中和潘丞觀青溪圖聯句 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af83c5e6-a0af-469a-adbf-74198bc442b7', '春日對雨聯句一首', '春日对雨聯句一首', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["春煙帶微雨，漠漠連城邑。","桐葉生微陰，桃花更宜濕。","蕭條暗楊柳，散漫下原隰。","歸路不我從，遙心空佇立。","林低山影近，岸轉水流急。","芳草自堪遊，白雲如可揖。","尋山禪客意，苦雨陶公什。","遊衍情未終，歸飛暮相及。","峰高日色轉，潭淨天光入。","却欲學神仙，空思謝朋執。","爲道貴逍遙，趍時多苦集。","瓊英若可飱，青紫徒勞拾。"]', '["春煙带微雨，漠漠連城邑。","桐葉生微陰，桃花更宜濕。","蕭條暗楊柳，散漫下原隰。","归路不我從，遙心空佇立。","林低山影近，岸轉水流急。","芳草自堪游，白云如可揖。","尋山禪客意，苦雨陶公什。","游衍情未終，归飞暮相及。","峰高日色轉，潭淨天光入。","却欲学神仙，空思謝朋執。","爲道貴逍遙，趍时多苦集。","瓊英若可飱，青紫徒勞拾。"]', '诗', 'shi', '', NULL, '春日對雨聯句一首 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8caf899a-3988-4d77-8845-6f3d90300cf5', '春日會韓武康章後亭聯句', '春日會韓武康章後亭聯句', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["後園堪寄賞，日日對春風。","客位繁陰下，公牆細柳中。","坐看青嶂遠，心與白雲同。","林暗花煙入，池深遠水通。","井桃新長蘂，欄藥未成叢。","松竹宜禪客，山泉入謝公。","砌香翻芍藥，簷靜倚梧桐。","外慮宜簾卷，忘情與道空。","楚僧招惠遠，蜀客挹楊雄。","便寄柴桑隱，何勞訪剡東。"]', '["後园堪寄賞，日日对春风。","客位繁陰下，公牆細柳中。","坐看青嶂远，心與白云同。","林暗花煙入，池深远水通。","井桃新长蘂，欄藥未成叢。","松竹宜禪客，山泉入謝公。","砌香翻芍藥，簷静倚梧桐。","外慮宜簾卷，忘情與道空。","楚僧招惠远，蜀客挹楊雄。","便寄柴桑隐，何勞訪剡东。"]', '诗', 'shi', '', NULL, '春日會韓武康章後亭聯句 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c72857a4-1806-4af6-806d-de660cc4cda1', '康錄事宅送僧聯句', '康錄事宅送僧聯句', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["蓮衣宜著雨，竹錫好隨雲。","見鶴還應養，逢鷗自作羣。"]', '["蓮衣宜著雨，竹錫好隨云。","见鹤還應養，逢鷗自作羣。"]', '诗', 'shi', '', NULL, '康錄事宅送僧聯句 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('658b06d0-8baa-425c-9fba-edd48eadf149', '與邢端公李台題庭石聯句', '與邢端公李台題庭石聯句', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["共題詩句遍，爭坐蘚文稀。"]', '["共題诗句遍，爭坐蘚文稀。"]', '诗', 'shi', '', NULL, '與邢端公李台題庭石聯句 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('041b8c0f-c5e7-48ad-bc12-dc3dd81b74a0', '冬日建安寺西院喜晝公自吳興至聯句一首', '冬日建安寺西院喜晝公自吳兴至聯句一首', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["宗系傳康樂，精修學遠公。","相尋當暮歲，行李犯寒風。","累積浮生裏，機慙半偈中。","傳家知業墜，繼祖忝聲同。","雲與輕帆至，山將本寺空。","向來忘起滅，留我宿花宮。"]', '["宗系傳康乐，精修学远公。","相尋當暮歲，行李犯寒风。","累積浮生裏，機慙半偈中。","傳家知業墜，繼祖忝声同。","云與轻帆至，山將本寺空。","向来忘起滅，留我宿花宮。"]', '诗', 'shi', '', NULL, '冬日建安寺西院喜晝公自吳興至聯句一首 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('facca95a-e528-4bd4-9a92-f227f68202aa', '秋日潘述自長城至霅上與晝公湯評事遊集累日時司直李公瑕往蘇州有阻良會因與二公聯句以寄之', '秋日潘述自长城至霅上與晝公湯評事游集累日时司直李公瑕往蘇州有阻良會因與二公聯句以寄之', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["離念非前期，秋風忽已至。","芸黃衆芳晚，搖蕩居人思。","白霜淒以積，高梧颯而墜。","悠然越山川，復此恨離異。","時景易遷謝，懽□難兼遂。","惜分緩迴舟，懷遙企歸駟。","休澣情自高，來思日云未。"]', '["離念非前期，秋风忽已至。","芸黄衆芳晚，搖蕩居人思。","白霜淒以積，高梧颯而墜。","悠然越山川，复此恨離異。","时景易遷謝，懽□难兼遂。","惜分緩迴舟，懷遙企归駟。","休澣情自高，来思日云未。"]', '诗', 'shi', '', NULL, '秋日潘述自長城至霅上與晝公湯評事遊集累日時司直李公瑕往蘇州有阻良會因與二公聯句以寄之 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5a7c702-6006-4e89-aa92-08fc28a65494', '喜晝公尋山迴相遇聯句一首', '喜晝公尋山迴相遇聯句一首', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["幾年無此會，今日喜相從。","後夏仍多病，前書達幾封。","水華迎暮雨，松吹引疎鐘。","出谷隨初月，尋僧說五峰。"]', '["幾年無此會，今日喜相從。","後夏仍多病，前书達幾封。","水华迎暮雨，松吹引疎鐘。","出谷隨初月，尋僧说五峰。"]', '诗', 'shi', '', NULL, '喜晝公尋山迴相遇聯句一首 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b1edf3b-2939-40c4-be65-259d560bb55c', '送晝公聯句', '送晝公聯句', '897cc95e-097e-4903-971f-6e6aa0f087b8', '唐', '["相逢情不厭，惜別意難爲。","吾道應無住，前期未可知。","輕霜凋古木，寒水縮荒陂。","賓雁依沙嶼，浮雲慘路岐。","林疎看野迥，岸轉覺山移。","寄賞驚搖落，歸心歎別離。","草堂思偃蹇，麈尾去相隨。","勿謂光陰遠，禪房會一窺。"]', '["相逢情不厭，惜別意难爲。","吾道應無住，前期未可知。","轻霜凋古木，寒水縮荒陂。","賓雁依沙嶼，浮云慘路岐。","林疎看野迥，岸轉覺山移。","寄賞驚搖落，归心歎別離。","草堂思偃蹇，麈尾去相隨。","勿謂光陰远，禪房會一窺。"]', '诗', 'shi', '', NULL, '送晝公聯句 清晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18fc8b41-2a36-47ce-8e22-09db3143aa9a', '與羅隱之聯句', '與羅隐之聯句', 'efbdd3ef-9413-4e72-9199-97d39e2b7571', '唐', '["一壺天上有名物，兩個世間無事人。","醉却隱之雲叟外，不知何處是天真。"]', '["一壺天上有名物，兩個世间無事人。","醉却隐之云叟外，不知何处是天真。"]', '诗', 'shi', '', NULL, '與羅隱之聯句 鄭遨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adf731c6-b6ae-4054-9e51-bd525d18e7e1', '句', '句', 'd0ea2bce-d3cf-4105-9cd5-bbc5754fafd7', '唐', '["所願暫知居者樂，無使時稱主者勞。"]', '["所願暫知居者乐，無使时稱主者勞。"]', '诗', 'shi', '', NULL, '句 李日知 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('932be744-2595-419c-bac4-ad3f2c3cd7ff', '句', '句', '75106374-0638-472b-92c3-e77ee2c46909', '唐', '["令乘驄馬去，丞脫繡衣來。"]', '["令乘驄马去，丞脫繡衣来。"]', '诗', 'shi', '', NULL, '句 趙仁奬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aa9a422-5524-45e4-ad05-b3ee7435716d', '句', '句', '655c593a-8af9-42d0-9d12-0540a585d38e', '唐', '["魂逐東流水，墳依獨坐山。"]', '["魂逐东流水，墳依独坐山。"]', '诗', 'shi', '', NULL, '句 郭廷謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcee7510-9f0d-429a-b08e-cf9c1d65dcf1', '句', '句', 'ff909308-b9d9-4f6d-a298-ec131edde79c', '唐', '["三代掌綸誥，一身能唱歌。"]', '["三代掌綸誥，一身能唱歌。"]', '诗', 'shi', '', NULL, '句 韋青 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c945614-ae46-4730-a644-4a036b17ab68', '句', '句', '3c0b4ab5-eaaa-4431-91fb-0c8a9be9c06a', '唐', '["明月飛出海，黃河流上天。","芙蓉初出水，桃李忽無言。","夜夜月爲青塚鏡，年年雪作黑山花。"]', '["明月飞出海，黄河流上天。","芙蓉初出水，桃李忽無言。","夜夜月爲青塚镜，年年雪作黑山花。"]', '诗', 'shi', '', NULL, '句 尉遲匡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de3d4d6c-ca99-4469-a833-1af62061a448', '句', '句', '9618643d-98d3-4659-9f29-70e712de76b6', '唐', '["鴈影數行秋半逢，漁歌一聲夜深發。"]', '["鴈影數行秋半逢，漁歌一声夜深發。"]', '诗', 'shi', '', NULL, '句 何涓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d692c8e-e26b-4bdc-8206-88b889acb982', '句', '句', '7b66aab3-4c48-4b2c-a914-a6c0746f05a3', '唐', '["忽覩邢武辭，泠其金石備。"]', '["忽覩邢武辞，泠其金石備。"]', '诗', 'shi', '', NULL, '句 杜偉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54c2f109-4b42-4be9-a9f7-cdff68442e48', '句', '句', 'ece3e464-9522-4c79-a5c9-eee62b0120d7', '唐', '["霜添柏樹冷，氣拂桂林寒。"]', '["霜添柏樹冷，氣拂桂林寒。"]', '诗', 'shi', '', NULL, '句 申堂構 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9ae3d56-6a25-4754-8f09-2ce0314cb641', '句', '句', '685c4780-b65e-408e-9802-a98f18356f4b', '唐', '["八十年前棠樹陰，竟陵太守公先人。"]', '["八十年前棠樹陰，竟陵太守公先人。"]', '诗', 'shi', '', NULL, '句 周愿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eef11dbe-4742-4b94-a175-f60d44274321', '句', '句', 'ba05a279-7054-4025-9468-7261d49e8737', '唐', '["陰天聞斷雁，夜浦送歸人。"]', '["陰天闻斷雁，夜浦送归人。"]', '诗', 'shi', '', NULL, '句 苐五琦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79903e5c-9cb4-4bfd-945e-34d553a76d2d', '句', '句', '2f115222-769b-4988-b0ee-54b1719925c5', '唐', '["誰言百人會，兄弟也霑陪。"]', '["誰言百人會，兄弟也霑陪。"]', '诗', 'shi', '', NULL, '句 顏允南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('600de7a4-83e5-42d1-bb0e-856d5250d0ae', '句', '句', 'aa0e3039-9fdd-4b4a-8e3d-137a52147387', '唐', '["刻舟尋已化，彈鋏未酬恩。"]', '["刻舟尋已化，彈鋏未酬恩。"]', '诗', 'shi', '', NULL, '句 季廣琛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f57093e-9a9f-4ffe-a9d0-2c6d69508236', '句', '句', '753c1e39-e943-4c54-affa-7f52cc92e199', '唐', '["夢裏換春秋。"]', '["梦裏換春秋。"]', '诗', 'shi', '', NULL, '句 陳蛻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4953b77-7188-47b8-b910-86e1b10c5fe4', '句', '句', '56304797-a576-4271-8c86-6d1de51ec007', '唐', '["莫言閑話是閑話，往往事從閑話來。","何必剃頭爲弟子，無家便是出家人。"]', '["莫言闲話是闲話，往往事從闲話来。","何必剃头爲弟子，無家便是出家人。"]', '诗', 'shi', '', NULL, '句 衛準 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea9a667e-eb83-443b-a76f-64b31c0369b3', '句', '句', '158dd7d1-0129-4321-b121-a834c2fd0414', '唐', '["常願追禪理，安能挹化源。"]', '["常願追禪理，安能挹化源。"]', '诗', 'shi', '', NULL, '句 杜鴻漸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80cffc2d-97ff-44a6-a74a-4cb6d8422e47', '句', '句', 'dc7a8edf-c47d-44ba-97df-ab0a3137a4f5', '唐', '["因緣三紀異，契分四般同。"]', '["因緣三紀異，契分四般同。"]', '诗', 'shi', '', NULL, '句 李摯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d75317f-aed9-4001-a469-f3dac90452ea', '句', '句', '3991544b-927c-44b1-b336-bf24db2b448e', '唐', '["在室愧屋漏。"]', '["在室愧屋漏。"]', '诗', 'shi', '', NULL, '句 韋綬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50cf7eb6-aa2e-4b50-9807-225bd355403a', '句', '句', 'b71784e8-b9a2-4ebd-8af2-bac5cd929191', '唐', '["桃花浪裏成龍去，竹葉山頭退鷁飛。"]', '["桃花浪裏成龙去，竹葉山头退鷁飞。"]', '诗', 'shi', '', NULL, '句 馮戡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2a48281-e7af-483f-bdb9-d1c5d3bd7216', '句', '句', '0e66a73c-b679-4699-b7c7-950e142f490a', '唐', '["庾嶺東邊吏隱州，溪山竹樹亦清幽。"]', '["庾嶺东邊吏隐州，溪山竹樹亦清幽。"]', '诗', 'shi', '', NULL, '句 韓泰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7588690-d696-4446-9170-90d86fc33e1e', '句', '句', 'c70cbfa2-9c1f-4053-be59-b1b8bce01ab4', '唐', '["地靈無俗草，岩靜有僊禽。"]', '["地靈無俗草，岩静有僊禽。"]', '诗', 'shi', '', NULL, '句 盧幷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d929bb8-5375-4092-82ca-3b991b924b40', '句', '句', 'db013af4-821d-4c5c-84c5-a71a18c3b5ac', '唐', '["白鳥遠行樹，玉虹孤飲潭。","四五片霞生絕壁，兩三行雁過疎松。","拋芥子降顛狒狒，折楊枝灑醉猩猩。"]', '["白鸟远行樹，玉虹孤饮潭。","四五片霞生絕壁，兩三行雁過疎松。","拋芥子降顛狒狒，折楊枝灑醉猩猩。"]', '诗', 'shi', '', NULL, '句 繆島雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('525bef20-9f2c-410e-a830-de2c3de69c9a', '句', '句', '2e48276c-21b1-40a0-823a-4d74c9761e93', '唐', '["山近衡陽雖少雁，水連巴蜀豈無魚。"]', '["山近衡陽雖少雁，水連巴蜀豈無鱼。"]', '诗', 'shi', '', NULL, '句 劉敬之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40a1c0f0-d42e-454f-bae0-fb49d95a1f7f', '句', '句', 'b5d2ead8-ce44-47da-a2af-94bc6846601c', '唐', '["水聲長在耳，山色不離門。","掃地樹留影，拂牀琴有聲。","落日長安道，秋槐滿地花。"]', '["水声长在耳，山色不離门。","掃地樹留影，拂牀琴有声。","落日长安道，秋槐满地花。"]', '诗', 'shi', '', NULL, '句 李濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('225d6a7f-0f84-413d-b995-00de78ba8a95', '句', '句', 'ae215308-6b3d-4549-9949-abeaf1864ae7', '唐', '["中丞爲國拔賢才，寒俊欣逢藻鑑開。"]', '["中丞爲国拔賢才，寒俊欣逢藻鑑开。"]', '诗', 'shi', '', NULL, '句 高元裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6ecd169-a3f3-43e0-8c2d-241cce6eb90c', '句', '句', '7c9adf73-8dc8-4377-8df7-6f870c2575e7', '唐', '["莫將韋監同殷監，錯認容身是保身。"]', '["莫將韋監同殷監，錯認容身是保身。"]', '诗', 'shi', '', NULL, '句 韋澳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11a3e008-5de0-4d22-9ab7-e374a2c0fb88', '句', '句', '9e75ad4d-1c78-4d92-89f2-4fdcc5609648', '唐', '["珠箔卷繁星，金樽瀉月明。"]', '["珠箔卷繁星，金樽瀉月明。"]', '诗', 'shi', '', NULL, '句 王龜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('663f1b31-8deb-474c-a6d7-de11891c7a33', '句', '句', '33656789-a1bf-4446-a697-ba75207100d4', '唐', '["身死爲修劉稹表，名高因讓陸洿書。"]', '["身死爲修劉稹表，名高因讓陸洿书。"]', '诗', 'shi', '', NULL, '句 李郁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80ae525d-d45c-46e9-af78-ed9188a82a87', '句', '句', '57f5c661-8ebb-4d9a-b0da-d25bce583447', '唐', '["塵飛遺恨盡，花落古宮平。","紅粉笙歌人代遠，月明陵樹水東流。"]', '["塵飞遺恨尽，花落古宮平。","紅粉笙歌人代远，月明陵樹水东流。"]', '诗', 'shi', '', NULL, '句 詹雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63e55677-d523-43ec-aa1f-a495d1e565fd', '句', '句', 'db1d31a9-5c12-44f7-a7fc-5ef1a6bd4dd6', '唐', '["露團沙鶴起，人臥釣船流。"]', '["露團沙鹤起，人臥釣船流。"]', '诗', 'shi', '', NULL, '句 任濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9169b3c2-d0db-432e-902e-3db6500ac147', '句', '句', '9329e544-9901-4f18-bcff-6178d0022586', '唐', '["秪向國門安四海，不離鄉井拜三公。"]', '["秪向国门安四海，不離乡井拜三公。"]', '诗', 'shi', '', NULL, '句 劇燕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc8de1e4-c192-4a70-aac4-4e37ea1079d0', '句', '句', '374d0716-c49f-4c5f-8e7d-0b63c6933432', '唐', '["芍藥花開菩薩面，椶閭葉散野人頭。"]', '["芍藥花开菩薩面，椶閭葉散野人头。"]', '诗', 'shi', '', NULL, '句 王璘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92e65081-9324-45fe-8f16-a51125619cb9', '句', '句', '2c60fac7-41aa-4ac5-a7ca-79b0fe59a4b9', '唐', '["虛心纖質雁銜餘，鳳吹龍吟定不如。"]', '["虛心纖質雁銜餘，鳳吹龙吟定不如。"]', '诗', 'shi', '', NULL, '句 李蔚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7cd3ffa-3992-402a-9bc4-2e0bac9c222d', '句', '句', 'd6499e34-efa0-4906-aa24-6ba9cb14009e', '唐', '["今朝拜貢盈襟淚，不進新芽是進心。"]', '["今朝拜貢盈襟泪，不進新芽是進心。"]', '诗', 'shi', '', NULL, '句 王枳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60c38de8-1f25-4d02-9b67-42381b0e7b05', '句', '句', '351937bb-9666-4ba4-bc52-1b28edf31532', '唐', '["萬蘊千牌次碧牙，縹牋金字間明霞。"]', '["万蘊千牌次碧牙，縹牋金字间明霞。"]', '诗', 'shi', '', NULL, '句 鄭賨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9320ce1-80f0-468f-82ce-90318e93ab10', '句', '句', '5cac4457-cfc1-41a5-93c9-908959a73ab1', '唐', '["一箭不中鵠，五湖歸釣魚。"]', '["一箭不中鵠，五湖归釣鱼。"]', '诗', 'shi', '', NULL, '句 張塋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72d76353-c364-4700-8ff3-b56869cac255', '句', '句', '5dc6d38a-5a88-4b83-88a5-21acb1deea55', '唐', '["煙隨紅焰斷，化作白雲飛。"]', '["煙隨紅焰斷，化作白云飞。"]', '诗', 'shi', '', NULL, '句 吳靄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89ea528e-530f-47ed-8122-5eaacc14825b', '句', '句', 'b99d19f8-7031-4c36-9a94-ce0fcaad6be0', '唐', '["隔岸水牛浮鼻渡，傍溪沙鳥點頭行。"]', '["隔岸水牛浮鼻渡，傍溪沙鸟点头行。"]', '诗', 'shi', '', NULL, '句 陳詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeac0e53-7191-47d9-909a-fddb74f60dbc', '句', '句', '6ae3e0bb-ed80-458d-beb5-7c2a233ba289', '唐', '["綺羅因片葉，桃李謾同時。"]', '["綺羅因片葉，桃李謾同时。"]', '诗', 'shi', '', NULL, '句 蔣密 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0332faef-e131-4708-a25b-5df5c1c16ec7', '句', '句', 'f00e1f75-dc09-4d86-a67e-02f9ad15c6bb', '唐', '["都緣心似水，故以鉢爲舟。"]', '["都緣心似水，故以鉢爲舟。"]', '诗', 'shi', '', NULL, '句 符蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('379a83c3-c898-4c3a-8ef0-41cf63315cea', '句', '句', 'b9bdc9ec-66e2-4b24-b553-0b9da020c947', '唐', '["路指丹陽分虎節，心存雙闕戀龍顏。"]', '["路指丹陽分虎節，心存雙闕戀龙顏。"]', '诗', 'shi', '', NULL, '句 李景遂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02f431b5-79db-45a6-a7ae-9409e9df6d27', '句', '句', 'c0ad4ecb-61bd-4176-a9db-e6588291b042', '唐', '["甜於泉水茶須信，狂似楊花蝶未知。","半窗月在猶煎藥，幾夜燈閑不照書。"]', '["甜於泉水茶須信，狂似楊花蝶未知。","半窗月在猶煎藥，幾夜灯闲不照书。"]', '诗', 'shi', '', NULL, '句 李弘茂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af14ba4e-6c10-403d-9446-05a8be3eb080', '句', '句', '29fed466-b35a-42a8-875d-9d3e3eaadc4b', '唐', '["至人無夢夢不到，天道惡盈盈有餘。","龍髯已斷嬪嬙老，豹尾不來岐路長。"]', '["至人無梦梦不到，天道惡盈盈有餘。","龙髯已斷嬪嬙老，豹尾不来岐路长。"]', '诗', 'shi', '', NULL, '句 李平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('709d42df-d50c-47b4-959e-d4f321b1a683', '句', '句', '6f4c231f-869a-4a8c-b179-23ea5ad0677d', '唐', '["翻身騰白浪，探爪擢明珠。"]', '["翻身腾白浪，探爪擢明珠。"]', '诗', 'shi', '', NULL, '句 胡元龜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7ae4e0a-7cd2-40cf-ab79-299926363ac7', '句', '句', 'bd4920ce-3ccd-46e3-badb-ab29633fc294', '唐', '["因借夢書過竹寺，學耕秋粟繞茆原。","芭蕉葉上無愁雨，自是多情聽斷腸。"]', '["因借梦书過竹寺，学耕秋粟繞茆原。","芭蕉葉上無愁雨，自是多情听斷腸。"]', '诗', 'shi', '', NULL, '句 蔣鈞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44f6d322-1f8a-4c43-9b0d-84d940037ccc', '句', '句', 'ac9aad4c-e212-44d3-8e17-f5692844a022', '唐', '["風雨揭却屋，全家醉不知。"]', '["风雨揭却屋，全家醉不知。"]', '诗', 'shi', '', NULL, '句 史虛白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30537484-2b51-45ad-b47e-4d69c4cb8abd', '句', '句', '5032d17e-e0c9-4d4d-8c84-b6af1e84e1ba', '唐', '["孤猨叫落中巖月，野客吟殘半夜燈。","雁飛南浦砧初斷，月滿西樓酒半醒。","曉來羸駟依前去，目斷遙山數點青。"]', '["孤猨叫落中巖月，野客吟殘半夜灯。","雁飞南浦砧初斷，月满西楼酒半醒。","晓来羸駟依前去，目斷遙山數点青。"]', '诗', 'shi', '', NULL, '句 夏寶松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51396ae6-18ba-463a-ba7d-4c2affe06e22', '句', '句', 'b128d398-7bbc-4c82-92ed-3a80b5b2ffc8', '唐', '["邁古文章金鸑鷟，出羣行止玉麒麟。"]', '["邁古文章金鸑鷟，出羣行止玉麒麟。"]', '诗', 'shi', '', NULL, '句 趙慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dc46479-dd24-430c-b5af-23568ab91b81', '句', '句', '89c80eca-7d3d-4c14-a17a-e34389059a46', '唐', '["風便磬聲遠，日斜樓影長。"]', '["风便磬声远，日斜楼影长。"]', '诗', 'shi', '', NULL, '句 潘天錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fda7011-9679-43f9-b1c5-30823eda6d44', '句', '句', '79c03f38-c5b6-4f79-8820-0269cf84e2db', '唐', '["好是晚來香雨裏，擔簦親送綺羅人。"]', '["好是晚来香雨裏，擔簦親送綺羅人。"]', '诗', 'shi', '', NULL, '句 朱勰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb8444a2-c152-432d-9f23-e76b31c06bd5', '句', '句', '19baacf6-f949-4864-8353-93f0f4197d00', '唐', '["蓮中花更好，雲裏月常新。"]', '["蓮中花更好，云裏月常新。"]', '诗', 'shi', '', NULL, '句 齊鎬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df8f60b5-5943-4954-9cce-ee9fac3891ba', '句', '句', 'd42912e4-32d0-4098-93a8-4be4c7180985', '唐', '["天下傳將舞馬賦，門前迎得跨驢賓。"]', '["天下傳將舞马賦，门前迎得跨驢賓。"]', '诗', 'shi', '', NULL, '句 黃可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6740d857-a680-4e78-a853-4efb3658a63d', '句', '句', '66215abd-dcc2-4464-af42-2d6d00c7774c', '唐', '["硯貯寒泉碧，庭堆敗葉紅。","燕掠琴弦穿靜院，吏收詩草下閑庭。"]', '["硯貯寒泉碧，庭堆敗葉紅。","燕掠琴弦穿静院，吏收诗草下闲庭。"]', '诗', 'shi', '', NULL, '句 高元矩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2211e928-6cf0-4419-a5ee-efe61df85b00', '句', '句', 'a8506600-e0f6-4826-bfab-57f0ffaacd9b', '唐', '["年年聞爾者，未有不傷情。","出得風塵者，合知岐路人。","拂榻燈未來，開門月先入。","忽生雲是匣，高以月爲臺。","入夜雖無傷物意，向明還有動人心。"]', '["年年闻爾者，未有不傷情。","出得风塵者，合知岐路人。","拂榻灯未来，开门月先入。","忽生云是匣，高以月爲台。","入夜雖無傷物意，向明還有动人心。"]', '诗', 'shi', '', NULL, '句 陳貺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3951f8f7-7646-4577-8977-6b99d88d305c', '句', '句', 'bd3ba744-8c5b-4fc2-bba1-85ad61f0b151', '唐', '["金莖來白露，玉宇起清風。"]', '["金莖来白露，玉宇起清风。"]', '诗', 'shi', '', NULL, '句 趙休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07352678-aa30-4556-ae3d-bc3509dd9216', '句', '句', '8e2c6568-427f-4248-9952-b095681ab9b0', '唐', '["紅斾渡江霞蘸水，青蛇出匣雪侵衣。","雲散便凝千里望，日斜長占半城陰。","只住此山寧有意，向來求佛本無心。"]', '["紅斾渡江霞蘸水，青蛇出匣雪侵衣。","云散便凝千里望，日斜长占半城陰。","只住此山寧有意，向来求佛本無心。"]', '诗', 'shi', '', NULL, '句 庸仁傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fcd167f-470c-482d-ba93-2ba78881e3a8', '句', '句', 'd0df22ec-afaf-443c-8bc6-da52f92e08e5', '唐', '["萬國不得雨，孤雲猶在山。"]', '["万国不得雨，孤云猶在山。"]', '诗', 'shi', '', NULL, '句 邵拙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66db48ca-501d-457f-b79c-6947018ce0b6', '句', '句', 'bb2ef540-3f74-4b2b-9031-83c2b72660ff', '唐', '["先生不在此，千載只空山。"]', '["先生不在此，千載只空山。"]', '诗', 'shi', '', NULL, '句 毛炳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dcc4ea9-687e-45ea-9779-b5d30b0dbf05', '句', '句', 'bbc8e560-c039-4ecb-bb3d-587079e66b9d', '唐', '["建水舊傳劉夜坐，螺川新有夏江城。"]', '["建水旧傳劉夜坐，螺川新有夏江城。"]', '诗', 'shi', '', NULL, '句 陳德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bcb1423-4a83-4c7a-9559-9145cfaf4135', '句', '句', '012e3267-7deb-4c4c-83e7-67e9d560351a', '唐', '["一雨洗殘暑，萬家生早涼。","暮鳥歸巢急，寒牛下隴遲。","算吟千百首，方得兩三聯。","清時不作登龍客，綠鬢閑梳傍草堂。"]', '["一雨洗殘暑，万家生早涼。","暮鸟归巢急，寒牛下隴遲。","算吟千百首，方得兩三聯。","清时不作登龙客，綠鬢闲梳傍草堂。"]', '诗', 'shi', '', NULL, '句 陳甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be4785c0-6a1d-41c3-80e1-0cd43621d03f', '句', '句', 'f0fda5ea-6397-44d4-b67b-6e9150ebf8ed', '唐', '["淮船分蟻隊，江市聚蠅聲。"]', '["淮船分蟻隊，江市聚蠅声。"]', '诗', 'shi', '', NULL, '句 徐融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c4d6d8c-1830-4930-b950-0e289f079212', '句', '句', '071698b3-48f9-418c-927d-8877d30610a2', '唐', '["人間不見月，天外自分明。"]', '["人间不见月，天外自分明。"]', '诗', 'shi', '', NULL, '句 高若拙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57760009-7038-47a8-9005-2d56a8ae4fd7', '句', '句', '504d535e-b48a-4d62-80f4-5359e03f57ac', '唐', '["燒平樵路出，潮落海山高。","行人折柳[和輕]絮，飛燕銜泥帶落花。"]', '["燒平樵路出，潮落海山高。","行人折柳[和轻]絮，飞燕銜泥带落花。"]', '诗', 'shi', '', NULL, '句 皮光業 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('291629f0-85b2-4bd3-8a73-f65a62d31673', '句', '句', '7e6207c4-c58e-4c4e-a01e-98eebdcf3cdc', '唐', '["輕身都是義，殉主始爲忠。"]', '["轻身都是義，殉主始爲忠。"]', '诗', 'shi', '', NULL, '句 屠瓌智 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac2a4af3-9f57-4258-952a-e997e5e96973', '句', '句', '111b2d8b-98a9-47e5-98dc-ee1ed55bd22e', '唐', '["滿堂羅綺兼朱紫，四代兒孫奉老翁。"]', '["满堂羅綺兼朱紫，四代兒孫奉老翁。"]', '诗', 'shi', '', NULL, '句 元德昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66f33e7b-89de-4ba7-a686-b98e0b868112', '句', '句', '374a5252-dc47-4069-a904-23f5bc900476', '唐', '["雪浦二月江湖闊，花發千山道路香。"]', '["雪浦二月江湖闊，花發千山道路香。"]', '诗', 'shi', '', NULL, '句 林無隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c72f6a53-4759-4e25-b443-b29953da5e1d', '句', '句', '3d17872c-1213-4aa8-90ff-1aa0c4aac566', '唐', '["海邊紅日半離水，天外暖風輕到花。","雨聲鞭自禁門出，一簇人從天上來。"]', '["海邊紅日半離水，天外暖风轻到花。","雨声鞭自禁门出，一簇人從天上来。"]', '诗', 'shi', '', NULL, '句 楊義方 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c4a8584-24ff-4c75-b269-cc2f67c3eb57', '句', '句', '12dda7b4-590f-4226-ac8d-ce0688cfcd8f', '唐', '["十字水中分島嶼，數重花外見樓臺。"]', '["十字水中分島嶼，數重花外见楼台。"]', '诗', 'shi', '', NULL, '句 王廷珪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef6c4d91-2021-48d7-b827-91f62b3e7744', '句', '句', '72eeb99b-0933-4b31-876c-2465ec0aa444', '唐', '["無錢將乞樊知客，名紙生毛不爲通。","桑柘殘陽裏，兒孫落葉中。"]', '["無錢將乞樊知客，名紙生毛不爲通。","桑柘殘陽裏，兒孫落葉中。"]', '诗', 'shi', '', NULL, '句 歐陽彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3917fe5e-a4f9-433e-9ed6-ec2b905e9911', '句', '句', '7ef559d4-1e4d-4863-a76e-9a2229447af1', '唐', '["向外疑無地，其中別有天。","方外共推爲道友，關中獨自占詩家。","炎暑鬱蒸無處避，涼風消息幾時來。"]', '["向外疑無地，其中別有天。","方外共推爲道友，关中独自占诗家。","炎暑鬱蒸無处避，涼风消息幾时来。"]', '诗', 'shi', '', NULL, '句 李堯夫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3bfb137-77c5-4b6b-82ba-754e7eb0881d', '句', '句', '258a91db-b734-4024-a74d-3cea84b93bc6', '唐', '["月沈湘浦冷，花謝漢宮秋。"]', '["月沈湘浦冷，花謝漢宮秋。"]', '诗', 'shi', '', NULL, '句 石文德 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07bfbd4a-a77b-4816-a955-a21501d4e0a3', '句', '句', '39836aad-8688-41ed-9e14-295a9e6ce1a1', '唐', '["須把咽喉吞世界，蓋因奢侈致危亡。","若須拋却便拋却，莫待風高更亦深。"]', '["須把咽喉吞世界，蓋因奢侈致危亡。","若須拋却便拋却，莫待风高更亦深。"]', '诗', 'shi', '', NULL, '句 戴偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2ab5a0c-ee8d-4b63-9128-19ee40d9e4f3', '句', '句', '311b40ef-8d58-432f-90dc-f5954976e3b5', '唐', '["夜長燈影滅，天遶鶴聲孤。"]', '["夜长灯影滅，天遶鹤声孤。"]', '诗', 'shi', '', NULL, '句 張迥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a055261-fbe9-4a0a-af31-5ef74140bcf7', '句', '句', 'ee212b02-ea81-4d1e-aeec-96360765beae', '唐', '["金筈離弦三尺電，星髇破的一聲雷。"]', '["金筈離弦三尺電，星髇破的一声雷。"]', '诗', 'shi', '', NULL, '句 鍾元章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7cba625-8488-4539-ade7-343bac07d59d', '句', '句', '5aac325d-4142-4298-8d58-48492c3c53c5', '唐', '["背日流泉生凍早，逆風歸鳥入巢遲。"]', '["背日流泉生凍早，逆风归鸟入巢遲。"]', '诗', 'shi', '', NULL, '句 楊鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdb9dc4b-3a32-4f39-9a8f-3ecf713d22d0', '句', '句', 'ab2e00b8-0dc0-426c-b7ba-5c50465105bc', '唐', '["勝日登樓望，山川一半春。"]', '["勝日登楼望，山川一半春。"]', '诗', 'shi', '', NULL, '句 王俊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80a3d075-085e-4c17-90bb-2575a91bfc13', '句', '句', '9887e589-97e6-498c-93bf-9d542c86b4a8', '唐', '["也知別有風光主，花蕾枝枝似去年。"]', '["也知別有风光主，花蕾枝枝似去年。"]', '诗', 'shi', '', NULL, '句 薛沆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('077b3f9e-d06b-4fae-8433-d7904e17e798', '句', '句', '9aed7403-f38b-421e-ae0d-eef4f6f877c7', '唐', '["金殿聖人看縱筆，玉堂詞客盡裁詩。"]', '["金殿聖人看縱笔，玉堂词客尽裁诗。"]', '诗', 'shi', '', NULL, '句 張顗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8037d5b-e55f-4f5a-9c71-5dfc42a10293', '句', '句', '0a407159-66ce-4b95-bb89-40d9366098ec', '唐', '["菱葉乍翻人採後，芰荷初沒舸行時。"]', '["菱葉乍翻人採後，芰荷初沒舸行时。"]', '诗', 'shi', '', NULL, '句 張林 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c054d81-b313-4c7d-ac68-ece85b1cb478', '句', '句', '56b92ce4-f5af-42b5-ad9a-6bf38fb8d140', '唐', '["春寒酒力遲，冉冉生微紅。","自然草木姓，誰祝元化功。","湓浦風生破膽愁，血染劍花明帳幕。","三千車馬出漁陽，入門堪笑復堪憐。","三逕苔荒一釣船。"]', '["春寒酒力遲，冉冉生微紅。","自然草木姓，誰祝元化功。","湓浦风生破膽愁，血染劍花明帳幕。","三千车马出漁陽，入门堪笑复堪怜。","三逕苔荒一釣船。"]', '诗', 'shi', '', NULL, '句 盧休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16e04216-8c0b-4349-a54e-a8b78dfa10e9', '句', '句', 'c454bad7-ebc4-474a-9194-07112ec735a8', '唐', '["小橋風月年年事，爭奈潘郎去□何。"]', '["小橋风月年年事，爭奈潘郎去□何。"]', '诗', 'shi', '', NULL, '句 陳嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('336854df-0c3f-4b4b-b213-22b0cec36ad2', '句', '句', 'aace013c-dc14-4261-9f97-9bf6cc5cb353', '唐', '["清猨啼遠木，白鳥下前灘。","鶴歸秋漢遠，人去草堂空。","雖當南北路，不礙往來人。","釣叟無機沙鳥睡，禪師入定白牛閑。","天涯故友無來信，窗外拒霜空落花。"]', '["清猨啼远木，白鸟下前灘。","鹤归秋漢远，人去草堂空。","雖當南北路，不礙往来人。","釣叟無機沙鸟睡，禪師入定白牛闲。","天涯故友無来信，窗外拒霜空落花。"]', '诗', 'shi', '', NULL, '句 李範 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc1094a7-cd5a-42d6-916e-b5706498f9b7', '句', '句', 'af132734-2411-4573-87b4-855f1b490562', '唐', '["雨壁長秋菌，風枝落病蟬。","老筇搘瘦影，寒木凭吟身。","詩債到春無處避，離愁因醉暫時無。","茶香解睡磨鐺煮，山色牽懷著屐登。"]', '["雨壁长秋菌，风枝落病蟬。","老筇搘瘦影，寒木凭吟身。","诗債到春無处避，離愁因醉暫时無。","茶香解睡磨鐺煮，山色牽懷著屐登。"]', '诗', 'shi', '', NULL, '句 卞震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d6fe4b9-d835-44ba-8462-b5b250df23f6', '句', '句', '6a7c3dc1-de69-475a-b092-a718331ef720', '唐', '["身閑不恨辭官早，詩好常甘得句遲。"]', '["身闲不恨辞官早，诗好常甘得句遲。"]', '诗', 'shi', '', NULL, '句 林楚才 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('488bc989-e6dd-4910-a449-4b48431daf0a', '句', '句', '67e8dc6d-14c9-4aea-b18a-0d868d08b747', '唐', '["白日故鄉遠，青山佳句中。"]', '["白日故乡远，青山佳句中。"]', '诗', 'shi', '', NULL, '句 孟不疑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f18febd1-3e77-4c2a-af1b-ffe20f44c836', '句', '句', 'e6515315-c6bb-442d-9d13-7c95dd1b1671', '唐', '["冥雲生易滿，秋草長難高。"]', '["冥云生易满，秋草长难高。"]', '诗', 'shi', '', NULL, '句 龐季子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16d3d3ac-1a84-479a-bdd7-89d8a0c64810', '句', '句', 'f2aa8220-41ed-4db6-b14b-199edf8a0863', '唐', '["落星一石幾千年，門外何人扣漢川。"]', '["落星一石幾千年，门外何人扣漢川。"]', '诗', 'shi', '', NULL, '句 郭思 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('487dab6d-d47a-4092-9e55-07c810278215', '句', '句', '414df875-d7a1-4884-b30d-02f423e9ad38', '唐', '["五千里地望皆見，七十二峰中最高。"]', '["五千里地望皆见，七十二峰中最高。"]', '诗', 'shi', '', NULL, '句 盧載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc767b4e-2132-43c7-aa3e-467a5098c5eb', '句', '句', '10cc1092-84d1-491a-8da5-1d2a6ba8a155', '唐', '["花燒落第眼，雨破到家程。"]', '["花燒落第眼，雨破到家程。"]', '诗', 'shi', '', NULL, '句 鄭翱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('884538a6-de5d-4a15-bf99-3b720752d519', '句', '句', '963ef91f-3f4a-463c-99c9-1b7cf8238336', '唐', '["架上紫衣閑不著，案頭金字坐長看。"]', '["架上紫衣闲不著，案头金字坐长看。"]', '诗', 'shi', '', NULL, '句 鄭說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e862844-0b30-4e5c-9d05-cbd8e512166c', '句', '句', '68ddcc6e-47d4-4267-b45f-cb120e86b8cd', '唐', '["溪從沮水流嶓冢，嶺接青泥入劍天。"]', '["溪從沮水流嶓冢，嶺接青泥入劍天。"]', '诗', 'shi', '', NULL, '句 史瑜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13d25bbe-dc88-4993-9366-f5a9f0d17798', '句', '句', 'ee835d74-0cd4-42b4-b851-e080a6fdb836', '唐', '["但存方寸地，留與子孫耕。"]', '["但存方寸地，留與子孫耕。"]', '诗', 'shi', '', NULL, '句 賀公 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdd0c931-91c9-411f-8e21-cc3a30c10f08', '句', '句', 'e50830e9-84ff-4834-874e-d70ef30e0281', '唐', '["小旗村店酒，微雨野塘花。"]', '["小旗村店酒，微雨野塘花。"]', '诗', 'shi', '', NULL, '句 米都知 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('490e300d-45fe-4efa-81fa-38cdb0b36c2a', '句', '句', '4c337930-ab27-4fc6-b5e1-ff67e246f7b1', '唐', '["地偏雲自起，日暮山更深。"]', '["地偏云自起，日暮山更深。"]', '诗', 'shi', '', NULL, '句 陳秀才 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ec68bb0-819c-4ed4-bd17-caae1ea404d7', '句', '句', '96983502-e37f-4192-b8dd-b6240936a1bc', '唐', '["恰似傳花人飲散，空拋牀下最繁枝。","豔魄香魂如有在，還應羞見墮樓人。"]', '["恰似傳花人饮散，空拋牀下最繁枝。","豔魄香魂如有在，還應羞见墮楼人。"]', '诗', 'shi', '', NULL, '句 崔李二生 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6357db03-3624-4713-b8f0-7358f7ae36b1', '句', '句', 'ef2b808f-e653-4a57-a91c-4f65582fc5c3', '唐', '["掃葉隨風便，澆花趁日陰。","閑雲生不雨，病葉落非秋。"]', '["掃葉隨风便，澆花趁日陰。","闲云生不雨，病葉落非秋。"]', '诗', 'shi', '', NULL, '句 范氏子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8da5f8c8-4b93-46cf-a3c6-88aaeed895c1', '句', '句', '9359d36a-4f10-4822-95c5-2a2d67196079', '唐', '["三月能辭千日醉，一生能得幾回看。"]', '["三月能辞千日醉，一生能得幾回看。"]', '诗', 'shi', '', NULL, '句 臨川小吏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25a1d6e2-c8b1-4251-9f7c-6b1934db348a', '句', '句', '4950cdc7-9a8f-491d-9552-07aa27dff050', '唐', '["最是五更留不住，向人枕畔著衣裳。"]', '["最是五更留不住，向人枕畔著衣裳。"]', '诗', 'shi', '', NULL, '句 韓熙載客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86b91114-d63c-4d7e-9480-111771d66c9a', '句', '句', '064a506f-9df0-467a-a4fe-0e1a0e2e4c8c', '唐', '["懸心秋夜月，萬里照鄉關。","玉排複道珊瑚殿，金錯危椆翡翠樓。","此花不與衆花同，爲感高僧護法功。"]', '["懸心秋夜月，万里照乡关。","玉排複道珊瑚殿，金錯危椆翡翠楼。","此花不與衆花同，爲感高僧護法功。"]', '诗', 'shi', '', NULL, '句 段義宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a6125bc-b864-4d6a-b16b-7cbfb86d4dcc', '無名氏之散句', '無名氏之散句', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["都來消帝力，全不用兵防。","道遠擎空鉢，深山踏落花。","船中江上景，晚泊早行時。","山寺鐘樓月，江城鼓角風。","雨過花爭出，雲空月半生。","鳥正啼隋柳，人須入楚山。","高松飄雨雪，一室掩香燈。","遂有冥心者，還尋此境來。","又因風雨夜，重到古松門。","道晦金雞伏，時來木馬鳴。","誰來看山寺，自去掃松門。","此生還自喜，餘事不相侵。","白鬢無心鑷，青山得意多。","一春能幾日，無雨亦多風。","苦雨秋濤漲，狂風野燒翻。","須知三尺劍，只爲不平磨。","要路爭先進，閑門肯暫過。","已難消永夜，況復聽秋霖。","大雪路亦宿，深山水也吞。","卷簾黃葉落，鏁印子規啼。","亡國空流水，孤祠掩落花。","山魅隔窗舞，鵩鳥入簾飛。","萬里八九月，一身西北風。","磴危攀薜荔，石滑疎莓苔。","日落無行客，天寒有去鴻。","正思浮世事，又到古城邊。","尋常風雨夜，應有鬼神看。","寄宿山中寺，相辭海上僧。","風吹榆莢葉，雨打木瓜花。","是星皆拱北，無水不朝東。","西風起邊雁，一一向瀟湘。","那堪懷遠路，猶自上高樓。","白雲風散盡，紅葉水流來。","妾如無異意，君棄也甘心。","野過雲根闊，山高樹影長。","古迹應重別，生緣不暫停。","一個字未穩，數宵心不閑。","別地葉頻落，去程山已寒。","但取詩名得，何論下第頻。","早起赴前程，鄰雞尚未鳴。","白地一回雨，兒孫拾得金。","軒車在何處，雨雪滿前山。","燈微山館雨，角咽海城秋。","去帆看已遠，臨水立多時。","家貧爲客早，路遠得書稀。","瀑布五千仞，草堂瀑布邊。","我憶雲門寺，門前千萬峰。","一瓶居無外，萬木老禪中。","秋江洗一鉢，寒日曬三衣。","空山行客少，獨樹晚蟬多。","一片月生海，幾家人上樓。","窗寒風漸緊，燈落夜將深。","雲夢幾行去，瀟湘一夜空。","無風來竹院，有月在莎庭。","故園從小別，夜雨近秋聞。","書劍別南州，炎荒萬里游。","山盤樵徑上，人到雪房遲。","路經秋雨後，人入亂峰來。","獨樹知秋早，孤舟覺夜寒。","馬飢飡落葉，鶴宿曬殘陽。","路遠春行盡，家貧愁到時。","臨水通宵坐，知君此興同。","江聲兼小雨，暝色入啼猨。","藕隱玲瓏玉，花藏縹緲容。","紅樹醉秋色，碧溪彈夜弦。","網斷蛛猶織，梁空燕不歸。","倒身無著處，呵手不成溫。","幾多詩弟子，無限酒知聞。","牀上小薰籠，韶州新退紅。","看時人步澁，展處蝶爭來。","酒味雜蓮氣，香冷勝於冰。","輪囷如象鼻，瀟灑絕青蠅。","太宗皇帝真長策，賺得英雄盡白頭。","曾題名處添前字，送出城人乞舊衣。","華陽觀裏鐘聲集，建福門前鼓動期。","隴右諸侯供語鳥，日南太守送名花。","八百孤寒齊下淚，一時回首望崖州。","讓劫已令多士伏，沽名還得世人聞。","人爲子推初禁火，花愁青女再飛霜。","楝花開後風光好，梅子黃時雨意濃。","蘭湯備浴傳荆俗，水馬浮江弔屈魂。","城頭椎鼓傳花枝，席上摶拳握松子。","鳥向不香花裏宿，人從無影月中歸。","輕著凍痕銷水面，密隨和氣入花根。","萬木盡如花落候，四簷鳴□雨來時。","濃綠萬枝紅一點，動人春色不須多。","晚菘細切肥牛肚，新笋初嘗嫩馬蹄。","蟬離楚樹鳴猶少，葉到嵩山落更多。","風和日暖方開眼，雨潤煙濃不舉頭。","窗前閑詠鴛鴦句，壁上時觀獬廌圖。","可能有事關心後，得似無人識面時。","一點孤燈人夢覺，萬重寒葉雨聲多。","此心只待相逢說，時復登樓看遠山。","九江有浪船難濟，三峽無猨客有愁。","四海魚龍精魄冷，五山鸞鳳骨毛寒。","誰家綠酒歡留客，何處紅樓睡失明。","雨露施恩無厚薄，蓬蒿隨分有枯榮。","去年花下留連飲，暖日夭桃鶯亂啼。","今日江邊容易別，淡煙衰草馬頻嘶。","蛇蝎性靈生便毒，蕙蘭根異死猶香。","三間茅屋無人到，十里松門獨自游。","翻憶舊山青碧裏，遶菴閑伴野僧禪。","不甘五等諸侯薦，直肯九重天子知。"]', '["都来消帝力，全不用兵防。","道远擎空鉢，深山踏落花。","船中江上景，晚泊早行时。","山寺鐘楼月，江城鼓角风。","雨過花爭出，云空月半生。","鸟正啼隋柳，人須入楚山。","高松飄雨雪，一室掩香灯。","遂有冥心者，還尋此境来。","又因风雨夜，重到古松门。","道晦金雞伏，时来木马鳴。","誰来看山寺，自去掃松门。","此生還自喜，餘事不相侵。","白鬢無心鑷，青山得意多。","一春能幾日，無雨亦多风。","苦雨秋濤漲，狂风野燒翻。","須知三尺劍，只爲不平磨。","要路爭先進，闲门肯暫過。","已难消永夜，況复听秋霖。","大雪路亦宿，深山水也吞。","卷簾黄葉落，鏁印子規啼。","亡国空流水，孤祠掩落花。","山魅隔窗舞，鵩鸟入簾飞。","万里八九月，一身西北风。","磴危攀薜荔，石滑疎莓苔。","日落無行客，天寒有去鴻。","正思浮世事，又到古城邊。","尋常风雨夜，應有鬼神看。","寄宿山中寺，相辞海上僧。","风吹榆莢葉，雨打木瓜花。","是星皆拱北，無水不朝东。","西风起邊雁，一一向瀟湘。","那堪懷远路，猶自上高楼。","白云风散尽，紅葉水流来。","妾如無異意，君棄也甘心。","野過云根闊，山高樹影长。","古迹應重別，生緣不暫停。","一個字未穩，數宵心不闲。","別地葉頻落，去程山已寒。","但取诗名得，何論下第頻。","早起赴前程，鄰雞尚未鳴。","白地一回雨，兒孫拾得金。","軒车在何处，雨雪满前山。","灯微山館雨，角咽海城秋。","去帆看已远，臨水立多时。","家貧爲客早，路远得书稀。","瀑布五千仞，草堂瀑布邊。","我憶云门寺，门前千万峰。","一瓶居無外，万木老禪中。","秋江洗一鉢，寒日曬三衣。","空山行客少，独樹晚蟬多。","一片月生海，幾家人上楼。","窗寒风漸緊，灯落夜將深。","云梦幾行去，瀟湘一夜空。","無风来竹院，有月在莎庭。","故园從小別，夜雨近秋闻。","书劍別南州，炎荒万里游。","山盤樵徑上，人到雪房遲。","路經秋雨後，人入亂峰来。","独樹知秋早，孤舟覺夜寒。","马飢飡落葉，鹤宿曬殘陽。","路远春行尽，家貧愁到时。","臨水通宵坐，知君此兴同。","江声兼小雨，暝色入啼猨。","藕隐玲瓏玉，花藏縹緲容。","紅樹醉秋色，碧溪彈夜弦。","網斷蛛猶织，梁空燕不归。","倒身無著处，呵手不成溫。","幾多诗弟子，無限酒知闻。","牀上小薰籠，韶州新退紅。","看时人步澁，展处蝶爭来。","酒味杂蓮氣，香冷勝於冰。","輪囷如象鼻，瀟灑絕青蠅。","太宗皇帝真长策，賺得英雄尽白头。","曾題名处添前字，送出城人乞旧衣。","华陽观裏鐘声集，建福门前鼓动期。","隴右諸侯供語鸟，日南太守送名花。","八百孤寒齊下泪，一时回首望崖州。","讓劫已令多士伏，沽名還得世人闻。","人爲子推初禁火，花愁青女再飞霜。","楝花开後风光好，梅子黄时雨意濃。","蘭湯備浴傳荆俗，水马浮江弔屈魂。","城头椎鼓傳花枝，席上摶拳握松子。","鸟向不香花裏宿，人從無影月中归。","轻著凍痕銷水面，密隨和氣入花根。","万木尽如花落候，四簷鳴□雨来时。","濃綠万枝紅一点，动人春色不須多。","晚菘細切肥牛肚，新笋初嘗嫩马蹄。","蟬離楚樹鳴猶少，葉到嵩山落更多。","风和日暖方开眼，雨潤煙濃不舉头。","窗前闲詠鴛鴦句，壁上时观獬廌圖。","可能有事关心後，得似無人識面时。","一点孤灯人梦覺，万重寒葉雨声多。","此心只待相逢说，时复登楼看远山。","九江有浪船难濟，三峽無猨客有愁。","四海鱼龙精魄冷，五山鸾鳳骨毛寒。","誰家綠酒歡留客，何处紅楼睡失明。","雨露施恩無厚薄，蓬蒿隨分有枯榮。","去年花下留連饮，暖日夭桃鶯亂啼。","今日江邊容易別，淡煙衰草马頻嘶。","蛇蝎性靈生便毒，蕙蘭根異死猶香。","三间茅屋無人到，十里松门独自游。","翻憶旧山青碧裏，遶菴闲伴野僧禪。","不甘五等諸侯薦，直肯九重天子知。"]', '诗', 'shi', '', NULL, '無名氏之散句 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff686ccf-4c4b-4ab6-850a-9903cf1ca49b', '離別難', '離別难', 'd6c28248-92cc-4030-bf55-bef59e0afc17', '唐', '["此別難重陳，花飛復戀人。","來時梅覆雪，去日柳含春。","物候催行客，歸途淑氣新。","剡川今已遠，魂夢暗相親。"]', '["此別难重陳，花飞复戀人。","来时梅覆雪，去日柳含春。","物候催行客，归途淑氣新。","剡川今已远，魂梦暗相親。"]', '诗', 'shi', '', NULL, '離別難 武后宮人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18e47a78-465f-4459-8acf-e344b9139445', '袍中詩', '袍中诗', '37841338-bc0a-464e-b6e5-d6031789955d', '唐', '["沙場征戍客，寒苦若爲眠。","戰袍經手作，知落阿誰邊。","蓄意多添線，含情更著綿。","今生已過也，結取後生緣。"]', '["沙場征戍客，寒苦若爲眠。","戰袍經手作，知落阿誰邊。","蓄意多添線，含情更著綿。","今生已過也，結取後生緣。"]', '诗', 'shi', '', NULL, '袍中詩 開元宮人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2d9fa8e-5872-480a-ad45-b1b62af3619a', '題洛苑梧葉上', '題洛苑梧葉上', '40da0b81-195c-43fb-ab4e-c6174cb12de0', '唐', '["舊寵悲秋扇，新恩寄早春。","聊題一片葉，將寄接流人。"]', '["旧寵悲秋扇，新恩寄早春。","聊題一片葉，將寄接流人。"]', '诗', 'shi', '', NULL, '題洛苑梧葉上 天寶宮人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71077c12-3f1e-40bc-b453-2fa73f3be4aa', '又題洛苑梧葉上', '又題洛苑梧葉上', '40da0b81-195c-43fb-ab4e-c6174cb12de0', '唐', '["一葉題詩出禁城，誰人酬和獨含情。","自嗟不及波中葉，蕩漾乘春取次行。"]', '["一葉題诗出禁城，誰人酬和独含情。","自嗟不及波中葉，蕩漾乘春取次行。"]', '诗', 'shi', '', NULL, '又題洛苑梧葉上 天寶宮人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cd54f56-4ee1-4e91-827b-d6874acd09b2', '題花葉詩', '題花葉诗', '8b901b3e-3b85-456b-87d8-17d4214d2ca0', '唐', '["一入深宮裏，無由得見春。","題詩花葉上，寄與接流人。"]', '["一入深宮裏，無由得见春。","題诗花葉上，寄與接流人。"]', '诗', 'shi', '', NULL, '題花葉詩 德宗宮人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50ec05b8-7d2f-4fe9-b430-3192a631661b', '題紅葉', '題紅葉', 'e2338b0b-fac3-476d-8a5c-321a57fe04a0', '唐', '["流水何太急，深宮盡日閑。","殷勤謝紅葉，好去到人間。"]', '["流水何太急，深宮尽日闲。","殷勤謝紅葉，好去到人间。"]', '诗', 'shi', '', NULL, '題紅葉 宣宗宮人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16a3b6dc-330d-40ed-8745-330e6be43447', '金鎖詩', '金鎖诗', '52515a6d-6c99-499f-a81a-20f7c36a0b5b', '唐', '["玉燭製袍夜，金刀呵手裁。","鎖寄千里客，鎖心終不開。"]', '["玉燭製袍夜，金刀呵手裁。","鎖寄千里客，鎖心終不开。"]', '诗', 'shi', '', NULL, '金鎖詩 僖宗宮人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ccb9964-33a0-4f10-9f05-a329230f87a9', '隨駕遊青城', '隨駕游青城', 'dde31e1a-2bb3-48e6-b688-38cd311b84e5', '唐', '["因隨八馬上仙山，頓隔塵埃物象閑。","只恐西追王母宴，却憂難得到人間。"]', '["因隨八马上仙山，頓隔塵埃物象闲。","只恐西追王母宴，却憂难得到人间。"]', '诗', 'shi', '', NULL, '隨駕遊青城 李舜弦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fdc3682-bfe8-409c-86b5-e50451643c6b', '蜀宮應制', '蜀宮應制', 'dde31e1a-2bb3-48e6-b688-38cd311b84e5', '唐', '["濃樹禁花開後庭，飲筵中散酒微醒。","濛濛雨草瑤階溼，鐘曉愁吟獨倚屏。"]', '["濃樹禁花开後庭，饮筵中散酒微醒。","濛濛雨草瑤階溼，鐘晓愁吟独倚屏。"]', '诗', 'shi', '', NULL, '蜀宮應制 李舜弦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d9f6363-173c-4bf8-b124-d154ad6f4694', '釣魚不得', '釣鱼不得', 'dde31e1a-2bb3-48e6-b688-38cd311b84e5', '唐', '["盡日池邊釣錦鱗，芰荷香裏暗消魂。","依稀縱有尋香餌，知是金鉤不肯吞。"]', '["尽日池邊釣錦鱗，芰荷香裏暗消魂。","依稀縱有尋香餌，知是金鉤不肯吞。"]', '诗', 'shi', '', NULL, '釣魚不得 李舜弦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dafb0d6-94c1-4eeb-b795-bf3e74ee3f12', '宮詞', '宮词', '2507dd9a-ffe6-4f24-bc0e-7b0b5ed4e98c', '唐', '["鴛鴦瓦上瞥然聲，晝寢宮娥夢裏驚。","元是我王金彈子，海棠花下打流鶯。"]', '["鴛鴦瓦上瞥然声，晝寢宮娥梦裏驚。","元是我王金彈子，海棠花下打流鶯。"]', '诗', 'shi', '', NULL, '宮詞 李玉簫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1004be4-46d5-429b-9ae1-435191c5c1cc', '太平詩', '太平诗', '3a56e7f7-8f31-43d4-9a89-beb853acde63', '唐', '["大唐開鴻業，巍巍皇猷昌。","止戈戎衣定，修文繼百王。","統天崇雨施，理物體含章。","深仁諧日月，撫運邁時康。","幡旗既赫赫，鉦鼓何鍠鍠。","外夷違命者，翦覆被大殃。","和風凝宇宙，遐邇競呈祥。","四時調玉燭，七曜巡萬方。","維嶽降宰輔，維帝用忠良。","三五咸一德，昭我皇家唐。"]', '["大唐开鴻業，巍巍皇猷昌。","止戈戎衣定，修文繼百王。","統天崇雨施，理物體含章。","深仁諧日月，撫運邁时康。","幡旗既赫赫，鉦鼓何鍠鍠。","外夷違命者，翦覆被大殃。","和风凝宇宙，遐邇競呈祥。","四时調玉燭，七曜巡万方。","維嶽降宰輔，維帝用忠良。","三五咸一德，昭我皇家唐。"]', '诗', 'shi', '', NULL, '太平詩 金真德 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34aabcf6-f33a-4d3b-8f64-a4e3c1c631c3', '句', '句', 'c842193a-b75f-4589-bdec-92eedb1250b7', '唐', '["寶帳香重重，一雙紅芙蓉。"]', '["寶帳香重重，一雙紅芙蓉。"]', '诗', 'shi', '', NULL, '句 寶曆宮人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0e68e7b-b6ee-46ff-8ac7-702e23414bb6', '宮詞 一', '宮词 一', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["五雲樓閣鳳城間，花木長新日月閑。","三十六宮連內苑，太平天子住崑山。"]', '["五云楼閣鳳城间，花木长新日月闲。","三十六宮連內苑，太平天子住崑山。"]', '诗', 'shi', '', NULL, '宮詞 一 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('248c8d76-79f4-4eec-85d2-787450337820', '宮詞 二', '宮词 二', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["會真廣殿約宮牆，樓閣相扶倚太陽。","淨甃玉階橫水岸，御爐香氣撲龍牀。"]', '["會真廣殿約宮牆，楼閣相扶倚太陽。","淨甃玉階橫水岸，御爐香氣撲龙牀。"]', '诗', 'shi', '', NULL, '宮詞 二 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85c09fb6-e343-437b-b967-43c186bbbd21', '宮詞 三', '宮词 三', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["龍池九曲遠相通，楊柳絲牽兩岸風。","長似江南好風景，畫船來去碧波中。"]', '["龙池九曲远相通，楊柳絲牽兩岸风。","长似江南好风景，畫船来去碧波中。"]', '诗', 'shi', '', NULL, '宮詞 三 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40caafff-5129-45fd-b9b6-a5c3501231b6', '宮詞 四', '宮词 四', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["東內斜將紫禁通，龍池鳳苑夾城中。","曉鐘聲斷嚴妝罷，院院紗窗海日紅。"]', '["东內斜將紫禁通，龙池鳳苑夾城中。","晓鐘声斷嚴妝罷，院院紗窗海日紅。"]', '诗', 'shi', '', NULL, '宮詞 四 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0c34c15-54bc-46fa-a176-61985afd55b3', '宮詞 五', '宮词 五', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["殿名新立號重光，島上亭臺盡改張。","但是一人行幸處，黃金閣子鎖牙牀。"]', '["殿名新立號重光，島上亭台尽改張。","但是一人行幸处，黄金閣子鎖牙牀。"]', '诗', 'shi', '', NULL, '宮詞 五 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cddbb9e-766e-4e82-b2ef-004211eea6a3', '宮詞 六', '宮词 六', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["夾城門與內門通，朝罷巡遊到苑中。","每日日高祗候處，滿堤紅豔立春風。"]', '["夾城门與內门通，朝罷巡游到苑中。","每日日高祗候处，满堤紅豔立春风。"]', '诗', 'shi', '', NULL, '宮詞 六 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8923a856-4edb-4529-8be2-492e398640cf', '宮詞 七', '宮词 七', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["廚船進食簇時新，侍宴無非列近臣。","日午殿頭宣索鱠，隔花催喚打魚人。"]', '["廚船進食簇时新，侍宴無非列近臣。","日午殿头宣索鱠，隔花催喚打鱼人。"]', '诗', 'shi', '', NULL, '宮詞 七 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df9ffa54-6b61-4ae1-89f6-616c8b15da28', '宮詞 八', '宮词 八', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["立春日進內園花，紅蕊輕輕嫩淺霞。","跪到玉階猶帶露，一時宣賜與宮娃。"]', '["立春日進內园花，紅蕊轻轻嫩淺霞。","跪到玉階猶带露，一时宣賜與宮娃。"]', '诗', 'shi', '', NULL, '宮詞 八 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84659c6c-c707-4f17-9df2-aa892fb5b57e', '宮詞 九', '宮词 九', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["三面宮城盡夾牆，苑中池水白茫茫。","直從獅子門前入，旋見亭臺遶岸傍。"]', '["三面宮城尽夾牆，苑中池水白茫茫。","直從獅子门前入，旋见亭台遶岸傍。"]', '诗', 'shi', '', NULL, '宮詞 九 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a76cfded-dd13-4e10-9879-b9986bfa6479', '宮詞 十', '宮词 十', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["離宮別院遶宮城，金版輕敲合鳳笙。","夜夜月明花樹底，傍池長有按歌聲。"]', '["離宮別院遶宮城，金版轻敲合鳳笙。","夜夜月明花樹底，傍池长有按歌声。"]', '诗', 'shi', '', NULL, '宮詞 十 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49c4ade2-3c03-43b7-a436-c68a466222e7', '宮詞 十一', '宮词 十一', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["御製新翻曲子成，六宮纔唱未知名。","盡將觱篥來抄譜，先按君王玉笛聲。"]', '["御製新翻曲子成，六宮纔唱未知名。","尽將觱篥来抄譜，先按君王玉笛声。"]', '诗', 'shi', '', NULL, '宮詞 十一 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb749e60-9a7b-47ab-89d3-417862aa13c5', '宮詞 十二', '宮词 十二', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["旋移紅樹斲新苔，宣使龍池更鑿開。","展得綠波寬似海，水心樓殿勝蓬萊。"]', '["旋移紅樹斲新苔，宣使龙池更鑿开。","展得綠波寬似海，水心楼殿勝蓬萊。"]', '诗', 'shi', '', NULL, '宮詞 十二 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55935bb7-f84b-42f2-8830-b523fff9e21d', '宮詞 十三', '宮词 十三', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["太虛高閣凌虛殿，背倚城牆面枕池。","諸院各分娘子位，羊車到處不教知。"]', '["太虛高閣凌虛殿，背倚城牆面枕池。","諸院各分娘子位，羊车到处不教知。"]', '诗', 'shi', '', NULL, '宮詞 十三 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bf754a5-ebf0-4ef3-874a-df35b53f255b', '宮詞 十四', '宮词 十四', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["修儀承寵住龍池，掃地焚香日午時。","等候大家來院裏，看教鸚鵡念新詩。"]', '["修儀承寵住龙池，掃地焚香日午时。","等候大家来院裏，看教鸚鵡念新诗。"]', '诗', 'shi', '', NULL, '宮詞 十四 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee6b11ed-3b5b-421e-83bd-cb093aaf78c5', '宮詞 十五', '宮词 十五', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["才人出入每參隨，筆硯將行遶曲池。","能向彩箋書大字，忽防御製寫新詩。"]', '["才人出入每參隨，笔硯將行遶曲池。","能向彩箋书大字，忽防御製寫新诗。"]', '诗', 'shi', '', NULL, '宮詞 十五 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0ce5d58-e64e-4569-b749-a30cfc26a057', '宮詞 十六', '宮词 十六', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["六宮官職總新除，宮女安排入畫圖。","二十四司分六局，御前頻見錯相呼。"]', '["六宮官職總新除，宮女安排入畫圖。","二十四司分六局，御前頻见錯相呼。"]', '诗', 'shi', '', NULL, '宮詞 十六 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32120a22-ff49-4fb9-8518-9c5f11fcaeca', '宮詞 十七', '宮词 十七', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["春風一面曉妝成，偷折花枝傍水行。","却被內監遙覷見，故將紅豆打黃鶯。"]', '["春风一面晓妝成，偷折花枝傍水行。","却被內監遙覷见，故將紅豆打黄鶯。"]', '诗', 'shi', '', NULL, '宮詞 十七 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('654404eb-2ef9-494b-aeba-e142d003a53f', '宮詞 十八', '宮词 十八', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["殿前排宴賞花開，宮女侵晨探幾回。","斜望花開遙舉袖，傳聲宣喚近臣來。"]', '["殿前排宴賞花开，宮女侵晨探幾回。","斜望花开遙舉袖，傳声宣喚近臣来。"]', '诗', 'shi', '', NULL, '宮詞 十八 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d0a6499-4d0b-4de2-96ef-783ccc74bbd3', '宮詞 十九', '宮词 十九', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["小毬場近曲池頭，宣喚勳臣試打毬。","先向畫樓排御幄，管絃聲動立浮油。"]', '["小毬場近曲池头，宣喚勳臣試打毬。","先向畫楼排御幄，管絃声动立浮油。"]', '诗', 'shi', '', NULL, '宮詞 十九 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1d2f5d3-9e7a-46f4-b89d-0867d8ed1797', '宮詞 二十', '宮词 二十', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["供奉頭籌不敢爭，上棚等喚近臣名。","內人酌酒纔宣賜，馬上齊呼萬歲聲。"]', '["供奉头籌不敢爭，上棚等喚近臣名。","內人酌酒纔宣賜，马上齊呼万歲声。"]', '诗', 'shi', '', NULL, '宮詞 二十 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('822d14a4-1c98-47d7-8913-857af3d27b28', '宮詞 二十一', '宮词 二十一', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["殿前宮女總纖腰，初學乘騎怯又嬌。","上得馬來纔欲走，幾回拋鞚抱鞍橋。"]', '["殿前宮女總纖腰，初学乘騎怯又嬌。","上得马来纔欲走，幾回拋鞚抱鞍橋。"]', '诗', 'shi', '', NULL, '宮詞 二十一 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17e00c36-8e47-48a1-8126-f271ea47eea8', '宮詞 二十二', '宮词 二十二', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["自教宮娥學打毬，玉鞍初跨柳腰柔。","上棚知是官家認，遍遍長贏第一籌。"]', '["自教宮娥学打毬，玉鞍初跨柳腰柔。","上棚知是官家認，遍遍长贏第一籌。"]', '诗', 'shi', '', NULL, '宮詞 二十二 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a851e76d-9982-41f1-a67a-19f36de8f98f', '宮詞 二十三', '宮词 二十三', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["翔鸞閣外夕陽天，樹影花光遠接連。","望見內家來往處，水門斜過罨樓船。"]', '["翔鸾閣外夕陽天，樹影花光远接連。","望见內家来往处，水门斜過罨楼船。"]', '诗', 'shi', '', NULL, '宮詞 二十三 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c619599-1e16-455f-a361-a3b3448b50ec', '宮詞 二十四', '宮词 二十四', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["內家追逐採蓮時，驚起沙歐兩岸飛。","蘭棹把來齊拍水，並船相鬬溼羅衣。"]', '["內家追逐採蓮时，驚起沙歐兩岸飞。","蘭棹把来齊拍水，並船相鬬溼羅衣。"]', '诗', 'shi', '', NULL, '宮詞 二十四 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8691e473-cdce-47ca-aee2-a81b29942d4b', '宮詞 二十五', '宮词 二十五', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["新秋女伴各相逢，罨畫船飛別浦中。","旋折荷花伴歌舞，夕陽斜照滿衣紅。"]', '["新秋女伴各相逢，罨畫船飞別浦中。","旋折荷花伴歌舞，夕陽斜照满衣紅。"]', '诗', 'shi', '', NULL, '宮詞 二十五 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dca209ec-eaa3-453c-b63d-c8647d55f7d3', '宮詞 二十六', '宮词 二十六', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["少年相逐採蓮回，羅帽羅衫巧製裁。","每到岸頭長拍水，競提纖手出船來。"]', '["少年相逐採蓮回，羅帽羅衫巧製裁。","每到岸头长拍水，競提纖手出船来。"]', '诗', 'shi', '', NULL, '宮詞 二十六 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27071504-abb7-427a-8c4a-7bb8429d61ae', '宮詞 二十七', '宮词 二十七', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["早春楊柳引長條，倚岸沿堤一面高。","稱與畫船牽錦纜，暖風搓出綵絲縧。"]', '["早春楊柳引长條，倚岸沿堤一面高。","稱與畫船牽錦纜，暖风搓出綵絲縧。"]', '诗', 'shi', '', NULL, '宮詞 二十七 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a5dc356-e6d4-4976-a8ed-a60c3d9e6889', '宮詞 二十八', '宮词 二十八', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["內家宣錫生辰宴，隔夜諸宮進御花。","後殿未聞宮主入，東門先報下金車。"]', '["內家宣錫生辰宴，隔夜諸宮進御花。","後殿未闻宮主入，东门先報下金车。"]', '诗', 'shi', '', NULL, '宮詞 二十八 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b19ec03b-62ed-426b-b6be-968df5d02471', '宮詞 二十九', '宮词 二十九', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["端午生衣進御牀，赭黃羅帕覆金箱。","美人捧入南薰殿，玉腕斜封綵縷長。"]', '["端午生衣進御牀，赭黄羅帕覆金箱。","美人捧入南薰殿，玉腕斜封綵縷长。"]', '诗', 'shi', '', NULL, '宮詞 二十九 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('686e20d4-8258-47a6-abed-f720923c9fe9', '宮詞 三十', '宮词 三十', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["選進仙韶第一人，纔勝羅綺不勝春。","重教按舞桃花下，只踏殘紅作地裀。"]', '["選進仙韶第一人，纔勝羅綺不勝春。","重教按舞桃花下，只踏殘紅作地裀。"]', '诗', 'shi', '', NULL, '宮詞 三十 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a002bc8-2f7b-4fd5-9974-fa6dd71582ca', '宮詞 三十一', '宮词 三十一', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["侍女爭揮玉彈弓，金丸飛入亂花中。","一時驚起流鶯散，踏落殘花滿地紅。"]', '["侍女爭揮玉彈弓，金丸飞入亂花中。","一时驚起流鶯散，踏落殘花满地紅。"]', '诗', 'shi', '', NULL, '宮詞 三十一 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20be117b-444e-4425-b557-fd296e2fc114', '宮詞 三十二', '宮词 三十二', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["七寶闌干白玉除，新開涼殿幸金輿。","一溝泛碧流春水，四面瓊鉤搭綺疏。"]', '["七寶闌干白玉除，新开涼殿幸金輿。","一溝泛碧流春水，四面瓊鉤搭綺疏。"]', '诗', 'shi', '', NULL, '宮詞 三十二 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a51f775e-d0f3-4cc9-a845-36e8ef3a044d', '宮詞 三十三', '宮词 三十三', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["山樓彩鳳棲寒月，宴殿金麟吐御香。","蜀錦地衣呈隊舞，教頭先出拜君王。"]', '["山楼彩鳳棲寒月，宴殿金麟吐御香。","蜀錦地衣呈隊舞，教头先出拜君王。"]', '诗', 'shi', '', NULL, '宮詞 三十三 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c332515-ac37-4e62-b1ca-cf10a28af0df', '宮詞 三十四', '宮词 三十四', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["天外明河翻玉浪，樓西涼月湧金盆。","香銷甲乙牀前帳，宮鎖玲瓏閉殿門。"]', '["天外明河翻玉浪，楼西涼月湧金盆。","香銷甲乙牀前帳，宮鎖玲瓏閉殿门。"]', '诗', 'shi', '', NULL, '宮詞 三十四 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f36cac6-90ff-4eae-b57d-d06bbf7adfd7', '宮詞 三十五', '宮词 三十五', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["細風攲葉撼宮梧，早怯秋寒著繡繻。","玉宇無人雙燕去，一彎新月上金樞。"]', '["細风攲葉撼宮梧，早怯秋寒著繡繻。","玉宇無人雙燕去，一彎新月上金樞。"]', '诗', 'shi', '', NULL, '宮詞 三十五 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c61825f-b097-46fe-bef3-9cadadb05cc8', '宮詞 三十六', '宮词 三十六', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["夜寒金屋篆煙飛，燈燭分明在紫微。","漏永禁宮三十六，燕回爭踏月輪歸。"]', '["夜寒金屋篆煙飞，灯燭分明在紫微。","漏永禁宮三十六，燕回爭踏月輪归。"]', '诗', 'shi', '', NULL, '宮詞 三十六 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32c22368-8cb0-47fb-b2ef-412af37905cc', '宮詞 三十七', '宮词 三十七', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["曉吹翩翩動翠旗，爐煙千疊瑞雲飛。","何人奏對偏移刻，御史天香隔繡衣。"]', '["晓吹翩翩动翠旗，爐煙千叠瑞云飞。","何人奏对偏移刻，御史天香隔繡衣。"]', '诗', 'shi', '', NULL, '宮詞 三十七 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62464f07-5224-4e92-8da9-9d7ee8e1c587', '宮詞 三十八', '宮词 三十八', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["金井秋啼絡緯聲，出花宮漏報嚴更。","不知誰是金鑾直，玉宇沈沈夜氣清。"]', '["金井秋啼絡緯声，出花宮漏報嚴更。","不知誰是金鑾直，玉宇沈沈夜氣清。"]', '诗', 'shi', '', NULL, '宮詞 三十八 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c260ae0-aead-45e5-aad6-ffc41f9852e3', '宮詞 三十九', '宮词 三十九', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["內庭秋燕玉池東，香散荷花水殿風。","阿監采菱牽錦纜，月明猶在畫船中。"]', '["內庭秋燕玉池东，香散荷花水殿风。","阿監采菱牽錦纜，月明猶在畫船中。"]', '诗', 'shi', '', NULL, '宮詞 三十九 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('930ac842-fb1d-4cd7-8b9a-b150c2c1646c', '宮詞 四十', '宮词 四十', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["東宮花燭彩樓新，天上仙橋上鎖春。","偏出六宮歌舞奏，嫦娥初到月虛輪。"]', '["东宮花燭彩楼新，天上仙橋上鎖春。","偏出六宮歌舞奏，嫦娥初到月虛輪。"]', '诗', 'shi', '', NULL, '宮詞 四十 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('760f9913-820b-4a5b-b160-2ffef80f60ec', '宮詞 四十一', '宮词 四十一', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["紗幔薄垂金麥穗，簾鉤纖挂玉蔥條。","樓西別起長春殿，香碧紅泥透蜀椒。"]', '["紗幔薄垂金麦穗，簾鉤纖挂玉蔥條。","楼西別起长春殿，香碧紅泥透蜀椒。"]', '诗', 'shi', '', NULL, '宮詞 四十一 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a54290de-ac37-45cf-8155-ab5626f4ccf4', '宮詞 四十二', '宮词 四十二', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["翠華香重玉爐添，雙鳳樓頭曉日暹。","扇掩紅鸞金殿悄，一聲清蹕捲珠簾。"]', '["翠华香重玉爐添，雙鳳楼头晓日暹。","扇掩紅鸾金殿悄，一声清蹕捲珠簾。"]', '诗', 'shi', '', NULL, '宮詞 四十二 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b768f3f6-8c5d-4dff-b8ed-2f74f6b8e111', '宮詞 四十三', '宮词 四十三', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["金作蟠龍繡作麟，壺中樓閣禁中春。","君王避暑來遊幸，風月橫秋氣象新。"]', '["金作蟠龙繡作麟，壺中楼閣禁中春。","君王避暑来游幸，风月橫秋氣象新。"]', '诗', 'shi', '', NULL, '宮詞 四十三 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22532b11-0610-4580-af9c-e45c4fd2c8c5', '宮詞 四十四', '宮词 四十四', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["清曉自傾花上露，冷侵宮殿玉蟾蜍。","擘開五色銷金紙，碧鎖窗前學草書。"]', '["清晓自傾花上露，冷侵宮殿玉蟾蜍。","擘开五色銷金紙，碧鎖窗前学草书。"]', '诗', 'shi', '', NULL, '宮詞 四十四 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40e37425-9898-4fc2-bf19-4117de819f67', '宮詞 四十五', '宮词 四十五', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["翠鈿貼靨輕如笑，玉鳳雕釵褭欲飛。","拂曉賀春皇帝閣，綵衣金勝近龍衣。"]', '["翠鈿貼靨轻如笑，玉鳳雕釵褭欲飞。","拂晓賀春皇帝閣，綵衣金勝近龙衣。"]', '诗', 'shi', '', NULL, '宮詞 四十五 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3855892-1e64-402b-babc-7d2ba992dd31', '宮詞 四十六', '宮词 四十六', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["璅聲金徹閤門環，簾捲珍珠十二間。","別殿春風呼萬歲，中丞新押散朝班。"]', '["璅声金徹閤门环，簾捲珍珠十二间。","別殿春风呼万歲，中丞新押散朝班。"]', '诗', 'shi', '', NULL, '宮詞 四十六 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58b98851-ed3b-4d1b-8d51-f02bfe16342d', '宮詞 四十七', '宮词 四十七', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["雞人報曉傳三唱，玉井金牀轉轆轤。","煙引御爐香繞殿，漏籤初刻上銅壺。"]', '["雞人報晓傳三唱，玉井金牀轉轆轤。","煙引御爐香繞殿，漏籤初刻上銅壺。"]', '诗', 'shi', '', NULL, '宮詞 四十七 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d950c838-25fa-4810-975a-3f69f1f6e0cb', '宮詞 四十八', '宮词 四十八', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["御按橫金殿幄紅，扇開雲表露天容。","太常奏備三千曲，樂府新調十二鐘。"]', '["御按橫金殿幄紅，扇开云表露天容。","太常奏備三千曲，乐府新調十二鐘。"]', '诗', 'shi', '', NULL, '宮詞 四十八 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa46826d-e216-4d76-a20b-b1f7cdf2984d', '宮詞 四十九', '宮词 四十九', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["宮女熏香進御衣，殿門開鎖請金匙。","朝陽初上黃金屋，禁夜春深晝漏遲。"]', '["宮女熏香進御衣，殿门开鎖請金匙。","朝陽初上黄金屋，禁夜春深晝漏遲。"]', '诗', 'shi', '', NULL, '宮詞 四十九 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad55651a-4fa0-4526-8509-e2f8726a0edd', '宮詞 五十', '宮词 五十', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["三月金明柳絮飛，岸花堤草弄春時。","樓船百戲催宣賜，御輦今年不上池。"]', '["三月金明柳絮飞，岸花堤草弄春时。","楼船百戲催宣賜，御輦今年不上池。"]', '诗', 'shi', '', NULL, '宮詞 五十 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66760aad-62a5-476f-ab8d-005602464714', '宮詞 五十一', '宮词 五十一', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["內人稀見水鞦韆，爭擘珠簾帳殿前。","第一錦標誰奪得，右軍輸却小龍船。"]', '["內人稀见水鞦韆，爭擘珠簾帳殿前。","第一錦標誰奪得，右軍輸却小龙船。"]', '诗', 'shi', '', NULL, '宮詞 五十一 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bf35f68-19e7-4a48-abb7-e58a7d83bfb8', '宮詞 五十二', '宮词 五十二', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["夜色樓臺月數層，金猊煙穗繞觚稜。","重廊屈折連三殿，密上真珠百寶燈。"]', '["夜色楼台月數層，金猊煙穗繞觚稜。","重廊屈折連三殿，密上真珠百寶灯。"]', '诗', 'shi', '', NULL, '宮詞 五十二 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1eb1a042-39d3-4883-b789-9baa091f5ead', '宮詞 五十三', '宮词 五十三', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["天門晏閉九重關，樓倚銀河氣象間。","一點星毬垂絳闕，五雲仙仗下蓬山。"]', '["天门晏閉九重关，楼倚銀河氣象间。","一点星毬垂絳闕，五云仙仗下蓬山。"]', '诗', 'shi', '', NULL, '宮詞 五十三 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9d48a39-5dc8-4db4-85c7-23ab573734cb', '宮詞 五十四', '宮词 五十四', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["禁裏春濃蝶自飛，御蠶眠處弄新絲。","碧窗盡日教鸚鵡，念得君王數首詩。"]', '["禁裏春濃蝶自飞，御蠶眠处弄新絲。","碧窗尽日教鸚鵡，念得君王數首诗。"]', '诗', 'shi', '', NULL, '宮詞 五十四 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f0c40ad-ae87-4332-83e5-d54315aca05e', '宮詞 五十五', '宮词 五十五', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["鬬草深宮玉檻前，春蒲如箭荇如錢。","不如紅藥闌干曲，日暮何人落翠鈿。"]', '["鬬草深宮玉檻前，春蒲如箭荇如錢。","不如紅藥闌干曲，日暮何人落翠鈿。"]', '诗', 'shi', '', NULL, '宮詞 五十五 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f95a8af4-3cb6-4675-a33a-97ed80181fd7', '宮詞 五十六', '宮词 五十六', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["太液波清水殿涼，畫船驚起宿鴛鴦。","翠眉不及池邊柳，取次飛花入建章。"]', '["太液波清水殿涼，畫船驚起宿鴛鴦。","翠眉不及池邊柳，取次飞花入建章。"]', '诗', 'shi', '', NULL, '宮詞 五十六 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6ad82c9-cfd8-4814-9ef6-6cab2146039e', '宮詞 五十七', '宮词 五十七', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["御座垂簾繡額單，冰山重疊貯金盤。","玉清迢遰無塵到，殿角東西五月寒。"]', '["御座垂簾繡額單，冰山重叠貯金盤。","玉清迢遰無塵到，殿角东西五月寒。"]', '诗', 'shi', '', NULL, '宮詞 五十七 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bb56dda-cce9-4974-b2bf-cf0e180c9ade', '宮詞 五十八', '宮词 五十八', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["春心滴破花邊漏，曉夢敲回禁裏鐘。","十二楚山何處是，御樓曾見兩三峰。"]', '["春心滴破花邊漏，晓梦敲回禁裏鐘。","十二楚山何处是，御楼曾见兩三峰。"]', '诗', 'shi', '', NULL, '宮詞 五十八 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14960b91-dfec-4807-b84d-fa0392b2521a', '宮詞 五十九', '宮词 五十九', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["博山夜宿沈香火，帳外時聞暖鳳笙。","理遍從頭新上曲，殿前龍直未交更。"]', '["博山夜宿沈香火，帳外时闻暖鳳笙。","理遍從头新上曲，殿前龙直未交更。"]', '诗', 'shi', '', NULL, '宮詞 五十九 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2672119b-3f05-4e46-ae0a-6c5283416d64', '宮詞 六十', '宮词 六十', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["春殿千官宴却歸，上林鶯舌報花時。","宣徽旋進新裁曲，學士爭吟應詔詩。"]', '["春殿千官宴却归，上林鶯舌報花时。","宣徽旋進新裁曲，学士爭吟應詔诗。"]', '诗', 'shi', '', NULL, '宮詞 六十 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16c3c5cc-21fc-4098-a344-e9d845a50658', '宮詞 六十一', '宮词 六十一', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["釣線沈波漾彩舟，魚爭芳餌上龍鉤。","內人急捧金盤接，撥刺紅鱗躍未休。"]', '["釣線沈波漾彩舟，鱼爭芳餌上龙鉤。","內人急捧金盤接，撥刺紅鱗躍未休。"]', '诗', 'shi', '', NULL, '宮詞 六十一 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62e593a8-bd0a-434a-aa65-b319c8a04705', '宮詞 六十二', '宮词 六十二', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["蕙炷香銷燭影殘，御衣熏盡輙更闌。","歸來困頓眠紅帳，一枕西風夢裏寒。"]', '["蕙炷香銷燭影殘，御衣熏尽輙更闌。","归来困頓眠紅帳，一枕西风梦裏寒。"]', '诗', 'shi', '', NULL, '宮詞 六十二 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e2cd49e-ab13-47fb-a928-e8f6a89a6d9e', '宮詞 六十三', '宮词 六十三', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["東宮降誕挺佳辰，少海星邊擁瑞雲。","中尉傳聞三日宴，翰林當撰洗兒文。"]', '["东宮降誕挺佳辰，少海星邊擁瑞云。","中尉傳闻三日宴，翰林當撰洗兒文。"]', '诗', 'shi', '', NULL, '宮詞 六十三 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91c907ab-9263-45ef-99fc-5580882b87c0', '宮詞 六十四', '宮词 六十四', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["酒庫新修近水傍，潑醅初熟五雲漿。","殿前供御頻宣索，追入花間一陣香。"]', '["酒庫新修近水傍，潑醅初熟五云漿。","殿前供御頻宣索，追入花间一陣香。"]', '诗', 'shi', '', NULL, '宮詞 六十四 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f6c1e0b-78f9-4c4d-aaff-d006dfa025d6', '宮詞 六十五', '宮词 六十五', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["白藤花限白銀花，閤子門當寢殿斜。","近被宮中知了事，每來隨駕使煎茶。"]', '["白藤花限白銀花，閤子门當寢殿斜。","近被宮中知了事，每来隨駕使煎茶。"]', '诗', 'shi', '', NULL, '宮詞 六十五 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10299208-dcd5-4a68-af1d-0dad93da0224', '宮詞 六十六', '宮词 六十六', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["西毬場裏打毬回，御宴先於苑內開。","宣索教坊諸伎樂，傍池催喚入船來。"]', '["西毬場裏打毬回，御宴先於苑內开。","宣索教坊諸伎乐，傍池催喚入船来。"]', '诗', 'shi', '', NULL, '宮詞 六十六 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2372ef2-44be-44d2-a946-2c18ea1fd709', '宮詞 六十七', '宮词 六十七', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["昭儀侍宴足精神，玉燭抽看記飲巡。","倚賴識書爲錄事，燈前時復錯瞞人。"]', '["昭儀侍宴足精神，玉燭抽看記饮巡。","倚賴識书爲錄事，灯前时复錯瞞人。"]', '诗', 'shi', '', NULL, '宮詞 六十七 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fcd57bf-a707-4183-b1bb-dcb15cb467f7', '宮詞 六十八', '宮词 六十八', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["後宮阿監裹羅巾，出入經過苑囿頻。","承奉聖顏憂悞失，就中長怕內夫人。"]', '["後宮阿監裹羅巾，出入經過苑囿頻。","承奉聖顏憂悞失，就中长怕內夫人。"]', '诗', 'shi', '', NULL, '宮詞 六十八 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdf3eb32-ca13-4f2c-a06c-d2d05df08af3', '宮詞 六十九', '宮词 六十九', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["管弦聲急滿龍池，宮女藏鉤夜宴時。","好是聖人親捉得，便將濃墨掃雙眉。"]', '["管弦声急满龙池，宮女藏鉤夜宴时。","好是聖人親捉得，便將濃墨掃雙眉。"]', '诗', 'shi', '', NULL, '宮詞 六十九 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9289db62-f7c8-442a-9482-cc6482244148', '宮詞 七十', '宮词 七十', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["密室紅泥地火爐，內人冬日晚傳呼。","今宵駕幸池頭宿，排比椒房得煖無。"]', '["密室紅泥地火爐，內人冬日晚傳呼。","今宵駕幸池头宿，排比椒房得煖無。"]', '诗', 'shi', '', NULL, '宮詞 七十 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('720c96c8-244d-466b-ab17-bd10c67349f7', '宮詞 七十一', '宮词 七十一', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["畫船花舫總新妝，進入池心近島傍。","松柏樓窗楠木板，暖風吹過一團香。"]', '["畫船花舫總新妝，進入池心近島傍。","松柏楼窗楠木板，暖风吹過一團香。"]', '诗', 'shi', '', NULL, '宮詞 七十一 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e575f23f-4dcf-47ce-90e8-7bd405a1be70', '宮詞 七十二', '宮词 七十二', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["三清臺近苑牆東，樓檻層層映水紅。","盡日綺羅人度曲，管弦聲在半天中。"]', '["三清台近苑牆东，楼檻層層映水紅。","尽日綺羅人度曲，管弦声在半天中。"]', '诗', 'shi', '', NULL, '宮詞 七十二 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c37cf787-b4f5-4b6d-b9f7-b3b33f697522', '宮詞 七十三', '宮词 七十三', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["安排諸院接行廊，外檻周迴十里強。","青錦地衣紅繡毯，盡鋪龍腦鬱金香。"]', '["安排諸院接行廊，外檻周迴十里強。","青錦地衣紅繡毯，尽鋪龙腦鬱金香。"]', '诗', 'shi', '', NULL, '宮詞 七十三 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ed45983-cc09-489d-a45f-108556421912', '宮詞 七十四', '宮词 七十四', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["安排竹柵與笆籬，養得新生鵓鴿兒。","宣受內家專餵飼，花毛間看總皆知。"]', '["安排竹柵與笆籬，養得新生鵓鴿兒。","宣受內家專餵飼，花毛间看總皆知。"]', '诗', 'shi', '', NULL, '宮詞 七十四 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ce1949d-9b22-4572-8e4d-2db7bd6126c5', '宮詞 七十五', '宮词 七十五', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["年初十五最風流，新賜雲鬟便上頭。","按罷霓裳歸院裏，畫樓雲閣總重修。"]', '["年初十五最风流，新賜云鬟便上头。","按罷霓裳归院裏，畫楼云閣總重修。"]', '诗', 'shi', '', NULL, '宮詞 七十五 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5af7083-b223-4ef5-a1bc-7ad01e589481', '宮詞 七十六', '宮词 七十六', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["金畫香臺出露盤，黃龍雕刻遶朱闌。","焚修每遇三元節，天子親簪白玉冠。"]', '["金畫香台出露盤，黄龙雕刻遶朱闌。","焚修每遇三元節，天子親簪白玉冠。"]', '诗', 'shi', '', NULL, '宮詞 七十六 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d95e45df-8def-4647-949e-396c857b31cc', '宮詞 七十七', '宮词 七十七', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["六宮一例雞冠子，新樣交鐫白玉花。","欲試澹妝兼道服，面前宣與唾盂家。"]', '["六宮一例雞冠子，新樣交鐫白玉花。","欲試澹妝兼道服，面前宣與唾盂家。"]', '诗', 'shi', '', NULL, '宮詞 七十七 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ad62f99-207e-4ebd-99d7-6591290da3b3', '宮詞 七十八', '宮词 七十八', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["三月櫻桃乍熟時，內人相引看紅枝。","回頭索取黃金彈，遶樹藏身打雀兒。"]', '["三月櫻桃乍熟时，內人相引看紅枝。","回头索取黄金彈，遶樹藏身打雀兒。"]', '诗', 'shi', '', NULL, '宮詞 七十八 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a2da73a-925d-4138-bc51-fd66d1c50e72', '宮詞 七十九', '宮词 七十九', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["小小宮娥到內園，未梳雲鬢臉如蓮。","自從配與夫人後，不使尋花亂入船。"]', '["小小宮娥到內园，未梳云鬢臉如蓮。","自從配與夫人後，不使尋花亂入船。"]', '诗', 'shi', '', NULL, '宮詞 七十九 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('808fb0e5-7f18-40e0-9d1b-5145e5a7570a', '宮詞 八十', '宮词 八十', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["錦城上起凝煙閣，擁殿遮樓一向高。","認得聖顏遙望見，碧闌干映赭黃袍。"]', '["錦城上起凝煙閣，擁殿遮楼一向高。","認得聖顏遙望见，碧闌干映赭黄袍。"]', '诗', 'shi', '', NULL, '宮詞 八十 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01d953c6-8d1a-4408-92df-8cca8d5d6e68', '宮詞 八十一', '宮词 八十一', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["水車踏水上宮城，寢殿簷頭滴滴鳴。","助得聖人高枕興，夜涼長作遠灘聲。"]', '["水车踏水上宮城，寢殿簷头滴滴鳴。","助得聖人高枕兴，夜涼长作远灘声。"]', '诗', 'shi', '', NULL, '宮詞 八十一 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5d38ddb-4839-4841-b036-be9d1d54c9d9', '宮詞 八十二', '宮词 八十二', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["平頭船子小龍床，多少神仙立御旁。","旋刺篙竿令過岸，滿池春水蘸紅妝。"]', '["平头船子小龙床，多少神仙立御旁。","旋刺篙竿令過岸，满池春水蘸紅妝。"]', '诗', 'shi', '', NULL, '宮詞 八十二 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d850f153-f860-4c6a-9688-bcd366456aa1', '宮詞 八十三', '宮词 八十三', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["苑東天子愛巡游，御岸花堤枕碧流。","新教內人供射鴨，長將弓箭繞池頭。"]', '["苑东天子愛巡游，御岸花堤枕碧流。","新教內人供射鴨，长將弓箭繞池头。"]', '诗', 'shi', '', NULL, '宮詞 八十三 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1580733d-d8ce-4c48-a468-bb389be08a98', '宮詞 八十四', '宮词 八十四', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["羅衫玉帶最風流，斜插銀箆慢裹頭。","閑向殿前騎御馬，揮鞭橫過小紅樓。"]', '["羅衫玉带最风流，斜插銀箆慢裹头。","闲向殿前騎御马，揮鞭橫過小紅楼。"]', '诗', 'shi', '', NULL, '宮詞 八十四 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abde7444-574f-4427-ac3e-e4c1c07fd094', '宮詞 八十五', '宮词 八十五', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["沈香亭子傍池斜，夏日巡游歇翠華。","簾畔玉盆盛淨水，內人手裏剖銀瓜。"]', '["沈香亭子傍池斜，夏日巡游歇翠华。","簾畔玉盆盛淨水，內人手裏剖銀瓜。"]', '诗', 'shi', '', NULL, '宮詞 八十五 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c25bbd21-7c49-4b50-aa6e-a58f94c58601', '宮詞 八十六', '宮词 八十六', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["薄羅衫子透肌膚，夏日初長板閣虛。","獨自凭闌無一事，水風涼處讀文書。"]', '["薄羅衫子透肌膚，夏日初长板閣虛。","独自凭闌無一事，水风涼处读文书。"]', '诗', 'shi', '', NULL, '宮詞 八十六 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38da881f-c8f2-4d76-ad73-8adee172897c', '宮詞 八十七', '宮词 八十七', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["婕妤生長帝王家，常近龍顏逐翠華。","楊柳岸長春日暮，傍池行困倚桃花。"]', '["婕妤生长帝王家，常近龙顏逐翠华。","楊柳岸长春日暮，傍池行困倚桃花。"]', '诗', 'shi', '', NULL, '宮詞 八十七 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b7d6c79-d685-4a27-8d1c-074fd24e0815', '宮詞 八十八', '宮词 八十八', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["月頭支給買花錢，滿殿宮人近數千。","遇著唱名多不語，含羞走過御牀前。"]', '["月头支給買花錢，满殿宮人近數千。","遇著唱名多不語，含羞走過御牀前。"]', '诗', 'shi', '', NULL, '宮詞 八十八 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dbe3a5f-0e06-4b01-b0ed-7e5f82d0f4fc', '宮詞 八十九', '宮词 八十九', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["小雨霏微潤綠苔，石楠紅杏傍池開。","一枝插向金瓶裏，捧進君王玉殿來。"]', '["小雨霏微潤綠苔，石楠紅杏傍池开。","一枝插向金瓶裏，捧進君王玉殿来。"]', '诗', 'shi', '', NULL, '宮詞 八十九 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15438298-f849-44f0-a62c-bbe77e93a62c', '宮詞 九十', '宮词 九十', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["錦鱗躍水出浮萍，荇草牽風翠帶橫。","恰似金梭攛碧沼，好題幽恨寫閨情。"]', '["錦鱗躍水出浮萍，荇草牽风翠带橫。","恰似金梭攛碧沼，好題幽恨寫閨情。"]', '诗', 'shi', '', NULL, '宮詞 九十 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b43783b4-fc4f-44ec-ba83-97e788519aef', '宮詞 九十一', '宮词 九十一', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["春天睡起曉妝成，隨侍君王觸處行。","畫得自家梳洗樣，相憑女伴把來呈。"]', '["春天睡起晓妝成，隨侍君王觸处行。","畫得自家梳洗樣，相憑女伴把来呈。"]', '诗', 'shi', '', NULL, '宮詞 九十一 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ad1bfb7-5972-4379-b1e2-6ba61b366649', '宮詞 九十二', '宮词 九十二', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["舞頭皆著畫羅衣，唱得新翻御製詞。","每日內庭聞教隊，樂聲飛上到龍墀。"]', '["舞头皆著畫羅衣，唱得新翻御製词。","每日內庭闻教隊，乐声飞上到龙墀。"]', '诗', 'shi', '', NULL, '宮詞 九十二 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a8251dc-ac2c-42ff-89a3-088f4441c547', '宮詞 九十三', '宮词 九十三', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["春早尋花入內園，競傳宣旨欲黃昏。","明朝駕幸遊蠶市，暗使氊車就苑門。"]', '["春早尋花入內园，競傳宣旨欲黄昏。","明朝駕幸游蠶市，暗使氊车就苑门。"]', '诗', 'shi', '', NULL, '宮詞 九十三 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be517c51-7751-4f15-a4cc-efc8f1e5d209', '宮詞 九十四', '宮词 九十四', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["半夜搖船載內家，水門紅蠟一行斜。","聖人正在宮中飲，宣使池頭旋折花。"]', '["半夜搖船載內家，水门紅蠟一行斜。","聖人正在宮中饮，宣使池头旋折花。"]', '诗', 'shi', '', NULL, '宮詞 九十四 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8d1bb61-2e01-469e-9342-95a1a1faf0ce', '宮詞 九十五', '宮词 九十五', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["春日龍池小宴開，岸邊亭子號流杯。","沈檀刻作神仙女，對捧金尊水上來。"]', '["春日龙池小宴开，岸邊亭子號流杯。","沈檀刻作神仙女，对捧金尊水上来。"]', '诗', 'shi', '', NULL, '宮詞 九十五 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('274dbb18-7b49-4888-b15f-ea841384f60d', '宮詞 九十六', '宮词 九十六', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["梨園子弟簇池頭，小樂攜來候宴游。","旋炙銀笙先按拍，海棠花下合梁州。"]', '["梨园子弟簇池头，小乐携来候宴游。","旋炙銀笙先按拍，海棠花下合梁州。"]', '诗', 'shi', '', NULL, '宮詞 九十六 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08bbac5c-6b1d-42db-8a52-8487c8b524cc', '宮詞 九十七', '宮词 九十七', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["慢梳鬟髻著輕紅，春早爭求芍藥叢。","近日承恩移住處，夾城裏面占新宮。"]', '["慢梳鬟髻著轻紅，春早爭求芍藥叢。","近日承恩移住处，夾城裏面占新宮。"]', '诗', 'shi', '', NULL, '宮詞 九十七 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab96880b-a6c0-4d1f-bea2-cc26e9bbdef1', '宮詞 九十八', '宮词 九十八', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["別色官司御輦家，黃衫束帶臉如花。","深宮內院參承慣，常從金輿到日斜。"]', '["別色官司御輦家，黄衫束带臉如花。","深宮內院參承慣，常從金輿到日斜。"]', '诗', 'shi', '', NULL, '宮詞 九十八 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d71f1566-df13-42ca-918e-8b7180bc24d1', '宮詞 九十九', '宮词 九十九', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["日高房裏學圍碁，等候官家未出時。","爲賭金錢爭路數，專憂女伴怪來遲。"]', '["日高房裏学圍碁，等候官家未出时。","爲賭金錢爭路數，專憂女伴怪来遲。"]', '诗', 'shi', '', NULL, '宮詞 九十九 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('876235f6-32da-4210-94bd-8c90f7bc8432', '宮詞 一百', '宮词 一百', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["摴蒱冷澹學投壺，箭倚腰身約畫圖。","盡對君王稱妙手，一人來射一人輸。"]', '["摴蒱冷澹学投壺，箭倚腰身約畫圖。","尽对君王稱妙手，一人来射一人輸。"]', '诗', 'shi', '', NULL, '宮詞 一百 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26763dc2-ddf7-46e1-8e5b-20c909d6bd32', '宮詞 一百一', '宮词 一百一', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["慢揎紅袖指纖纖，學釣池魚傍水邊。","忍冷不禁還自去，釣竿常被別人牽。"]', '["慢揎紅袖指纖纖，学釣池鱼傍水邊。","忍冷不禁還自去，釣竿常被別人牽。"]', '诗', 'shi', '', NULL, '宮詞 一百一 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a2a77b9-6e16-4949-91d9-67814d443f8e', '宮詞 一百二', '宮词 一百二', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["宣城院約池南岸，粉壁紅窗畫不成。","總是一人行幸處，徹宵聞奏管弦聲。"]', '["宣城院約池南岸，粉壁紅窗畫不成。","總是一人行幸处，徹宵闻奏管弦声。"]', '诗', 'shi', '', NULL, '宮詞 一百二 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fafb557c-7139-49a1-a4ff-3f3b6373951c', '宮詞 一百三', '宮词 一百三', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["丹霞亭浸池心冷，曲沼門含水脚清。","傍岸鴛鴦皆著對，時時出向淺沙行。"]', '["丹霞亭浸池心冷，曲沼门含水脚清。","傍岸鴛鴦皆著对，时时出向淺沙行。"]', '诗', 'shi', '', NULL, '宮詞 一百三 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d194ea8a-8a30-4441-86b5-3354bf226b8e', '宮詞 一百四', '宮词 一百四', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["楊柳陰中引御溝，碧梧桐樹擁朱樓。","金陵城共滕王閣，畫向丹青也合羞。"]', '["楊柳陰中引御溝，碧梧桐樹擁朱楼。","金陵城共滕王閣，畫向丹青也合羞。"]', '诗', 'shi', '', NULL, '宮詞 一百四 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('659d6ea7-4744-499b-a49b-aaaaf7bc080e', '宮詞 一百五', '宮词 一百五', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["晚來隨駕上城游，行到東西百子樓。","回望苑中花柳色，綠陰紅豔滿池頭。"]', '["晚来隨駕上城游，行到东西百子楼。","回望苑中花柳色，綠陰紅豔满池头。"]', '诗', 'shi', '', NULL, '宮詞 一百五 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a02fcd79-41d9-446d-a035-f2c571c2184b', '宮詞 一百六', '宮词 一百六', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["牡丹移向苑中栽，盡是藩方進入來。","未到末春緣地暖，數般顏色一時開。"]', '["牡丹移向苑中栽，尽是藩方進入来。","未到末春緣地暖，數般顏色一时开。"]', '诗', 'shi', '', NULL, '宮詞 一百六 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb5d880e-5c1a-4365-a53b-010eab3a2764', '宮詞 一百七', '宮词 一百七', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["明朝臘日官家出，隨駕先須點內人。","回鶻衣裝回鶻馬，就中偏稱小腰身。"]', '["明朝臘日官家出，隨駕先須点內人。","回鶻衣裝回鶻马，就中偏稱小腰身。"]', '诗', 'shi', '', NULL, '宮詞 一百七 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a700d86-d868-42ea-803e-b16957ac963d', '宮詞 一百八', '宮词 一百八', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["盤鳳鞍韉閃色妝，黃金壓胯紫游韁。","自從揀得真龍種，別置東頭小馬坊。"]', '["盤鳳鞍韉閃色妝，黄金壓胯紫游韁。","自從揀得真龙種，別置东头小马坊。"]', '诗', 'shi', '', NULL, '宮詞 一百八 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10f1478c-6822-4230-b9b4-5eb4dc4f011b', '宮詞 一百九', '宮词 一百九', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["翠輦每從城畔出，內人相次簇池隈。","嫩荷花裏搖船去，一陣香風逐水來。"]', '["翠輦每從城畔出，內人相次簇池隈。","嫩荷花裏搖船去，一陣香风逐水来。"]', '诗', 'shi', '', NULL, '宮詞 一百九 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('729f146d-ce0f-4590-b8d4-ffeb07621ee6', '宮詞 一百一十', '宮词 一百一十', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["高燒紅燭點銀燈，秋晚花池景色澄。","今夜聖人新殿宿，後宮相競覓祇承。"]', '["高燒紅燭点銀灯，秋晚花池景色澄。","今夜聖人新殿宿，後宮相競覓祇承。"]', '诗', 'shi', '', NULL, '宮詞 一百一十 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cc630e3-1160-4b19-8fd0-1c590f75ea94', '宮詞 一一一', '宮词 一一一', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["苑中排比宴秋宵，弦管掙摐各自調。","日晚閣門傳聖旨，明朝盡放紫宸朝。"]', '["苑中排比宴秋宵，弦管掙摐各自調。","日晚閣门傳聖旨，明朝尽放紫宸朝。"]', '诗', 'shi', '', NULL, '宮詞 一一一 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4e2a8db-f500-4c9b-9b8f-72cfdf9ba025', '宮詞 一一二', '宮词 一一二', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["夜深飲散月初斜，無限宮嬪亂插花。","近侍婕妤先過水，遙聞隔岸喚船家。"]', '["夜深饮散月初斜，無限宮嬪亂插花。","近侍婕妤先過水，遙闻隔岸喚船家。"]', '诗', 'shi', '', NULL, '宮詞 一一二 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9376904b-c934-4c8e-a149-87fdcaaf9207', '宮詞 一一三', '宮词 一一三', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["宮娥小小豔紅妝，唱得歌聲遶畫梁。","緣是太妃新進入，座前頒賜小羅箱。"]', '["宮娥小小豔紅妝，唱得歌声遶畫梁。","緣是太妃新進入，座前頒賜小羅箱。"]', '诗', 'shi', '', NULL, '宮詞 一一三 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06422b27-23a9-4077-85d1-8715e27fb1c1', '宮詞 一一四', '宮词 一一四', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["池心小樣釣魚船，入玩偏宜向晚天。","挂得綵帆教便放，急風吹過水門前。"]', '["池心小樣釣鱼船，入玩偏宜向晚天。","挂得綵帆教便放，急风吹過水门前。"]', '诗', 'shi', '', NULL, '宮詞 一一四 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5d93023-ef82-4a65-9991-d5c0abefadf8', '宮詞 一一五', '宮词 一一五', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["傍池居住有漁家，收網搖船到淺沙。","預進活魚供日料，滿筐跳躍白銀花。"]', '["傍池居住有漁家，收網搖船到淺沙。","預進活鱼供日料，满筐跳躍白銀花。"]', '诗', 'shi', '', NULL, '宮詞 一一五 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b90a7a8-09d8-41d7-b531-9d21f4273d82', '宮詞 一一六', '宮词 一一六', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["秋晚紅妝傍水行，競將衣袖撲蜻蜓。","回頭瞥見宮中喚，幾度藏身入畫屏。"]', '["秋晚紅妝傍水行，競將衣袖撲蜻蜓。","回头瞥见宮中喚，幾度藏身入畫屏。"]', '诗', 'shi', '', NULL, '宮詞 一一六 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f58ddcb8-b5af-4881-a61d-44dccdfe3b79', '宮詞 一一七', '宮词 一一七', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["御溝春水碧于天，宮女尋花入內園。","汗溼紅妝行漸困，岸頭相喚洗花鈿。"]', '["御溝春水碧于天，宮女尋花入內园。","汗溼紅妝行漸困，岸头相喚洗花鈿。"]', '诗', 'shi', '', NULL, '宮詞 一一七 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65b328c0-cfc8-4aa7-b874-86eb8363b1fe', '宮詞 一一八', '宮词 一一八', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["亭高百尺立春風，引得君王到此中。","牀上翠屏開六扇，折枝花綻牡丹紅。"]', '["亭高百尺立春风，引得君王到此中。","牀上翠屏开六扇，折枝花綻牡丹紅。"]', '诗', 'shi', '', NULL, '宮詞 一一八 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35bfc82c-285a-40b4-9401-cb9691d7d3b7', '宮詞 一一九', '宮词 一一九', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["內人承寵賜新房，紅紙泥窗遶畫廊。","種得海柑纔結子，乞求自送與君王。"]', '["內人承寵賜新房，紅紙泥窗遶畫廊。","種得海柑纔結子，乞求自送與君王。"]', '诗', 'shi', '', NULL, '宮詞 一一九 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b98f1cc-efbb-436e-9593-a5a330f08479', '宮詞 一百二十', '宮词 一百二十', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["翡翠簾前日影斜，御溝春水浸成霞。","侍臣向晚隨天步，共看池頭滿樹花。"]', '["翡翠簾前日影斜，御溝春水浸成霞。","侍臣向晚隨天步，共看池头满樹花。"]', '诗', 'shi', '', NULL, '宮詞 一百二十 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c9a1be0-9ea7-49a5-92e0-86b3858f4264', '宮詞 一二一', '宮词 一二一', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["金碧闌干倚岸邊，捲簾初聽一聲蟬。","殿頭日午搖紈扇，宮女爭來玉座前。"]', '["金碧闌干倚岸邊，捲簾初听一声蟬。","殿头日午搖紈扇，宮女爭来玉座前。"]', '诗', 'shi', '', NULL, '宮詞 一二一 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3109bfef-690e-4902-88a6-99bc6c93e08e', '宮詞 一二二', '宮词 一二二', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["嫩荷香撲釣魚亭，水面文魚作隊行。","宮女齊來池畔看，傍簾呼喚勿高聲。"]', '["嫩荷香撲釣鱼亭，水面文鱼作隊行。","宮女齊来池畔看，傍簾呼喚勿高声。"]', '诗', 'shi', '', NULL, '宮詞 一二二 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53f05781-62fd-43e0-876f-9a9f8c93f0dc', '宮詞 一二三', '宮词 一二三', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["新翻酒令著詞章，侍宴初聞憶却忙。","宣使近臣傳賜本，書家院裏徧抄將。"]', '["新翻酒令著词章，侍宴初闻憶却忙。","宣使近臣傳賜本，书家院裏徧抄將。"]', '诗', 'shi', '', NULL, '宮詞 一二三 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c8a19cf-d1ef-47d7-be4d-5006649d796b', '宮詞 一二四', '宮词 一二四', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["寒食清明小殿旁，綵樓雙夾鬬雞場。","內人對御分明看，先賭紅羅被十牀。"]', '["寒食清明小殿旁，綵楼雙夾鬬雞場。","內人对御分明看，先賭紅羅被十牀。"]', '诗', 'shi', '', NULL, '宮詞 一二四 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22128616-b1ba-46aa-b17b-02249ecef9d4', '宮詞 一二五', '宮词 一二五', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["寢殿門前曉色開，紅泥藥樹間花栽。","君王未起翠簾捲，又發宮人上直來。"]', '["寢殿门前晓色开，紅泥藥樹间花栽。","君王未起翠簾捲，又發宮人上直来。"]', '诗', 'shi', '', NULL, '宮詞 一二五 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85bbac29-be58-405d-97e4-dae0fddfa79c', '宮詞 一二六', '宮词 一二六', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["海棠花發盛春天，游賞無時引御筵。","遶岸結成紅錦帳，暖枝猶拂畫樓船。"]', '["海棠花發盛春天，游賞無时引御筵。","遶岸結成紅錦帳，暖枝猶拂畫楼船。"]', '诗', 'shi', '', NULL, '宮詞 一二六 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fa82f1c-7ac9-454d-a863-5c73633a3fd5', '宮詞 一二七', '宮词 一二七', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["日晚宮人外按回，自牽驄馬出林隈。","御前接得高叉手，射得山雞喜進來。"]', '["日晚宮人外按回，自牽驄马出林隈。","御前接得高叉手，射得山雞喜進来。"]', '诗', 'shi', '', NULL, '宮詞 一二七 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a6a9cb8-9800-432d-8a37-97b19767d698', '宮詞 一二八', '宮词 一二八', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["朱雀門高花外開，毬場空闊淨塵埃。","預排白兔兼蒼狗，等候君王按鶻來。"]', '["朱雀门高花外开，毬場空闊淨塵埃。","預排白兔兼蒼狗，等候君王按鶻来。"]', '诗', 'shi', '', NULL, '宮詞 一二八 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0f3ca8a-4f9f-430f-b15d-82146517e73d', '宮詞 一二九', '宮词 一二九', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["會仙觀內玉清壇，新點宮人作女冠。","每度駕來羞不出，羽衣初著怕人看。"]', '["會仙观內玉清壇，新点宮人作女冠。","每度駕来羞不出，羽衣初著怕人看。"]', '诗', 'shi', '', NULL, '宮詞 一二九 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('722aa853-4e6e-4304-af2b-7f628cbbf497', '宮詞 一百三十', '宮词 一百三十', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["老大初教學道人，鹿皮冠子澹黃裙。","後宮歌舞今拋擲，每日焚香事老君。"]', '["老大初教学道人，鹿皮冠子澹黄裙。","後宮歌舞今拋擲，每日焚香事老君。"]', '诗', 'shi', '', NULL, '宮詞 一百三十 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c414799-51fc-49e5-a302-39a32ba2bd0a', '宮詞 一三一', '宮词 一三一', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["法雲寺裏中元節，又是官家誕降辰。","滿殿香花爭供養，內園先占得鋪陳。"]', '["法云寺裏中元節，又是官家誕降辰。","满殿香花爭供養，內园先占得鋪陳。"]', '诗', 'shi', '', NULL, '宮詞 一三一 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('311ca331-59d1-4ee6-9910-510ccf51f561', '宮詞 一三二', '宮词 一三二', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["金章紫綬選高班，每每東頭近聖顏。","才藝足當恩寵別，只堪供奉一場閑。"]', '["金章紫綬選高班，每每东头近聖顏。","才藝足當恩寵別，只堪供奉一場闲。"]', '诗', 'shi', '', NULL, '宮詞 一三二 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('febcde21-de13-4cec-a730-258cf808fe86', '宮詞 一三三', '宮词 一三三', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["內人深夜學迷藏，徧遶花叢水岸傍。","乘興忽來仙洞裏，大家尋覓一時忙。"]', '["內人深夜学迷藏，徧遶花叢水岸傍。","乘兴忽来仙洞裏，大家尋覓一时忙。"]', '诗', 'shi', '', NULL, '宮詞 一三三 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68ee7d18-e4d6-4c36-84c6-0fe2f91bc4a3', '宮詞 一三四', '宮词 一三四', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["小院珠簾著地垂，院中排比不相知。","羨他鸚鵡能言語，窗裏偷教鸜鵒兒。"]', '["小院珠簾著地垂，院中排比不相知。","羨他鸚鵡能言語，窗裏偷教鸜鵒兒。"]', '诗', 'shi', '', NULL, '宮詞 一三四 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3ffe66d-be07-491e-bdee-8b69424731ef', '宮詞 一三五', '宮词 一三五', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["島樹高低約浪痕，苑中斜日欲黃昏。","樹頭木刻雙飛鶴，蕩起晴空映水門。"]', '["島樹高低約浪痕，苑中斜日欲黄昏。","樹头木刻雙飞鹤，蕩起晴空映水门。"]', '诗', 'shi', '', NULL, '宮詞 一三五 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4df74381-da45-46eb-aa2b-267e94853dae', '宮詞 一三六', '宮词 一三六', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["大臣承寵賜新莊，梔子園東柳岸傍。","今日聖恩親幸到，板橋頭是讀書堂。"]', '["大臣承寵賜新莊，梔子园东柳岸傍。","今日聖恩親幸到，板橋头是读书堂。"]', '诗', 'shi', '', NULL, '宮詞 一三六 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5d7f496-88ef-4e59-a9f8-d8324f7119a4', '宮詞 一三七', '宮词 一三七', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["樹葉初成鳥護窠，石榴花裏笑聲多。","衆中遺却金釵子，拾得從他要贖麽。"]', '["樹葉初成鸟護窠，石榴花裏笑声多。","衆中遺却金釵子，拾得從他要贖麽。"]', '诗', 'shi', '', NULL, '宮詞 一三七 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db234dfa-ac76-4dc9-ac02-c86853b6f7b1', '宮詞 一三八', '宮词 一三八', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["小殿初成粉未乾，貴妃姊妹自來看。","爲逢好日先移入，續向街西索牡丹。"]', '["小殿初成粉未乾，貴妃姊妹自来看。","爲逢好日先移入，續向街西索牡丹。"]', '诗', 'shi', '', NULL, '宮詞 一三八 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3726a9ae-4a2e-4cd2-a43b-e65da5bbb72f', '宮詞 一三九', '宮词 一三九', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["內人相續報花開，准擬君王便看來。","逢著五弦琴繡袋，宜春院裏按歌回。"]', '["內人相續報花开，准擬君王便看来。","逢著五弦琴繡袋，宜春院裏按歌回。"]', '诗', 'shi', '', NULL, '宮詞 一三九 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b7a9a39-8cc3-4652-b78a-6d92d7d6c4dd', '宮詞 一百四十', '宮词 一百四十', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["巡吹慢遍不相和，暗數看誰曲校多。","明日梨花園裏見，先須逐得內家歌。"]', '["巡吹慢遍不相和，暗數看誰曲校多。","明日梨花园裏见，先須逐得內家歌。"]', '诗', 'shi', '', NULL, '宮詞 一百四十 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75813571-6ac8-4cb9-8c66-48543f292c50', '宮詞 一四一', '宮词 一四一', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["黃金合裏盛紅雪，重結香羅四出花。","一一傍邊書勑字，中官送與大臣家。"]', '["黄金合裏盛紅雪，重結香羅四出花。","一一傍邊书勑字，中官送與大臣家。"]', '诗', 'shi', '', NULL, '宮詞 一四一 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac71ba13-9c78-4953-a1b5-d77f1a4c2e88', '宮詞 一四二', '宮词 一四二', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["宮人早起笑相呼，不識堦前掃地夫。","乞與金錢爭借問，外頭還似此間無。"]', '["宮人早起笑相呼，不識堦前掃地夫。","乞與金錢爭借问，外头還似此间無。"]', '诗', 'shi', '', NULL, '宮詞 一四二 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6176fee-0c5a-4df4-9eaa-f145a52e9a0d', '宮詞 一四三', '宮词 一四三', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["小隨阿姊學吹笙，見好君王賜與名。","夜拂玉牀朝把鏡，黃金殿外不教行。"]', '["小隨阿姊学吹笙，见好君王賜與名。","夜拂玉牀朝把镜，黄金殿外不教行。"]', '诗', 'shi', '', NULL, '宮詞 一四三 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('267aa9a6-35dd-4510-99cc-036d6c20bbf1', '宮詞 一四四', '宮词 一四四', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["日高殿裏有香煙，萬歲聲長動九天。","妃子院中初降誕，內人爭乞洗兒錢。"]', '["日高殿裏有香煙，万歲声长动九天。","妃子院中初降誕，內人爭乞洗兒錢。"]', '诗', 'shi', '', NULL, '宮詞 一四四 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2c8c8ad-16fd-42ee-a1e7-2c0e91186a16', '宮詞 一四五', '宮词 一四五', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["宮花不共外花同，正月長生一半紅。","供御櫻桃看守別，直無鴉鵲到園中。"]', '["宮花不共外花同，正月长生一半紅。","供御櫻桃看守別，直無鴉鵲到园中。"]', '诗', 'shi', '', NULL, '宮詞 一四五 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c98e6143-20c2-4d50-8b16-2ff1ddb68919', '宮詞 一四六', '宮词 一四六', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["殿前鋪設兩邊樓，寒食宮人步打毬。","一半走來爭跪拜，上棚先謝得頭籌。"]', '["殿前鋪設兩邊楼，寒食宮人步打毬。","一半走来爭跪拜，上棚先謝得头籌。"]', '诗', 'shi', '', NULL, '宮詞 一四六 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('655b60a7-1bae-4d81-854c-6b617b2be88b', '宮詞 一四七', '宮词 一四七', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["大儀前日暖房來，囑向朝陽乞藥栽。","勑賜一窠紅躑躅，謝恩未了奏花開。"]', '["大儀前日暖房来，囑向朝陽乞藥栽。","勑賜一窠紅躑躅，謝恩未了奏花开。"]', '诗', 'shi', '', NULL, '宮詞 一四七 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5acbdb74-f9e2-4cca-a00f-9f5e8136e842', '宮詞 一四八', '宮词 一四八', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["御前新賜紫羅襦，步步金堦上軟輿。","宮局總來爲喜樂，院中新拜內尚書。"]', '["御前新賜紫羅襦，步步金堦上軟輿。","宮局總来爲喜乐，院中新拜內尚书。"]', '诗', 'shi', '', NULL, '宮詞 一四八 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c87d4b0a-9376-4e6d-8a66-cae076759e8a', '宮詞 一四九', '宮词 一四九', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["鸚鵡誰教轉舌關，內人手裏養來姦。","語多更覺承恩澤，數對君王憶隴山。"]', '["鸚鵡誰教轉舌关，內人手裏養来姦。","語多更覺承恩澤，數对君王憶隴山。"]', '诗', 'shi', '', NULL, '宮詞 一四九 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0720cffd-74d1-4404-8398-627075c794bd', '宮詞 一百五十', '宮词 一百五十', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["分朋閑坐賭櫻桃，收却投壺玉腕勞。","各把沈香雙陸子，局中鬬累阿誰高。"]', '["分朋闲坐賭櫻桃，收却投壺玉腕勞。","各把沈香雙陸子，局中鬬累阿誰高。"]', '诗', 'shi', '', NULL, '宮詞 一百五十 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3b675d5-e03f-499a-9151-546111b7c8be', '宮詞 一五一', '宮词 一五一', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["禁寺紅樓內裏通，笙歌引駕夾城東。","裹頭宮監堂前立，手把牙鞘竹彈弓。"]', '["禁寺紅楼內裏通，笙歌引駕夾城东。","裹头宮監堂前立，手把牙鞘竹彈弓。"]', '诗', 'shi', '', NULL, '宮詞 一五一 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06c487ac-e001-4c52-860c-56db60976ca5', '宮詞 一五二', '宮词 一五二', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["舞來汗溼羅衣徹，樓上人扶下玉梯。","歸到院中重洗面，金花盆裏潑銀泥。"]', '["舞来汗溼羅衣徹，楼上人扶下玉梯。","归到院中重洗面，金花盆裏潑銀泥。"]', '诗', 'shi', '', NULL, '宮詞 一五二 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15e47fc5-310f-4f20-8413-86a19cf62912', '宮詞 一五三', '宮词 一五三', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["宿妝殘粉未明天，總立昭陽花樹邊。","寒食內人長白打，庫中先散與金錢。"]', '["宿妝殘粉未明天，總立昭陽花樹邊。","寒食內人长白打，庫中先散與金錢。"]', '诗', 'shi', '', NULL, '宮詞 一五三 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8327b84-ee0f-415e-8791-e581205d5938', '宮詞 一五四', '宮词 一五四', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["衆中偏得君王笑，偷把金箱筆硯開。","書破紅蠻隔子上，旋推當直美人來。"]', '["衆中偏得君王笑，偷把金箱笔硯开。","书破紅蠻隔子上，旋推當直美人来。"]', '诗', 'shi', '', NULL, '宮詞 一五四 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c9b0abe-c435-401d-997c-841ae1bfefc2', '宮詞 一五五', '宮词 一五五', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["水中芹葉土中花，拾得還將避衆家。","總待別人般數盡，袖中拈出鬱金芽。"]', '["水中芹葉土中花，拾得還將避衆家。","總待別人般數尽，袖中拈出鬱金芽。"]', '诗', 'shi', '', NULL, '宮詞 一五五 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08bdaea3-57d1-4821-ab9f-1b2478897eb9', '宮詞 一五六', '宮词 一五六', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["玉簫改調箏移柱，催換紅羅繡舞筵。","未戴柘枝花帽子，兩行宮監在簾前。"]', '["玉簫改調箏移柱，催換紅羅繡舞筵。","未戴柘枝花帽子，兩行宮監在簾前。"]', '诗', 'shi', '', NULL, '宮詞 一五六 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8a78b67-36f3-4d4e-b52a-28013dfe7677', '宮詞 一五七', '宮词 一五七', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["窗窗戶戶院相當，總有珠簾玳瑁牀。","雖道君王不來宿，帳中長是炷牙香。"]', '["窗窗戶戶院相當，總有珠簾玳瑁牀。","雖道君王不来宿，帳中长是炷牙香。"]', '诗', 'shi', '', NULL, '宮詞 一五七 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5923651a-6a7a-4f09-8b2b-b40ae5d0f5b2', '述國亡詩', '述国亡诗', 'b30425a5-dee5-4bed-8c4b-7102cf22e027', '唐', '["君王城上豎降旗，妾在深宮那得知。","十四萬人齊解甲，寧無一箇是男兒。"]', '["君王城上豎降旗，妾在深宮那得知。","十四万人齊解甲，寧無一箇是男兒。"]', '诗', 'shi', '', NULL, '述國亡詩 花蕊夫人徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86b5a7dd-165a-44d3-b6f3-06b381ddf34e', '新妝詩', '新妝诗', '164c1b0b-17e1-42dd-a67d-075b23277638', '唐', '["啼鳥驚眠罷，房櫳乘曉開。","鳳釵金作縷，鸞鏡玉爲臺。","妝似臨池出，人疑向月來。","自憐終不見，欲去復裴回。"]', '["啼鸟驚眠罷，房櫳乘晓开。","鳳釵金作縷，鸾镜玉爲台。","妝似臨池出，人疑向月来。","自怜終不见，欲去复裴回。"]', '诗', 'shi', '', NULL, '新妝詩 楊容華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99a38e7c-68df-4432-938a-38925d44330c', '贈外', '贈外', '94889ee9-139f-4c92-b064-6bc940671a92', '唐', '["浮萍依綠水，弱蔦寄青松。","與君結大義，移天得所從。","翰林無雙鳥，劒水不分龍。","諧和類琴瑟，堅固同膠漆。","義重恩欲深，夷險貴如一。","本自身不令，積多嬰痛疾。","朝夕倦牀枕，形體恥巾櫛。","遊子倦風塵，從官初解巾。","束裝赴南郢，脂駕出西秦。","比翼終難遂，銜雌苦未因。","徒悲楓岸遠，空對柳園春。","男兒不重舊，丈夫多好新。","新人喜新聘，朝朝臨粉鏡。","兩鴛固無比，雙蛾誰與競。","詎憐愁思人，銜啼嗟薄命。","蕣華不足恃，松枝有餘勁。","所願好九思，勿令虧百行。"]', '["浮萍依綠水，弱蔦寄青松。","與君結大義，移天得所從。","翰林無雙鸟，劒水不分龙。","諧和類琴瑟，堅固同膠漆。","義重恩欲深，夷險貴如一。","本自身不令，積多嬰痛疾。","朝夕倦牀枕，形體恥巾櫛。","游子倦风塵，從官初解巾。","束裝赴南郢，脂駕出西秦。","比翼終难遂，銜雌苦未因。","徒悲楓岸远，空对柳园春。","男兒不重旧，丈夫多好新。","新人喜新聘，朝朝臨粉镜。","兩鴛固無比，雙蛾誰與競。","詎怜愁思人，銜啼嗟薄命。","蕣华不足恃，松枝有餘勁。","所願好九思，勿令虧百行。"]', '诗', 'shi', '', NULL, '贈外 魏氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36de2690-e81e-47f5-8c68-89759bf3c62d', '詠破簾', '詠破簾', '745d400a-2f6a-4947-bb43-6f9375f09bb4', '唐', '["已漏風聲罷，繩持也不禁。","一從經落後，無復有貞心。"]', '["已漏风声罷，繩持也不禁。","一從經落後，無复有貞心。"]', '诗', 'shi', '', NULL, '詠破簾 喬氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('febe0c8d-ba4a-4237-a6b2-60217f730bbb', '送兄', '送兄', '1a4c91c8-676d-4ed3-b792-a80e36b9685e', '唐', '["別路雲初起，離亭葉正飛。","所嗟人異鴈，不作一行歸。"]', '["別路云初起，離亭葉正飞。","所嗟人異鴈，不作一行归。"]', '诗', 'shi', '', NULL, '送兄 七歲女子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56b4df17-a710-403f-833e-bb07e31937cf', '送男左貶詩', '送男左貶诗', 'a9291c94-2185-49db-a10f-6701e3253a0a', '唐', '["他日初投杼，勤王在飲冰。","有辭期不罰，積毀竟相仍。","謫宦今何在，銜冤猶未勝。","天涯分越徼，驛騎速毘陵。","腸斷腹非苦，書傳寫豈能。","淚添江水遠，心劇海雲蒸。","明月珠難識，甘泉賦可稱。","但將忠報主，何懼點青蠅。"]', '["他日初投杼，勤王在饮冰。","有辞期不罰，積毀竟相仍。","謫宦今何在，銜冤猶未勝。","天涯分越徼，驛騎速毘陵。","腸斷腹非苦，书傳寫豈能。","泪添江水远，心劇海云蒸。","明月珠难識，甘泉賦可稱。","但將忠報主，何懼点青蠅。"]', '诗', 'shi', '', NULL, '送男左貶詩 林氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5165fe9c-eb8f-43b4-a41e-30fa96c19d2e', '古興 一', '古兴 一', '64251310-8668-4310-8471-4b7c18feab72', '唐', '["鬱蒸夏將半，暑氣扇飛閣。","驟雨滿空來，當軒卷羅幕。","度雲開夕霽，宇宙何清廓。","明月流素光，輕風換炎鑠。","孤鸞傷對影，寶瑟悲別鶴。","君子去不還，遙心欲何託。"]', '["鬱蒸夏將半，暑氣扇飞閣。","驟雨满空来，當軒卷羅幕。","度云开夕霽，宇宙何清廓。","明月流素光，轻风換炎鑠。","孤鸾傷对影，寶瑟悲別鹤。","君子去不還，遙心欲何託。"]', '诗', 'shi', '', NULL, '古興 一 趙氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e0cd288-b30f-484a-a024-45a61bc07930', '古興 二', '古兴 二', '64251310-8668-4310-8471-4b7c18feab72', '唐', '["金菊延清霜，玉壺多美酒。","良人猶不歸，芳菲豈常有。","不惜芳菲歇，但傷別離久。","含情罷斟酌，凝怨對窗牖。"]', '["金菊延清霜，玉壺多美酒。","良人猶不归，芳菲豈常有。","不惜芳菲歇，但傷別離久。","含情罷斟酌，凝怨对窗牖。"]', '诗', 'shi', '', NULL, '古興 二 趙氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('139c0e4f-780a-4837-9244-fefe2f900967', '古興 三', '古兴 三', '64251310-8668-4310-8471-4b7c18feab72', '唐', '["霽雪舒長野，寒雲半幽谷。","嚴風振枯條，猨啼抱冰木。","所嗟遊宦子，少小荷天祿。","前程未云至，悽愴對車僕。","歲寒成詠歌，日暮棲林樸。","不憚行險道，空悲年運促。"]', '["霽雪舒长野，寒云半幽谷。","嚴风振枯條，猨啼抱冰木。","所嗟游宦子，少小荷天祿。","前程未云至，悽愴对车僕。","歲寒成詠歌，日暮棲林樸。","不憚行險道，空悲年運促。"]', '诗', 'shi', '', NULL, '古興 三 趙氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a598058-c6a3-46f7-a640-f9ae0f7d9d5c', '寄夫', '寄夫', '4829a015-eff6-4ef5-a157-0fe6408187b3', '唐', '["我壻去重湖，臨窗泣血書。","殷勤憑燕翼，寄與薄情夫。"]', '["我壻去重湖，臨窗泣血书。","殷勤憑燕翼，寄與薄情夫。"]', '诗', 'shi', '', NULL, '寄夫 郭紹蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46d3c974-cf0b-406f-9fa2-5e4bed0392c6', '同夫遊秦', '同夫游秦', 'a8557386-0872-4e39-a1f3-5448b8b98b62', '唐', '["路掃飢寒跡，天哀志氣人。","休零離別淚，攜手入西秦。"]', '["路掃飢寒跡，天哀志氣人。","休零離別泪，携手入西秦。"]', '诗', 'shi', '', NULL, '同夫遊秦 王韞秀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f0b25a6-6dd1-4adf-984d-a68fc2e99751', '夫入相寄姨妹', '夫入相寄姨妹', 'a8557386-0872-4e39-a1f3-5448b8b98b62', '唐', '["相國已隨麟閣貴，家風第一右丞詩。","笄年解笑鳴機婦，恥見蘇秦富貴時。"]', '["相国已隨麟閣貴，家风第一右丞诗。","笄年解笑鳴機婦，恥见蘇秦富貴时。"]', '诗', 'shi', '', NULL, '夫入相寄姨妹 王韞秀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30eb9d67-9d1d-41e5-835e-3e3e48a10c14', '喻夫阻客', '喻夫阻客', 'a8557386-0872-4e39-a1f3-5448b8b98b62', '唐', '["楚竹燕歌動畫梁，春蘭重換舞衣裳。","公孫開閣招嘉客，知道浮榮不久長。"]', '["楚竹燕歌动畫梁，春蘭重換舞衣裳。","公孫开閣招嘉客，知道浮榮不久长。"]', '诗', 'shi', '', NULL, '喻夫阻客 王韞秀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3be0d6ff-3bc2-40c5-9ffe-e4c52a36364e', '古意', '古意', '174792af-d9ee-4107-aae2-f60defaf67a2', '唐', '["轆轤曉轉素絲綆，桐聲夜落蒼苔塼。","涓涓吹溜若時雨，濯濯佳蔬非用天。","丈夫不解此中意，抱甕當時徒自賢。"]', '["轆轤晓轉素絲綆，桐声夜落蒼苔塼。","涓涓吹溜若时雨，濯濯佳蔬非用天。","丈夫不解此中意，抱甕當时徒自賢。"]', '诗', 'shi', '', NULL, '古意 張夫人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e786966d-f862-48a9-b4d4-c83986043b2b', '拜新月', '拜新月', '174792af-d9ee-4107-aae2-f60defaf67a2', '唐', '["拜新月，拜月出堂前。","暗魄初籠桂，虛弓未引弦。","拜新月，拜月妝樓上。","鸞鏡始安臺，蛾眉已相向。","拜新月，拜月不勝情，庭花風露清。","月臨人自老，人望月長明。","東家阿母亦拜月，一拜一悲聲斷絕。","昔年拜月逞容輝，如今拜月雙淚垂。","回看衆女拜新月，却憶紅閨年少時。"]', '["拜新月，拜月出堂前。","暗魄初籠桂，虛弓未引弦。","拜新月，拜月妝楼上。","鸾镜始安台，蛾眉已相向。","拜新月，拜月不勝情，庭花风露清。","月臨人自老，人望月长明。","东家阿母亦拜月，一拜一悲声斷絕。","昔年拜月逞容輝，如今拜月雙泪垂。","回看衆女拜新月，却憶紅閨年少时。"]', '诗', 'shi', '', NULL, '拜新月 張夫人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('133ea4a3-3f55-4c7c-ad31-5cd91d95577e', '柳絮', '柳絮', '174792af-d9ee-4107-aae2-f60defaf67a2', '唐', '["靄靄芳春朝，雪絮起青條。","或值花同舞，不因風自飄。","過尊浮綠醑，拂幌綴紅綃。","那用持愁翫，春懷不自聊。"]', '["靄靄芳春朝，雪絮起青條。","或值花同舞，不因风自飄。","過尊浮綠醑，拂幌綴紅綃。","那用持愁翫，春懷不自聊。"]', '诗', 'shi', '', NULL, '柳絮 張夫人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c469973-b3dc-46ad-8b36-7c2f1a87875a', '拾得韋氏花鈿以詩寄贈', '拾得韋氏花鈿以诗寄贈', '174792af-d9ee-4107-aae2-f60defaf67a2', '唐', '["今朝妝閣前，拾得舊花鈿。","粉汚痕猶在，塵侵色尚鮮。","曾經纖手裏，拈向翠眉邊。","能助千金笑，如何忍棄捐。"]', '["今朝妝閣前，拾得旧花鈿。","粉汚痕猶在，塵侵色尚鲜。","曾經纖手裏，拈向翠眉邊。","能助千金笑，如何忍棄捐。"]', '诗', 'shi', '', NULL, '拾得韋氏花鈿以詩寄贈 張夫人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a139233c-3f0e-4c5d-8558-a04a325dfd5b', '誚喜鵲', '誚喜鵲', '174792af-d9ee-4107-aae2-f60defaf67a2', '唐', '["疇昔鴛鴦侶，朱門賀客多。","如今無此事，好去莫相過。"]', '["疇昔鴛鴦侶，朱门賀客多。","如今無此事，好去莫相過。"]', '诗', 'shi', '', NULL, '誚喜鵲 張夫人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffd905fa-df58-43a5-acdf-d5bd8786add6', '句', '句', '174792af-d9ee-4107-aae2-f60defaf67a2', '唐', '["遊蜂乍起驚落墀，黃鳥銜來却上枝。","臨風重回首，掩淚向庭花。","鏡中春色老，枕前秋夜長。"]', '["游蜂乍起驚落墀，黄鸟銜来却上枝。","臨风重回首，掩泪向庭花。","镜中春色老，枕前秋夜长。"]', '诗', 'shi', '', NULL, '句 張夫人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c24d6aa4-8171-4821-b560-19d4889e5995', '書石壁', '书石壁', '9fecff0d-d57b-4571-b112-e7fdc2f8c656', '唐', '["何事潘郎戀別筵，歡情未斷妾心懸。","汰王灘下相思處，猨叫山山月滿船。"]', '["何事潘郎戀別筵，歡情未斷妾心懸。","汰王灘下相思处，猨叫山山月满船。"]', '诗', 'shi', '', NULL, '書石壁 王氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd5d2bee-7b17-4b7f-af2b-f2e1840b3144', '荅微之', '荅微之', '97acc8db-4cfe-4ccb-a66f-611dcd6dcf83', '唐', '["侯門初擁節，御苑柳絲新。","不是悲殊命，唯愁別近親。","黃鶯遷古木，朱履從清塵。","想到千山外，滄江正暮春。"]', '["侯门初擁節，御苑柳絲新。","不是悲殊命，唯愁別近親。","黄鶯遷古木，朱履從清塵。","想到千山外，滄江正暮春。"]', '诗', 'shi', '', NULL, '荅微之 裴淑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaf7bb38-5886-4d7a-8e0f-b569a2a91b36', '夫下第', '夫下第', '64251310-8668-4310-8471-4b7c18feab72', '唐', '["良人的的有奇才，何事年年被放回。","如今妾面羞君面，君若來時近夜來。"]', '["良人的的有奇才，何事年年被放回。","如今妾面羞君面，君若来时近夜来。"]', '诗', 'shi', '', NULL, '夫下第 趙氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9edb62b-8ab0-468e-bcae-dee78ce204db', '雜言寄杜羔', '杂言寄杜羔', '64251310-8668-4310-8471-4b7c18feab72', '唐', '["君從淮海遊，再過蘭杜秋。","歸來未須臾，又欲向梁州。","梁州秦嶺西，棧道與雲齊。","羌蠻萬餘落，矛戟自高低。","已念寡儔侶，復慮勞攀躋。","丈夫重志氣，兒女空悲啼。","臨邛滯遊地，肯顧濁水泥。","人生賦命有厚薄，君但遨遊我寂寞。"]', '["君從淮海游，再過蘭杜秋。","归来未須臾，又欲向梁州。","梁州秦嶺西，棧道與云齊。","羌蠻万餘落，矛戟自高低。","已念寡儔侶，复慮勞攀躋。","丈夫重志氣，兒女空悲啼。","臨邛滯游地，肯顧濁水泥。","人生賦命有厚薄，君但遨游我寂寞。"]', '诗', 'shi', '', NULL, '雜言寄杜羔 趙氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd00995d-e299-4636-aaef-1e769b0e384b', '聞夫杜羔登第', '闻夫杜羔登第', '64251310-8668-4310-8471-4b7c18feab72', '唐', '["長安此去無多地，鬱鬱蔥蔥佳氣浮。","良人得意正年少，今夜醉眠何處樓。"]', '["长安此去無多地，鬱鬱蔥蔥佳氣浮。","良人得意正年少，今夜醉眠何处楼。"]', '诗', 'shi', '', NULL, '聞夫杜羔登第 趙氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9967e41d-2fdc-4b5c-86f3-87909843bee6', '雜言', '杂言', '64251310-8668-4310-8471-4b7c18feab72', '唐', '["上林園中青青桂，折得一枝好夫壻。","杏花如雪柳垂絲，春風蕩颺不同枝。"]', '["上林园中青青桂，折得一枝好夫壻。","杏花如雪柳垂絲，春风蕩颺不同枝。"]', '诗', 'shi', '', NULL, '雜言 趙氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23f88ea8-4327-4059-8981-cda65ecb2099', '寄夫 一', '寄夫 一', 'f4b2173e-8766-4322-a205-27ec7d18cfd3', '唐', '["久無音信到羅幃，路遠迢迢遣問誰。","聞君折得東堂桂，折罷那能不暫歸。"]', '["久無音信到羅幃，路远迢迢遣问誰。","闻君折得东堂桂，折罷那能不暫归。"]', '诗', 'shi', '', NULL, '寄夫 一 張氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c2792ef-c3af-4ebe-8b1f-e9134da8680b', '寄夫 二', '寄夫 二', 'f4b2173e-8766-4322-a205-27ec7d18cfd3', '唐', '["驛使今朝過五湖，殷勤爲我報狂夫。","從來誇有龍泉劒，試割相思得斷無。"]', '["驛使今朝過五湖，殷勤爲我報狂夫。","從来誇有龙泉劒，試割相思得斷無。"]', '诗', 'shi', '', NULL, '寄夫 二 張氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc2bfccd-37f6-4a0b-8ded-da844d9ed7b6', '贈鄭女郎', '贈鄭女郎', 'cfaa302f-2d2b-48e5-8d2c-78efbe56ae2f', '唐', '["豔陽灼灼河洛神，珠簾繡戶青樓春。","能彈箜篌弄纖指，愁殺門前少年子。","笑開一面紅粉妝，東園幾樹桃花死。","朝理曲，暮理曲，獨坐窗前一片玉。","行也嬌，坐也嬌，見之令人魂魄銷。","堂前錦褥紅地鑪，綠沈香榼傾屠蘇。","解佩時時歇歌管，芙蓉帳裏蘭麝滿。","晚起羅衣香不斷，滅燭每嫌秋夜短。"]', '["豔陽灼灼河洛神，珠簾繡戶青楼春。","能彈箜篌弄纖指，愁殺门前少年子。","笑开一面紅粉妝，东园幾樹桃花死。","朝理曲，暮理曲，独坐窗前一片玉。","行也嬌，坐也嬌，见之令人魂魄銷。","堂前錦褥紅地鑪，綠沈香榼傾屠蘇。","解佩时时歇歌管，芙蓉帳裏蘭麝满。","晚起羅衣香不斷，滅燭每嫌秋夜短。"]', '诗', 'shi', '', NULL, '贈鄭女郎 薛馧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72c62b15-4e1c-44bd-bb61-e005b0ed0114', '古意', '古意', 'cfaa302f-2d2b-48e5-8d2c-78efbe56ae2f', '唐', '["昨夜巫山中，失却陽臺女。","朝來香閣裏，獨伴楚王語。"]', '["昨夜巫山中，失却陽台女。","朝来香閣裏，独伴楚王語。"]', '诗', 'shi', '', NULL, '古意 薛馧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a403a234-449e-4e71-bc97-3e589db2feab', '贈故人', '贈故人', 'cfaa302f-2d2b-48e5-8d2c-78efbe56ae2f', '唐', '["昔別容如玉，今來鬢若絲。","淚痕應共見，腸斷阿誰知。"]', '["昔別容如玉，今来鬢若絲。","泪痕應共见，腸斷阿誰知。"]', '诗', 'shi', '', NULL, '贈故人 薛馧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6102ecfa-9b06-43e2-a6b0-d2061fae8521', '句', '句', 'cfaa302f-2d2b-48e5-8d2c-78efbe56ae2f', '唐', '["寂寞相思處，雕梁落燕泥。"]', '["寂寞相思处，雕梁落燕泥。"]', '诗', 'shi', '', NULL, '句 薛馧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28b4c653-7b79-44d0-9ee3-d51a6c1b12ca', '題奉慈寺', '題奉慈寺', 'ba0dfd2e-4575-4888-8766-58063117bdc3', '唐', '["日月金輪動，旃檀碧樹秋。","塔分鴻鴈翅，鐘挂鳳凰樓。"]', '["日月金輪动，旃檀碧樹秋。","塔分鴻鴈翅，鐘挂鳳凰楼。"]', '诗', 'shi', '', NULL, '題奉慈寺 楊德麟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e48dd05-26ac-4058-a8e3-96f1814b880e', '述懷', '述懷', 'e87988e7-d70d-4669-9103-a4126f76541c', '唐', '["不怨盧郎年紀大，不怨盧郎官職卑。","自恨妾身生較晚，不及盧郎年少時。"]', '["不怨盧郎年紀大，不怨盧郎官職卑。","自恨妾身生較晚，不及盧郎年少时。"]', '诗', 'shi', '', NULL, '述懷 崔氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c84fc5e4-d883-4858-a2a9-0feac1154bab', '寄夫', '寄夫', '4046ad53-bf20-4738-aa1c-35cbe353112e', '唐', '["夫戍邊關妾在吳，西風吹妾妾憂夫。","一行書信千行淚，寒到君邊衣到無。"]', '["夫戍邊关妾在吳，西风吹妾妾憂夫。","一行书信千行泪，寒到君邊衣到無。"]', '诗', 'shi', '', NULL, '寄夫 陳玉蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('682d9a63-2f12-41dc-a146-257f67f17984', '寫真寄夫', '寫真寄夫', 'd506fdbb-2c12-461a-8801-56fc94b1f557', '唐', '["欲下丹青筆，先拈寶鏡寒。","已經顏索寞，漸覺鬢凋殘。","淚眼描將易，愁腸寫出難。","恐君渾忘却，時展畫圖看。"]', '["欲下丹青笔，先拈寶镜寒。","已經顏索寞，漸覺鬢凋殘。","泪眼描將易，愁腸寫出难。","恐君渾忘却，时展畫圖看。"]', '诗', 'shi', '', NULL, '寫真寄夫 薛媛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a44ca13-827a-4b80-9192-6b0e6dcf3846', '聞琴', '闻琴', '8b634e6f-fe34-439f-bec7-e5f5ef408795', '唐', '["玉指朱弦軋復清，湘妃愁怨最難聽。","初疑颯颯涼風勁，又似蕭蕭暮雨零。","近比流泉來碧嶂，遠如玄鶴下青冥。","夜深彈罷堪惆悵，露溼叢蘭月滿庭。"]', '["玉指朱弦軋复清，湘妃愁怨最难听。","初疑颯颯涼风勁，又似蕭蕭暮雨零。","近比流泉来碧嶂，远如玄鹤下青冥。","夜深彈罷堪惆悵，露溼叢蘭月满庭。"]', '诗', 'shi', '', NULL, '聞琴 孫氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6dc6340-5ae0-4a87-a04c-cc0074982856', '白蠟燭詩', '白蠟燭诗', '8b634e6f-fe34-439f-bec7-e5f5ef408795', '唐', '["景勝銀釭香比蘭，一條白玉偪人寒。","他時紫禁春風夜，醉草天書仔細看。"]', '["景勝銀釭香比蘭，一條白玉偪人寒。","他时紫禁春风夜，醉草天书仔細看。"]', '诗', 'shi', '', NULL, '白蠟燭詩 孫氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58219b41-0a15-4288-a2e2-1ebf982ec88b', '謝人送酒', '謝人送酒', '8b634e6f-fe34-439f-bec7-e5f5ef408795', '唐', '["謝將清酒寄愁人，澄澈甘香氣味真。","好是綠窗風月夜，一杯搖蕩滿懷春。"]', '["謝將清酒寄愁人，澄澈甘香氣味真。","好是綠窗风月夜，一杯搖蕩满懷春。"]', '诗', 'shi', '', NULL, '謝人送酒 孫氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('363fd601-bcab-4f51-a099-a7ae9b4cd96c', '詩', '诗', 'dfc17449-01dd-458e-a0ed-5b3d5f07a258', '唐', '["危冠廣袖楚宮妝，獨步閑庭逐夜涼。","自把玉簪敲砌竹，清歌一曲月如霜。"]', '["危冠廣袖楚宮妝，独步闲庭逐夜涼。","自把玉簪敲砌竹，清歌一曲月如霜。"]', '诗', 'shi', '', NULL, '詩 張立本女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf21db2d-a170-4b69-87bd-1643742ed924', '繡龜形詩', '繡龟形诗', 'bdbcbd11-e508-48d0-9b9b-274115fbbbe0', '唐', '["暌離已是十秋強，對鏡那堪重理妝。","聞鴈幾迴修尺素，見霜先爲製衣裳。","開箱疊練先垂淚，拂杵調砧更斷腸。","繡作龜形獻天子，願教征客早還鄉。"]', '["暌離已是十秋強，对镜那堪重理妝。","闻鴈幾迴修尺素，见霜先爲製衣裳。","开箱叠練先垂泪，拂杵調砧更斷腸。","繡作龟形獻天子，願教征客早還乡。"]', '诗', 'shi', '', NULL, '繡龜形詩 侯氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d3fe8f4-5d2e-47c8-a3ab-5541f2824fe0', '感夫詩', '感夫诗', '9f2e408d-fd06-41f8-9335-9e004d3d3bc8', '唐', '["當時心事已相關，雨散雲飛一餉間。","便是孤帆從此去，不堪重上望夫山。"]', '["當时心事已相关，雨散云飞一餉间。","便是孤帆從此去，不堪重上望夫山。"]', '诗', 'shi', '', NULL, '感夫詩 慎氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52470403-70a0-4488-bf26-4ce55173e96a', '謠', '謠', 'fdb68db0-3adf-4022-8dab-c74adc397ad7', '唐', '["化雲心兮思淑貞，洞寂滅兮不見人。","瑤草芳兮思芬蒀，將奈何兮青春。"]', '["化云心兮思淑貞，洞寂滅兮不见人。","瑤草芳兮思芬蒀，將奈何兮青春。"]', '诗', 'shi', '', NULL, '謠 薛瑤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65bc9a75-4cee-4066-8037-23cd7f988f6e', '題唐安寺閣壁', '題唐安寺閣壁', 'd8f8fb66-bb37-4cb1-82bc-071fcb8d5bc5', '唐', '["春來引步暫尋遊，愁見風光倚寺樓。","正好開懷對煙月，雙眉不覺自如鉤。"]', '["春来引步暫尋游，愁见风光倚寺楼。","正好开懷对煙月，雙眉不覺自如鉤。"]', '诗', 'shi', '', NULL, '題唐安寺閣壁 王霞卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42c45940-942a-4c90-a13e-32ed4430d218', '荅鄭殷彝', '荅鄭殷彝', 'd8f8fb66-bb37-4cb1-82bc-071fcb8d5bc5', '唐', '["君是煙霄折桂身，聖朝方切用儒珍。","正堪西上文場戰，空向途中泥婦人。"]', '["君是煙霄折桂身，聖朝方切用儒珍。","正堪西上文場戰，空向途中泥婦人。"]', '诗', 'shi', '', NULL, '荅鄭殷彝 王霞卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3e0ac13-0145-43b5-b587-fa2a9e714f35', '喜盧郎及第', '喜盧郎及第', '03e38c23-5fbc-4e2e-beb4-e5a402091ce9', '唐', '["曉妝初罷眼初瞤，小玉驚人踏破帬。","手把紅箋書一紙，上頭名字有郎君。"]', '["晓妝初罷眼初瞤，小玉驚人踏破帬。","手把紅箋书一紙，上头名字有郎君。"]', '诗', 'shi', '', NULL, '喜盧郎及第 竇梁賓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6980f51a-151a-4502-a77b-93394915a5bd', '雨中看牡丹', '雨中看牡丹', '03e38c23-5fbc-4e2e-beb4-e5a402091ce9', '唐', '["東風未放曉泥乾，紅藥花開不奈寒。","待得天晴花已老，不如攜手雨中看。"]', '["东风未放晓泥乾，紅藥花开不奈寒。","待得天晴花已老，不如携手雨中看。"]', '诗', 'shi', '', NULL, '雨中看牡丹 竇梁賓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa3898fa-cc2a-4e9a-8535-911cf2be322e', '書桐葉', '书桐葉', 'c2ceab02-9802-4d50-9835-cec2dbe2523b', '唐', '["拭翠斂蛾眉，鬱鬱心中事。","搦管下庭除，書成相思字。","此字不書石，此字不書紙。","書在桐葉上，願逐秋風起。","天下有心人，盡解相思死。","天下負心人，不識相思字。","有心與負心，不知落何地。"]', '["拭翠斂蛾眉，鬱鬱心中事。","搦管下庭除，书成相思字。","此字不书石，此字不书紙。","书在桐葉上，願逐秋风起。","天下有心人，尽解相思死。","天下負心人，不識相思字。","有心與負心，不知落何地。"]', '诗', 'shi', '', NULL, '書桐葉 任氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59967f24-5e84-4ceb-8cf3-f57ea305919d', '下獄貢詩', '下獄貢诗', 'bc91e0d6-ea7b-4a8d-a186-1d5fbbaaabcd', '唐', '["偶辭幽隱在臨邛，行止堅貞比澗松。","何事政清如水鏡，絆他野鶴在深籠。"]', '["偶辞幽隐在臨邛，行止堅貞比澗松。","何事政清如水镜，絆他野鹤在深籠。"]', '诗', 'shi', '', NULL, '下獄貢詩 黃崇嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f3490a4-e938-481e-8a93-c415b7ccbc20', '辭蜀相妻女詩', '辞蜀相妻女诗', 'bc91e0d6-ea7b-4a8d-a186-1d5fbbaaabcd', '唐', '["一辭拾翠碧江湄，貧守蓬茅但賦詩。","自服藍衫居郡掾，永拋鸞鏡畫蛾眉。","立身卓爾青松操，挺志鏗然白璧姿。","幕府若容爲坦腹，願天速變作男兒。"]', '["一辞拾翠碧江湄，貧守蓬茅但賦诗。","自服藍衫居郡掾，永拋鸾镜畫蛾眉。","立身卓爾青松操，挺志鏗然白璧姿。","幕府若容爲坦腹，願天速变作男兒。"]', '诗', 'shi', '', NULL, '辭蜀相妻女詩 黃崇嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a45ceb95-2a3e-4844-a36f-9e46ea2e3b2f', '荅諸姊妹戒飲', '荅諸姊妹戒饮', '19dfd75f-2763-4030-beee-85439a298564', '唐', '["平生偏好酒，勞爾勸吾餐。","但得杯中滿，時光度不難。"]', '["平生偏好酒，勞爾勸吾餐。","但得杯中满，时光度不难。"]', '诗', 'shi', '', NULL, '荅諸姊妹戒飲 蔣氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02ef842b-bb93-4a59-8960-3dde22d8d6b2', '書壁', '书壁', 'ed63bc7f-28cb-4f38-821e-42ee2293994f', '唐', '["愛妾不愛子，爲問此何理。","棄官更棄妻，人情寧可已。","永訣泗之濱，遺言空在耳。","三載無朝昏，孤幃淚如洗。","婦人義從夫，一節誓生死。","江鄉感殘春，腸斷晚煙起。","西望太華峰，不知幾千里。"]', '["愛妾不愛子，爲问此何理。","棄官更棄妻，人情寧可已。","永訣泗之濱，遺言空在耳。","三載無朝昏，孤幃泪如洗。","婦人義從夫，一節誓生死。","江乡感殘春，腸斷晚煙起。","西望太华峰，不知幾千里。"]', '诗', 'shi', '', NULL, '書壁 周仲美 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('745a9b04-89e7-4b5d-bf35-d328d2403ecc', '溪口雲', '溪口云', 'ee311e74-3cc3-45e2-b162-bec8242cc2d0', '唐', '["溶溶溪口雲，纔向溪中吐。","不復歸溪中，還作溪中雨。"]', '["溶溶溪口云，纔向溪中吐。","不复归溪中，還作溪中雨。"]', '诗', 'shi', '', NULL, '溪口雲 張文姬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ded41575-fb8a-4f5b-99d6-3c339fd75dc6', '池上竹', '池上竹', 'ee311e74-3cc3-45e2-b162-bec8242cc2d0', '唐', '["此君臨此池，枝低水相近。","碧色綠波中，日日流不盡。"]', '["此君臨此池，枝低水相近。","碧色綠波中，日日流不尽。"]', '诗', 'shi', '', NULL, '池上竹 張文姬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba2fd465-d362-495b-a27e-b01e371d8470', '沙上鷺', '沙上鷺', 'ee311e74-3cc3-45e2-b162-bec8242cc2d0', '唐', '["沙頭一水禽，鼓翼揚清音。","只待高風便，非無雲漢心。"]', '["沙头一水禽，鼓翼揚清音。","只待高风便，非無云漢心。"]', '诗', 'shi', '', NULL, '沙上鷺 張文姬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e614ecf9-9216-4c20-9e30-b2215fcac6cd', '雙槿樹', '雙槿樹', 'ee311e74-3cc3-45e2-b162-bec8242cc2d0', '唐', '["綠影競扶疎，紅姿相照灼。","不學桃李花，亂向春風落。"]', '["綠影競扶疎，紅姿相照灼。","不学桃李花，亂向春风落。"]', '诗', 'shi', '', NULL, '雙槿樹 張文姬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('426e4caa-937e-46b9-ba0b-10f149c2ba3b', '獄中書情上使君', '獄中书情上使君', '97a52ae6-a057-41bb-8541-a5b8d2412e3b', '唐', '["妾家本住鄱陽曲，一片貞心比孤竹。","當年二八盛容儀，紅牋草隸恰如飛。","盡日閑窗刺繡坐，有時極浦採蓮歸。","誰道居貧守都邑，幽閨寂寞無人識。","海燕朝歸衾枕寒，山花夜落階墀溼。","強暴之男何所爲，手持白刃向簾幃。","一命任從刀下死，千金豈受暗中欺。","我心匪石情難轉，志奪秋霜意不移。","血濺羅衣終不恨，瘡黏錦袖亦何辭。","縣僚曾未知情緒，即便教人縶囹圄。","朱脣滴瀝獨銜冤，玉筯闌干歎非所。","十月寒更堪思人，一聞擊柝一傷神。","高髻不梳雲已散，蛾眉罷埽月仍新。","三尺嚴章難可越，百年心事向誰說。","但看洗雪出圜扉，始信白圭無玷缺。"]', '["妾家本住鄱陽曲，一片貞心比孤竹。","當年二八盛容儀，紅牋草隸恰如飞。","尽日闲窗刺繡坐，有时極浦採蓮归。","誰道居貧守都邑，幽閨寂寞無人識。","海燕朝归衾枕寒，山花夜落階墀溼。","強暴之男何所爲，手持白刃向簾幃。","一命任從刀下死，千金豈受暗中欺。","我心匪石情难轉，志奪秋霜意不移。","血濺羅衣終不恨，瘡黏錦袖亦何辞。","縣僚曾未知情緒，即便教人縶囹圄。","朱脣滴瀝独銜冤，玉筯闌干歎非所。","十月寒更堪思人，一闻擊柝一傷神。","高髻不梳云已散，蛾眉罷埽月仍新。","三尺嚴章难可越，百年心事向誰说。","但看洗雪出圜扉，始信白圭無玷缺。"]', '诗', 'shi', '', NULL, '獄中書情上使君 程長文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f90106b9-fcd0-431c-99f5-47f7b728524b', '銅雀臺怨', '銅雀台怨', '97a52ae6-a057-41bb-8541-a5b8d2412e3b', '唐', '["君王去後行人絕，簫箏不響歌喉咽。","雄劒無威光彩沈，寶琴零落金星滅。","玉階寂寞墜秋露，月照當時歌舞處。","當時歌舞人不迴，化爲今日西陵灰。"]', '["君王去後行人絕，簫箏不响歌喉咽。","雄劒無威光彩沈，寶琴零落金星滅。","玉階寂寞墜秋露，月照當时歌舞处。","當时歌舞人不迴，化爲今日西陵灰。"]', '诗', 'shi', '', NULL, '銅雀臺怨 程長文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e800e312-b8d9-4708-ae5b-00d2aa31be4c', '春閨怨', '春閨怨', '97a52ae6-a057-41bb-8541-a5b8d2412e3b', '唐', '["[綺]陌香飄柳如線，時光瞬息如流電。","良人何處事功名，十載相思不相見。"]', '["[綺]陌香飄柳如線，时光瞬息如流電。","良人何处事功名，十載相思不相见。"]', '诗', 'shi', '', NULL, '春閨怨 程長文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c1c52e6-2e37-4d73-8a28-b3eb6b6bfbc0', '荅韓翃', '荅韓翃', '768a19eb-4eda-49ad-b96f-efae5d0bdcbb', '唐', '["楊柳枝，芳菲節，可恨年年贈離別。","一葉隨風忽報秋，縱使君來豈堪折。"]', '["楊柳枝，芳菲節，可恨年年贈離別。","一葉隨风忽報秋，縱使君来豈堪折。"]', '诗', 'shi', '', NULL, '荅韓翃 柳氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7196d94-63d7-4fe4-aef6-6a8a65d0a5d0', '歸李江州後寄別王氏', '归李江州後寄別王氏', 'af25b069-0e64-4bf8-800f-e3118e5fe587', '唐', '["魚鴈回時寫報音，難憑剉蘖數年心。","雖然情斷沙吒後，爭奈平生怨恨深。"]', '["鱼鴈回时寫報音，难憑剉蘖數年心。","雖然情斷沙吒後，爭奈平生怨恨深。"]', '诗', 'shi', '', NULL, '歸李江州後寄別王氏 程洛賓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43897f0e-e5bc-499e-b38a-f13fa2bdd7b3', '憶崔生', '憶崔生', '4bb4596a-c1b1-4362-8ca8-0017ed060879', '唐', '["深洞鶯啼恨阮郎，偷來花下解珠璫。","碧雲飄斷音書絕，空倚玉簫愁鳳皇。"]', '["深洞鶯啼恨阮郎，偷来花下解珠璫。","碧云飄斷音书絕，空倚玉簫愁鳳皇。"]', '诗', 'shi', '', NULL, '憶崔生 紅綃妓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f4006c4-d20f-452e-b5ce-9842d8b77e31', '寄文茂', '寄文茂', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["花箋製葉寄郎邊，的的尋魚爲妾傳。","幷蒂已看靈鵲報，倩郎早覓買花船。"]', '["花箋製葉寄郎邊，的的尋鱼爲妾傳。","幷蒂已看靈鵲報，倩郎早覓買花船。"]', '诗', 'shi', '', NULL, '寄文茂 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38d5772d-c185-4c22-a232-caddf97c2ecc', '秋日再寄', '秋日再寄', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["珍簟生涼夜漏餘，夢中恍惚覺來初。","魂離不得空成病，面見無由浪寄書。","窗外江村鐘響絕，枕邊梧葉雨聲疎。","此時最是思君處，腸斷寒猨定不如。"]', '["珍簟生涼夜漏餘，梦中恍惚覺来初。","魂離不得空成病，面见無由浪寄书。","窗外江村鐘响絕，枕邊梧葉雨声疎。","此时最是思君处，腸斷寒猨定不如。"]', '诗', 'shi', '', NULL, '秋日再寄 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1236566a-1088-490a-91e9-16760e6bb973', '春日送夫之長安', '春日送夫之长安', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["思君遠別妾心愁，踏翠江邊送畫舟。","欲待相看遲此別，只憂紅日向西流。"]', '["思君远別妾心愁，踏翠江邊送畫舟。","欲待相看遲此別，只憂紅日向西流。"]', '诗', 'shi', '', NULL, '春日送夫之長安 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6566189d-711d-4771-a6c0-d265def3635d', '雨中憶夫 一', '雨中憶夫 一', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["窗前細雨日啾啾，妾在閨中獨自愁。","何事玉郎久離別，忘憂總對豈忘憂。"]', '["窗前細雨日啾啾，妾在閨中独自愁。","何事玉郎久離別，忘憂總对豈忘憂。"]', '诗', 'shi', '', NULL, '雨中憶夫 一 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('911f631b-dcb2-4a6a-8890-9ae0fdf31057', '雨中憶夫 二', '雨中憶夫 二', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["春風送雨過窗東，忽憶良人在客中。","安得妾身今似雨，也隨風去與郎同。"]', '["春风送雨過窗东，忽憶良人在客中。","安得妾身今似雨，也隨风去與郎同。"]', '诗', 'shi', '', NULL, '雨中憶夫 二 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d39d972-81c8-40ce-a3d2-9fb82a1daa0b', '子夜歌十八首 一', '子夜歌十八首 一', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["儂既剪雲鬟，郎亦分絲髮。","覓向無人處，綰作同心結。"]', '["儂既剪云鬟，郎亦分絲髮。","覓向無人处，綰作同心結。"]', '诗', 'shi', '', NULL, '子夜歌十八首 一 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cee37ed2-dbe3-411d-b652-d274e05b7702', '子夜歌十八首 二', '子夜歌十八首 二', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["夜夜不成寐，擁被啼終夕。","郎不信儂時，但看枕上跡。"]', '["夜夜不成寐，擁被啼終夕。","郎不信儂时，但看枕上跡。"]', '诗', 'shi', '', NULL, '子夜歌十八首 二 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64df80be-7000-42bb-9c86-decf28286053', '子夜歌十八首 三', '子夜歌十八首 三', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["何時得成匹，離恨不復牽。","金針刺菡萏，夜夜得見蓮。"]', '["何时得成匹，離恨不复牽。","金針刺菡萏，夜夜得见蓮。"]', '诗', 'shi', '', NULL, '子夜歌十八首 三 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82e22c1d-77a5-4561-9dba-7005a5c737c2', '子夜歌十八首 四', '子夜歌十八首 四', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["相逢逐涼候，黃花忽復香。","顰眉臘月露，愁殺未成霜。"]', '["相逢逐涼候，黄花忽复香。","顰眉臘月露，愁殺未成霜。"]', '诗', 'shi', '', NULL, '子夜歌十八首 四 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c174ebbf-0dc4-44c4-8348-6a41a4d13262', '子夜歌十八首 五', '子夜歌十八首 五', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["明窗弄玉指，指甲如水晶。","翦之特寄郎，聊當攜手行。"]', '["明窗弄玉指，指甲如水晶。","翦之特寄郎，聊當携手行。"]', '诗', 'shi', '', NULL, '子夜歌十八首 五 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc9e96e8-466a-4de7-b71b-1646656baa78', '子夜歌十八首 六', '子夜歌十八首 六', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["寄語閨中娘，顏色不常好。","含笑對棘實，歡娛須是棗。"]', '["寄語閨中娘，顏色不常好。","含笑对棘實，歡娛須是棗。"]', '诗', 'shi', '', NULL, '子夜歌十八首 六 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b05e9e06-1e7a-4bfc-af7c-0fb9205563df', '子夜歌十八首 七', '子夜歌十八首 七', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["良會終有時，勸郎莫得怒。","薑蘖畏春蠶，要綿須辛苦。"]', '["良會終有时，勸郎莫得怒。","薑蘖畏春蠶，要綿須辛苦。"]', '诗', 'shi', '', NULL, '子夜歌十八首 七 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53ff9de3-f372-4951-b7b1-0516bc449c9b', '子夜歌十八首 八', '子夜歌十八首 八', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["醉夢幸逢郎，無奈烏啞啞。","中山如有酒，敢借千金價。"]', '["醉梦幸逢郎，無奈烏啞啞。","中山如有酒，敢借千金價。"]', '诗', 'shi', '', NULL, '子夜歌十八首 八 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd25c1b1-34ef-4ef7-be11-dea18d41bc53', '子夜歌十八首 九', '子夜歌十八首 九', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["信使無虛日，玉醞寄盈觥。","一年一日雨，底事太多晴。"]', '["信使無虛日，玉醞寄盈觥。","一年一日雨，底事太多晴。"]', '诗', 'shi', '', NULL, '子夜歌十八首 九 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5cc3885-ba50-4465-9665-6b220aad4ea4', '子夜歌十八首 十', '子夜歌十八首 十', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["繡房擬會郎，四窗日離離。","手自施屏障，恐有女伴窺。"]', '["繡房擬會郎，四窗日離離。","手自施屏障，恐有女伴窺。"]', '诗', 'shi', '', NULL, '子夜歌十八首 十 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9109c348-3946-40cd-a55a-229f94d9c690', '子夜歌十八首 十一', '子夜歌十八首 十一', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["相思百餘日，相見苦無期。","褰裳摘藕花，要蓮敢恨池。"]', '["相思百餘日，相见苦無期。","褰裳摘藕花，要蓮敢恨池。"]', '诗', 'shi', '', NULL, '子夜歌十八首 十一 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26ce7874-d932-4474-b787-d96bc75fddd7', '子夜歌十八首 十二', '子夜歌十八首 十二', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["金盆盥素手，焚香誦普門。","來生何所願，與郎爲一身。"]', '["金盆盥素手，焚香誦普门。","来生何所願，與郎爲一身。"]', '诗', 'shi', '', NULL, '子夜歌十八首 十二 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46bdf6bb-df79-4811-bd72-d49e5a54d514', '子夜歌十八首 十三', '子夜歌十八首 十三', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["花池多芳水，玉杯挹贈郎。","避人藏袖裏，溼却素羅裳。"]', '["花池多芳水，玉杯挹贈郎。","避人藏袖裏，溼却素羅裳。"]', '诗', 'shi', '', NULL, '子夜歌十八首 十三 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e17e862d-214b-4ebd-ae94-a96b4afc6b25', '子夜歌十八首 十四', '子夜歌十八首 十四', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["感郎金鍼贈，欲報物俱輕。","一雙連素縷，與郎聊定情。"]', '["感郎金鍼贈，欲報物俱轻。","一雙連素縷，與郎聊定情。"]', '诗', 'shi', '', NULL, '子夜歌十八首 十四 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14407943-9c68-4823-902d-516291d26e7d', '子夜歌十八首 十五', '子夜歌十八首 十五', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["寒風響枯木，通夕不得臥。","早起遣問郎，昨宵何以過。"]', '["寒风响枯木，通夕不得臥。","早起遣问郎，昨宵何以過。"]', '诗', 'shi', '', NULL, '子夜歌十八首 十五 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b8a76d2-d017-4cda-8f8a-3021c48c378a', '子夜歌十八首 十六', '子夜歌十八首 十六', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["得郎日嗣音，令人不可覩。","熊膽磨作墨，書來字字苦。"]', '["得郎日嗣音，令人不可覩。","熊膽磨作墨，书来字字苦。"]', '诗', 'shi', '', NULL, '子夜歌十八首 十六 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9587780-178c-4756-8251-9af0eb6cc636', '子夜歌十八首 十七', '子夜歌十八首 十七', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["輕巾手自製，顏色爛含桃。","先懷儂袖裏，然後約郎腰。"]', '["轻巾手自製，顏色爛含桃。","先懷儂袖裏，然後約郎腰。"]', '诗', 'shi', '', NULL, '子夜歌十八首 十七 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f146ab5-f1a2-4b9e-9e1d-04c7486bfdfd', '子夜歌十八首 十八', '子夜歌十八首 十八', '6ed6375f-97b1-4ce2-8b37-eb9b8136a326', '唐', '["儂贈綠絲衣，郎遺玉鉤子。","即欲繫儂心，儂思著郎體。"]', '["儂贈綠絲衣，郎遺玉鉤子。","即欲繫儂心，儂思著郎體。"]', '诗', 'shi', '', NULL, '子夜歌十八首 十八 晁采 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07bdeb64-f528-4187-9b4c-525f1d5e6e5b', '荅張生', '荅張生', '5b6f838e-d5d7-4a03-b0f9-1c0d17aaaa2d', '唐', '["待月西廂下，迎風戶半開。","拂牆花影動，疑是玉人來。"]', '["待月西廂下，迎风戶半开。","拂牆花影动，疑是玉人来。"]', '诗', 'shi', '', NULL, '荅張生 崔鶯鶯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eb5b013-93f1-48bd-a808-2793bb75920d', '寄詩', '寄诗', '5b6f838e-d5d7-4a03-b0f9-1c0d17aaaa2d', '唐', '["自從銷瘦減容光，萬轉千迴嬾下牀。","不爲傍人羞不起，爲郎憔悴却羞郎。"]', '["自從銷瘦減容光，万轉千迴嬾下牀。","不爲傍人羞不起，爲郎憔悴却羞郎。"]', '诗', 'shi', '', NULL, '寄詩 崔鶯鶯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c211667-c614-419c-97da-fd7c8d73fb6c', '告絕詩', '告絕诗', '5b6f838e-d5d7-4a03-b0f9-1c0d17aaaa2d', '唐', '["棄置今何道，當時且自親。","還將舊來意，憐取眼前人。"]', '["棄置今何道，當时且自親。","還將旧来意，怜取眼前人。"]', '诗', 'shi', '', NULL, '告絕詩 崔鶯鶯 shi');
